alse}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_basic#3','math',5,2,'u5','L03','g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',1,'mc','auto','정육면체의 면이 될 수 있는 사각형은 어느 것인가요?',ARRAY['M5-2-u5-X02']::text[],true,'{"seq":3,"concept":"M5-2-u5-C3","difficulty":1,"kind":"mc","stem":"정육면체의 면이 될 수 있는 사각형은 어느 것인가요?","options":[{"t":"네 변이 모두 3 cm이고 네 각이 모두 직각인 사각형","correct":true},{"t":"가로 3 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X02"},{"t":"네 변이 모두 3 cm이지만 직각이 없는 사각형","mis":"M5-2-u5-X02"},{"t":"윗변 2 cm, 아랫변 3 cm인 사다리꼴","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","그래서 면 6개가 모두 크기가 같은 정사각형이에요.","정답은 「네 변이 모두 3 cm이고 네 각이 모두 직각인 사각형」이에요."],"variant_rule":{"alt":[{"stem":"한 모서리의 길이가 4 cm인 정육면체의 한 면은 어떤 도형인가요?","options":[{"t":"한 변이 4 cm인 정사각형","correct":true},{"t":"가로 4 cm, 세로 8 cm인 직사각형","mis":"M5-2-u5-X07"},{"t":"한 변이 8 cm인 정사각형","mis":"M5-2-u5-X07"},{"t":"한 변이 4 cm인 삼각형","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","그래서 면 6개가 모두 크기가 같은 정사각형이에요.","정답은 「한 변이 4 cm인 정사각형」이에요."]},{"stem":"정육면체의 면에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"면 6개가 모두 크기가 같은 정사각형이다","correct":true},{"t":"면 4개만 정사각형이다","mis":"M5-2-u5-X04"},{"t":"면마다 크기가 다르다","mis":"M5-2-u5-X06"},{"t":"마주 보는 두 면만 크기가 같다","mis":"M5-2-u5-X06"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","그래서 면 6개가 모두 크기가 같은 정사각형이에요.","정답은 「면 6개가 모두 크기가 같은 정사각형이다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_basic#4','math',5,2,'u5','L03','g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',1,'mc','auto','다음 상자 가운데 정육면체 모양인 것은 어느 것인가요?',ARRAY['M5-2-u5-X06']::text[],true,'{"seq":4,"concept":"M5-2-u5-C3","difficulty":1,"kind":"mc","stem":"다음 상자 가운데 정육면체 모양인 것은 어느 것인가요?","options":[{"t":"가로 4 cm, 세로 4 cm, 높이 4 cm인 상자","correct":true},{"t":"가로 4 cm, 세로 4 cm, 높이 6 cm인 상자","mis":"M5-2-u5-X06"},{"t":"가로 4 cm, 세로 6 cm, 높이 4 cm인 상자","mis":"M5-2-u5-X06"},{"t":"가로 2 cm, 세로 4 cm, 높이 4 cm인 상자","mis":"M5-2-u5-X06"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","가로, 세로, 높이가 모두 4 cm인 상자를 찾아요.","정답은 「가로 4 cm, 세로 4 cm, 높이 4 cm인 상자」예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 상자 가운데 정육면체 모양인 것은 어느 것인가요?","options":[{"t":"가로 6 cm, 세로 6 cm, 높이 6 cm인 상자","correct":true},{"t":"가로 6 cm, 세로 6 cm, 높이 3 cm인 상자","mis":"M5-2-u5-X06"},{"t":"가로 6 cm, 세로 3 cm, 높이 6 cm인 상자","mis":"M5-2-u5-X06"},{"t":"가로 3 cm, 세로 3 cm, 높이 6 cm인 상자","mis":"M5-2-u5-X06"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","가로, 세로, 높이가 모두 6 cm인 상자를 찾아요.","정답은 「가로 6 cm, 세로 6 cm, 높이 6 cm인 상자」예요."]},{"stem":"이번에는 다른 보기예요. 다음 상자 가운데 정육면체 모양인 것은 어느 것인가요?","options":[{"t":"가로 5 cm, 세로 5 cm, 높이 5 cm인 상자","correct":true},{"t":"가로 5 cm, 세로 5 cm, 높이 2 cm인 상자","mis":"M5-2-u5-X06"},{"t":"가로 5 cm, 세로 2 cm, 높이 2 cm인 상자","mis":"M5-2-u5-X06"},{"t":"가로 2 cm, 세로 5 cm, 높이 5 cm인 상자","mis":"M5-2-u5-X06"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","가로, 세로, 높이가 모두 5 cm인 상자를 찾아요.","정답은 「가로 5 cm, 세로 5 cm, 높이 5 cm인 상자」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_basic#5','math',5,2,'u5','L03','g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'mc','auto','직육면체와 정육면체의 같은 점이 아닌 것은 어느 것인가요?',ARRAY['M5-2-u5-X18']::text[],true,'{"seq":5,"concept":"M5-2-u5-C3","difficulty":2,"kind":"mc","stem":"직육면체와 정육면체의 같은 점이 아닌 것은 어느 것인가요?","options":[{"t":"모든 모서리의 길이가 같다","correct":true},{"t":"면이 6개다","mis":"M5-2-u5-X18"},{"t":"모서리가 12개다","mis":"M5-2-u5-X18"},{"t":"꼭짓점이 8개다","mis":"M5-2-u5-X18"}],"explanation":["면은 6개, 모서리는 12개, 꼭짓점은 8개로 수가 같아요.","정육면체는 면이 모두 크기가 같은 정사각형이라 모든 모서리의 길이가 같아요.","정답은 「모든 모서리의 길이가 같다」예요."],"variant_rule":{"alt":[{"stem":"직육면체와 정육면체의 다른 점은 어느 것인가요?","options":[{"t":"면의 모양 — 정육면체는 면이 모두 정사각형이다","correct":true},{"t":"면의 수 — 정육면체는 면이 8개다","mis":"M5-2-u5-X04"},{"t":"모서리의 수 — 정육면체는 모서리가 6개다","mis":"M5-2-u5-X05"},{"t":"꼭짓점의 수 — 정육면체는 꼭짓점이 12개다","mis":"M5-2-u5-X05"}],"explanation":["면은 6개, 모서리는 12개, 꼭짓점은 8개로 수가 같아요.","정육면체는 면이 모두 크기가 같은 정사각형이라 모든 모서리의 길이가 같아요.","정답은 「면의 모양 — 정육면체는 면이 모두 정사각형이다」예요."]},{"stem":"정육면체에만 있는 성질은 어느 것인가요?","options":[{"t":"모든 면의 크기가 같다","correct":true},{"t":"면이 직사각형이다","mis":"M5-2-u5-X06"},{"t":"꼭짓점이 8개다","mis":"M5-2-u5-X18"},{"t":"평행한 면이 3쌍이다","mis":"M5-2-u5-X18"}],"explanation":["면은 6개, 모서리는 12개, 꼭짓점은 8개로 수가 같아요.","정육면체는 면이 모두 크기가 같은 정사각형이라 모든 모서리의 길이가 같아요.","정답은 「모든 면의 크기가 같다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_basic#6','math',5,2,'u5','L03','g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'sa','auto','한 모서리의 길이가 3 cm인 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C3","difficulty":2,"kind":"sa","stem":"한 모서리의 길이가 3 cm인 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","3 × 12 = 36이에요.","그래서 36 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리의 길이가 5 cm인 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","5 × 12 = 60이에요.","그래서 60 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"5 cm"]]}],"tag":false}},{"stem":"한 모서리의 길이가 7 cm인 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","7 × 12 = 84예요.","그래서 84 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"7 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_basic#7','math',5,2,'u5','L03','g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'sa','auto','가로, 세로, 높이에 쌓기나무를 2개씩 똑같이 쌓아 정육면체 모양을 만들었어요. 쌓기나무는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C3","difficulty":2,"kind":"sa","stem":"가로, 세로, 높이에 쌓기나무를 2개씩 똑같이 쌓아 정육면체 모양을 만들었어요. 쌓기나무는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["한 층에 2 × 2 = 4(개)예요.","2층이니 4 × 2 = 8이에요.","그래서 8개예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"가로, 세로, 높이에 쌓기나무를 3개씩 똑같이 쌓아 정육면체 모양을 만들었어요. 쌓기나무는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["한 층에 3 × 3 = 9(개)예요.","3층이니 9 × 3 = 27이에요.","그래서 27개예요."]},{"stem":"가로, 세로, 높이에 쌓기나무를 4개씩 똑같이 쌓아 정육면체 모양을 만들었어요. 쌓기나무는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["한 층에 4 × 4 = 16(개)예요.","4층이니 16 × 4 = 64예요.","그래서 64개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_basic#8','math',5,2,'u5','L03','g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'ox','auto','정육면체는 직육면체라고 할 수 있어요.',ARRAY['M5-2-u5-X06']::text[],true,'{"seq":8,"concept":"M5-2-u5-C3","difficulty":2,"kind":"ox","stem":"정육면체는 직육면체라고 할 수 있어요.","answer":"O","reason_options":[{"t":"정사각형은 직사각형이므로 정사각형 6개는 직사각형 6개이기도 하므로","correct":true},{"t":"이름이 다르므로","mis":"M5-2-u5-X06"}],"mis":"M5-2-u5-X06","explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「정사각형은 직사각형이므로 정사각형 6개는 직사각형 6개이기도 하므로」를 골라요."],"variant_rule":{"alt":[{"stem":"직육면체는 모두 정육면체라고 할 수 있어요.","answer":"X","reason_options":[{"t":"직육면체의 면은 정사각형이 아닐 수 있으므로","correct":true},{"t":"면이 6개로 같으므로","mis":"M5-2-u5-X06"}],"explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「직육면체의 면은 정사각형이 아닐 수 있으므로」를 골라요."]},{"stem":"정육면체는 모든 모서리의 길이가 같아요.","answer":"O","reason_options":[{"t":"면이 모두 크기가 같은 정사각형이므로","correct":true},{"t":"마주 보는 모서리만 같으므로","mis":"M5-2-u5-X06"}],"explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「면이 모두 크기가 같은 정사각형이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_basic#9','math',5,2,'u5','L03','g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',2,'mc','auto','친구가 「정육면체는 직육면체가 아니야.」라고 했어요. 바르게 고친 말은 어느 것인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X04']::text[],true,'{"seq":9,"concept":"M5-2-u5-C3","difficulty":2,"kind":"mc","stem":"친구가 「정육면체는 직육면체가 아니야.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"정사각형은 직사각형이므로 정육면체는 직육면체라고 할 수 있다","correct":true},{"t":"맞다 — 이름이 다르다","mis":"M5-2-u5-X06"},{"t":"직육면체는 모두 정육면체다","mis":"M5-2-u5-X06"},{"t":"면의 수가 달라서 견줄 수 없다","mis":"M5-2-u5-X04"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","정육면체는 직육면체의 한 종류이고, 면·모서리·꼭짓점의 수는 같아요.","정답은 「정사각형은 직사각형이므로 정육면체는 직육면체라고 할 수 있다」예요."],"variant_rule":{"alt":[{"stem":"친구가 「직육면체는 모두 정육면체야.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"직육면체의 면은 정사각형이 아닐 수도 있으므로 모두 정육면체는 아니다","correct":true},{"t":"맞다 — 면이 6개로 같다","mis":"M5-2-u5-X06"},{"t":"정육면체는 직육면체가 아니다","mis":"M5-2-u5-X06"},{"t":"직육면체는 꼭짓점이 더 많다","mis":"M5-2-u5-X04"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","정육면체는 직육면체의 한 종류이고, 면·모서리·꼭짓점의 수는 같아요.","정답은 「직육면체의 면은 정사각형이 아닐 수도 있으므로 모두 정육면체는 아니다」예요."]},{"stem":"친구가 「정육면체는 모서리가 짧아서 모서리 수가 직육면체보다 적어.」라고 했어요. 바르게 고친 말은 어느 것인가요?","options":[{"t":"정육면체도 모서리가 12개로 직육면체와 같다","correct":true},{"t":"맞다 — 크기가 작으면 모서리가 적다","mis":"M5-2-u5-X04"},{"t":"정육면체는 모서리가 6개다","mis":"M5-2-u5-X05"},{"t":"정육면체는 모서리가 24개다","mis":"M5-2-u5-X05"}],"explanation":["정사각형은 네 각이 직각이므로 직사각형이에요.","정육면체는 직육면체의 한 종류이고, 면·모서리·꼭짓점의 수는 같아요.","정답은 「정육면체도 모서리가 12개로 직육면체와 같다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_basic#10','math',5,2,'u5','L03','g5_2_math_u5_L03_basic','lesson_basic','M5-2-u5-C3',3,'sa','auto','모서리의 길이가 15 cm, 7 cm, 7 cm인 직육면체 모양 빵을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"모서리의 길이가 15 cm, 7 cm, 7 cm인 직육면체 모양 빵을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 7 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 7 cm예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"모서리의 길이가 12 cm, 9 cm, 10 cm인 직육면체 모양 두부를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 9 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 9 cm예요."]},{"stem":"모서리의 길이가 8 cm, 11 cm, 6 cm인 직육면체 모양 나무 토막을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 6 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#1','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',2,'sa','auto','모든 모서리의 길이의 합이 48 cm인 정육면체가 있어요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C3","difficulty":2,"kind":"sa","stem":"모든 모서리의 길이의 합이 48 cm인 정육면체가 있어요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","48 ÷ 12 = 4예요.","그래서 4 cm예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"모든 모서리의 길이의 합이 72 cm인 정육면체가 있어요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","72 ÷ 12 = 6이에요.","그래서 6 cm예요."]},{"stem":"모든 모서리의 길이의 합이 96 cm인 정육면체가 있어요. 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","96 ÷ 12 = 8이에요.","그래서 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#2','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',2,'ox','auto','정육면체의 꼭짓점은 직육면체의 꼭짓점보다 적어요.',ARRAY['M5-2-u5-X04']::text[],true,'{"seq":2,"concept":"M5-2-u5-C3","difficulty":2,"kind":"ox","stem":"정육면체의 꼭짓점은 직육면체의 꼭짓점보다 적어요.","answer":"X","reason_options":[{"t":"둘 다 꼭짓점이 8개이므로","correct":true},{"t":"정육면체가 더 작은 도형이므로","mis":"M5-2-u5-X04"}],"mis":"M5-2-u5-X04","explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「둘 다 꼭짓점이 8개이므로」를 골라요."],"variant_rule":{"alt":[{"stem":"한 모서리가 5 cm인 정육면체의 모든 모서리의 길이의 합은 60 cm예요.","answer":"O","reason_options":[{"t":"5 × 12 = 60이므로","correct":true},{"t":"5 × 6 = 30이므로","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「5 × 12 = 60이므로」를 골라요."]},{"stem":"면 하나가 정사각형인 직육면체는 정육면체예요.","answer":"X","reason_options":[{"t":"면 6개가 모두 정사각형이어야 정육면체이므로","correct":true},{"t":"정사각형 면이 하나라도 있으면 되므로","mis":"M5-2-u5-X06"}],"explanation":["정육면체의 뜻과 성질을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「면 6개가 모두 정사각형이어야 정육면체이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#3','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'error','auto','친구들이 정육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X06','M5-2-u5-X04']::text[],true,'{"seq":3,"concept":"M5-2-u5-C3","difficulty":3,"kind":"error","stem":"친구들이 정육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「정육면체는 면이 정사각형이니까 직육면체가 아니야.」","correct":true,"mis_target":"M5-2-u5-X06"},{"t":"서연 — 「정육면체는 모서리의 길이가 모두 같아.」","mis":"M5-2-u5-X06"},{"t":"지호 — 「정육면체의 꼭짓점은 8개야.」","mis":"M5-2-u5-X04"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 직육면체예요.","모서리 12개의 길이가 모두 같아요.","민준의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 정육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「직육면체도 모든 모서리의 길이가 같아.」","correct":true,"mis_target":"M5-2-u5-X06"},{"t":"나린 — 「정육면체는 정사각형 6개로 둘러싸여 있어.」","mis":"M5-2-u5-X02"},{"t":"유진 — 「정육면체의 모서리는 12개야.」","mis":"M5-2-u5-X05"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 직육면체예요.","모서리 12개의 길이가 모두 같아요.","가온의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 정육면체에 대해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「한 모서리가 3 cm인 정육면체의 모서리 길이의 합은 18 cm야.」","correct":true,"mis_target":"M5-2-u5-X07"},{"t":"라온 — 「정육면체는 직육면체라고 할 수 있어.」","mis":"M5-2-u5-X06"},{"t":"예준 — 「정육면체의 면은 6개야.」","mis":"M5-2-u5-X04"}],"explanation":["정육면체는 정사각형 6개로 둘러싸인 직육면체예요.","모서리 12개의 길이가 모두 같아요.","여울의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#4','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'sa','auto','모서리의 길이가 20 cm, 14 cm, 16 cm인 직육면체 모양 케이크를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"모서리의 길이가 20 cm, 14 cm, 16 cm인 직육면체 모양 케이크를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 14 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 14 cm예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"모서리의 길이가 9 cm, 13 cm, 10 cm인 직육면체 모양 치즈를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 9 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 9 cm예요."]},{"stem":"모서리의 길이가 18 cm, 12 cm, 15 cm인 직육면체 모양 스펀지를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 12 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#5','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'sa','auto','가로, 세로, 높이에 쌓기나무를 5개씩 똑같이 쌓아 정육면체 모양을 만들었어요. 쌓기나무는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"가로, 세로, 높이에 쌓기나무를 5개씩 똑같이 쌓아 정육면체 모양을 만들었어요. 쌓기나무는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["125"],"explanation":["한 층에 5 × 5 = 25(개)예요.","5층이니 25 × 5 = 125예요.","그래서 125개예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"가로, 세로, 높이에 쌓기나무를 6개씩 똑같이 쌓아 정육면체 모양을 만들었어요. 쌓기나무는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["216"],"explanation":["한 층에 6 × 6 = 36(개)예요.","6층이니 36 × 6 = 216이에요.","그래서 216개예요."]},{"stem":"가로, 세로, 높이에 쌓기나무를 7개씩 똑같이 쌓아 정육면체 모양을 만들었어요. 쌓기나무는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["343"],"explanation":["한 층에 7 × 7 = 49(개)예요.","7층이니 49 × 7 = 343이에요.","그래서 343개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#6','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'sa','auto','가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체와 한 모서리가 4 cm인 정육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체와 한 모서리가 4 cm인 정육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["직육면체: 4 × 4 + 3 × 4 + 2 × 4 = 36이에요.","정육면체: 4 × 12 = 48이에요.","차는 48 − 36 = 12(cm)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체와 한 모서리가 3 cm인 정육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["직육면체: 5 × 4 + 3 × 4 + 2 × 4 = 40이에요.","정육면체: 3 × 12 = 36이에요.","차는 40 − 36 = 4(cm)예요."]},{"stem":"가로 6 cm, 세로 3 cm, 높이 3 cm인 직육면체와 한 모서리가 5 cm인 정육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["직육면체: 6 × 4 + 3 × 4 + 3 × 4 = 48이에요.","정육면체: 5 × 12 = 60이에요.","차는 60 − 48 = 12(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#7','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',3,'sa','auto','한 모서리의 길이가 9 cm인 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"한 모서리의 길이가 9 cm인 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","9 × 12 = 108이에요.","그래서 108 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"9 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리의 길이가 11 cm인 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["132"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","11 × 12 = 132예요.","그래서 132 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"11 cm"]]}],"tag":false}},{"stem":"한 모서리의 길이가 12 cm인 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["144"],"explanation":["정육면체는 모서리 12개의 길이가 모두 같아요.","12 × 12 = 144예요.","그래서 144 cm예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33,111],"12 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#8','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',4,'sa','auto','쌓기나무 64개를 남김없이 써서 가로, 세로, 높이에 같은 개수씩 쌓아 정육면체 모양을 만들었어요. 한 줄에 쌓기나무를 몇 개씩 놓았나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C3","difficulty":4,"kind":"sa","stem":"쌓기나무 64개를 남김없이 써서 가로, 세로, 높이에 같은 개수씩 쌓아 정육면체 모양을 만들었어요. 한 줄에 쌓기나무를 몇 개씩 놓았나요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 줄에 □개씩이면 □ × □ × □개가 들어요.","4 × 4 × 4 = 64예요.","그래서 한 줄에 4개씩이에요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"쌓기나무 125개를 남김없이 써서 가로, 세로, 높이에 같은 개수씩 쌓아 정육면체 모양을 만들었어요. 한 줄에 쌓기나무를 몇 개씩 놓았나요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 줄에 □개씩이면 □ × □ × □개가 들어요.","5 × 5 × 5 = 125예요.","그래서 한 줄에 5개씩이에요."]},{"stem":"쌓기나무 216개를 남김없이 써서 가로, 세로, 높이에 같은 개수씩 쌓아 정육면체 모양을 만들었어요. 한 줄에 쌓기나무를 몇 개씩 놓았나요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 줄에 □개씩이면 □ × □ × □개가 들어요.","6 × 6 × 6 = 216이에요.","그래서 한 줄에 6개씩이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#9','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',4,'sa','auto','가로 7 cm, 세로 4 cm, 높이 3 cm인 직육면체와 한 모서리가 6 cm인 정육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C3","difficulty":4,"kind":"sa","stem":"가로 7 cm, 세로 4 cm, 높이 3 cm인 직육면체와 한 모서리가 6 cm인 정육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["직육면체: 7 × 4 + 4 × 4 + 3 × 4 = 56이에요.","정육면체: 6 × 12 = 72예요.","차는 72 − 56 = 16(cm)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"가로 8 cm, 세로 5 cm, 높이 2 cm인 직육면체와 한 모서리가 4 cm인 정육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["직육면체: 8 × 4 + 5 × 4 + 2 × 4 = 60이에요.","정육면체: 4 × 12 = 48이에요.","차는 60 − 48 = 12(cm)예요."]},{"stem":"가로 9 cm, 세로 6 cm, 높이 3 cm인 직육면체와 한 모서리가 7 cm인 정육면체가 있어요. 두 도형의 모든 모서리의 길이의 합의 차는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["직육면체: 9 × 4 + 6 × 4 + 3 × 4 = 72예요.","정육면체: 7 × 12 = 84예요.","차는 84 − 72 = 12(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L03_challenge#10','math',5,2,'u5','L03','g5_2_math_u5_L03_challenge','lesson_challenge','M5-2-u5-C3',4,'essay','teacher','「정육면체는 직육면체라고 할 수 있다.」와 「직육면체는 정육면체라고 할 수 있다.」 가운데 맞는 말을 고르고, 두 말이 맞는지 틀린지를 각각 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C3","difficulty":4,"kind":"essay","stem":"「정육면체는 직육면체라고 할 수 있다.」와 「직육면체는 정육면체라고 할 수 있다.」 가운데 맞는 말을 고르고, 두 말이 맞는지 틀린지를 각각 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「정육면체는 직육면체라고 할 수 있다.」가 맞다. 정사각형은 네 각이 직각이므로 직사각형이고, 정사각형 6개로 둘러싸인 정육면체는 직사각형 6개로 둘러싸인 직육면체이기도 하다. 그러나 직육면체의 면은 정사각형이 아닌 직사각형일 수 있으므로 직육면체를 모두 정육면체라고 할 수는 없다.","scoring_points":["정육면체는 직육면체라고 할 수 있다고 썼는가","정사각형은 직사각형이라는 까닭을 썼는가","직육면체의 면은 정사각형이 아닐 수 있어 거꾸로는 안 된다고 썼는가"]},"explanation":["정사각형은 직사각형이에요.","그래서 정육면체는 직육면체예요.","직육면체는 면이 정사각형이 아닐 수 있어 정육면체라고 할 수 없어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_basic#1','math',5,2,'u5','L04','g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',1,'mc','auto','직육면체의 겨냥도에서 보이지 않는 모서리는 어떻게 그리나요?',ARRAY['M5-2-u5-X09','M5-2-u5-X10']::text[],true,'{"seq":1,"concept":"M5-2-u5-C4","difficulty":1,"kind":"mc","stem":"직육면체의 겨냥도에서 보이지 않는 모서리는 어떻게 그리나요?","options":[{"t":"점선으로 그린다","correct":true},{"t":"실선으로 그린다","mis":"M5-2-u5-X09"},{"t":"그리지 않는다","mis":"M5-2-u5-X09"},{"t":"보이는 모서리보다 굵게 그린다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「점선으로 그린다」예요."],"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 보이는 모서리는 어떻게 그리나요?","options":[{"t":"실선으로 그린다","correct":true},{"t":"점선으로 그린다","mis":"M5-2-u5-X09"},{"t":"그리지 않는다","mis":"M5-2-u5-X09"},{"t":"색칠한다","mis":"M5-2-u5-X03"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「실선으로 그린다」예요."]},{"stem":"보이는 모서리는 실선, 보이지 않는 모서리는 점선으로 나타낸 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 겨냥도","correct":true},{"t":"직육면체의 전개도","mis":"M5-2-u5-X16"},{"t":"평면도형","mis":"M5-2-u5-X01"},{"t":"직사각형","mis":"M5-2-u5-X02"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「직육면체의 겨냥도」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_basic#2','math',5,2,'u5','L04','g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',1,'sa','auto','직육면체 모양 캠핑 상자의 겨냥도예요. 실선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u5-C4","difficulty":1,"kind":"sa","stem":"직육면체 모양 캠핑 상자의 겨냥도예요. 실선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","보이는 모서리 9개를 실선으로 그려요.","그래서 9개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 서랍의 겨냥도예요. 점선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","보이지 않는 모서리 3개를 점선으로 그려요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 선물 상자의 겨냥도예요. 보이는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","앞, 위, 옆의 면 3개가 보여요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
