INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_basic#6','math',5,2,'u5','L04','g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',2,'sa','auto','직육면체의 겨냥도에서 보이는 면, 모서리, 꼭짓점의 수를 모두 더하면 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C4","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도에서 보이는 면, 모서리, 꼭짓점의 수를 모두 더하면 얼마인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["보이는 것은 면 3, 모서리 9, 꼭짓점 7 — 보이지 않는 것은 면 3, 모서리 3, 꼭짓점 1이에요.","3 + 9 + 7 = 19예요.","그래서 19예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 겨냥도에서 보이지 않는 면, 모서리, 꼭짓점의 수를 모두 더하면 얼마인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["보이는 것은 면 3, 모서리 9, 꼭짓점 7 — 보이지 않는 것은 면 3, 모서리 3, 꼭짓점 1이에요.","3 + 3 + 1 = 7이에요.","그래서 7이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 실선으로 그린 모서리와 점선으로 그린 모서리의 수를 모두 더하면 얼마인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["보이는 것은 면 3, 모서리 9, 꼭짓점 7 — 보이지 않는 것은 면 3, 모서리 3, 꼭짓점 1이에요.","9 + 3 = 12예요.","그래서 12예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[110.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[88,66.0,