INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_basic#9','math',5,2,'u5','L04','g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',2,'sa','auto','직육면체의 겨냥도를 그리고 있어요. 지금까지 실선을 5개 그렸어요. 겨냥도를 완성하려면 실선을 몇 개 더 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C4","difficulty":2,"kind":"sa","stem":"직육면체의 겨냥도를 그리고 있어요. 지금까지 실선을 5개 그렸어요. 겨냥도를 완성하려면 실선을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["겨냥도에는 실선 9개, 점선 3개가 있어요.","모두 그려야 할 실선은 9개예요.","9 − 5 = 4(개)예요."],"mis":"M5-2-u5-X10","variant_rule":{"alt":[{"stem":"직육면체의 겨냥도를 그리고 있어요. 지금까지 실선을 7개 그렸어요. 겨냥도를 완성하려면 선(실선과 점선)을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["겨냥도에는 실선 9개, 점선 3개가 있어요.","모두 그려야 할 선은 12개예요.","12 − 7 = 5(개)예요."]},{"stem":"직육면체의 겨냥도를 그리고 있어요. 지금까지 실선을 4개 그렸어요. 겨냥도를 완성하려면 실선을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["겨냥도에는 실선 9개, 점선 3개가 있어요.","모두 그려야 할 실선은 9개예요.","9 − 4 = 5(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_basic#10','math',5,2,'u5','L04','g5_2_math_u5_L04_basic','lesson_basic','M5-2-u5-C4',3,'mc','auto','겨냥도에서 보이지 않는 모서리를 점선으로 그리는 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['M5-2-u5-X09','M5-2-u5-X10']::text[],true,'{"seq":10,"concept":"M5-2-u5-C4","difficulty":3,"kind":"mc","stem":"겨냥도에서 보이지 않는 모서리를 점선으로 그리는 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"그림만 보고도 다른 사람이 입체의 모양을 알아맞힐 수 있게 하려고","correct":true},{"t":"그리기가 쉬워서","mis":"M5-2-u5-X09"},{"t":"선의 수를 줄이려고","mis":"M5-2-u5-X10"},{"t":"보이지 않는 면을 지우려고","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 내가 아는 것을 적는 그림이 아니라 남이 알아볼 수 있는 그림이에요.","숨은 모서리는 점선으로 드러내야 앞뒤도 알고 모서리 12개도 다 보여요.","정답은 「그림만 보고도 다른 사람이 입체의 모양을 알아맞힐 수 있게 하려고」예요."],"variant_rule":{"alt":[{"stem":"보이지 않는 모서리를 실선으로 그리면 어떤 점이 불편한가요?","options":[{"t":"어느 쪽이 앞이고 어느 쪽이 뒤인지 알 수 없다","correct":true},{"t":"모서리가 12개보다 많아진다","mis":"M5-2-u5-X10"},{"t":"면이 7개가 된다","mis":"M5-2-u5-X10"},{"t":"불편한 점이 없다","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 내가 아는 것을 적는 그림이 아니라 남이 알아볼 수 있는 그림이에요.","숨은 모서리는 점선으로 드러내야 앞뒤도 알고 모서리 12개도 다 보여요.","정답은 「어느 쪽이 앞이고 어느 쪽이 뒤인지 알 수 없다」예요."]},{"stem":"보이지 않는 모서리를 아예 그리지 않으면 어떤 점이 잘못되나요?","options":[{"t":"모서리가 12개가 되지 않아 직육면체를 다 나타내지 못한다","correct":true},{"t":"앞뒤가 바뀐다","mis":"M5-2-u5-X09"},{"t":"면이 정사각형이 된다","mis":"M5-2-u5-X02"},{"t":"잘못된 점이 없다","mis":"M5-2-u5-X09"}],"explanation":["겨냥도는 내가 아는 것을 적는 그림이 아니라 남이 알아볼 수 있는 그림이에요.","숨은 모서리는 점선으로 드러내야 앞뒤도 알고 모서리 12개도 다 보여요.","정답은 「모서리가 12개가 되지 않아 직육면체를 다 나타내지 못한다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_challenge#1','math',5,2,'u5','L04','g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',2,'sa','auto','직육면체 모양 캠핑 상자의 겨냥도예요. 보이지 않는 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C4","difficulty":2,"kind":"sa","stem":"직육면체 모양 캠핑 상자의 겨냥도예요. 보이지 않는 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","점선으로 그린 모서리가 보이지 않는 모서리예요.","그래서 3개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 선물 상자의 겨냥도예요. 보이는 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","실선으로 그린 모서리가 보이는 모서리예요.","그래서 9개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 서랍의 겨냥도예요. 보이지 않는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","뒤, 아래, 다른 옆의 면 3개는 보이지 않아요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ",