INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_challenge#5','math',5,2,'u5','L04','g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',3,'mc','auto','과일 상자 모양을 그린 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X10']::text[],true,'{"seq":5,"concept":"M5-2-u5-C4","difficulty":3,"kind":"mc","stem":"과일 상자 모양을 그린 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?","options":[{"t":"보이지 않는 모서리를 그리지 않았다","correct":true},{"t":"보이지 않는 모서리를 실선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"보이는 모서리를 점선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"면을 7개 그렸다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 어떤 모서리가 어떻게 그려졌는지 살펴봐요.","잘못된 까닭은 「보이지 않는 모서리를 그리지 않았다」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[132.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[110,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"벽돌 모양을 그린 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?","options":[{"t":"보이는 모서리를 점선으로 그렸다","correct":true},{"t":"보이지 않는 모서리를 실선으로 그렸다","mis":"M5-2-u5-X09"},{"t":"보이지 않는 모서리를 그리지 않았다","mis":"M5-2-u5-X09"},{"t":"면을 7개 그렸다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 어떤 모서리가 어떻게 그려졌는지 살펴봐요.","잘못된 까닭은 「보이는 모서리를 점선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":44.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,22,"ne"],"ㅇ":[110.0,22,"e"],"ㅂ":[0,44.0,"sw"],"ㅅ":[88,44.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄴ","ㄷ"],["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"도시락통 모양을 그린 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?","options":[{"t":"보이지 않는 모서리를 실선으로 그렸다","correct":true},{"t":"보이지 않는 모서리를 그리지 않았다","mis":"M5-2-u5-X10"},{"t":"보이는 모서리를 점선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"면을 7개 그렸다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 어떤 모서리가 어떻게 그려졌는지 살펴봐요.","잘못된 까닭은 「보이지 않는 모서리를 실선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_challenge#6','math',5,2,'u5','L04','g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',3,'sa','auto','정육면체의 모든 모서리의 길이의 합이 120 cm예요. 이 정육면체의 겨냥도에서 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"정육면체의 모든 모서리의 길이의 합이 120 cm예요. 이 정육면체의 겨냥도에서 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["한 모서리는 120 ÷ 12 = 10(cm)예요.","보이지 않는 모서리는 3개예요.","10 × 3 = 30(cm)예요."],"mis":"M5-2-u5-X10","variant_rule":{"alt":[{"stem":"정육면체의 모든 모서리의 길이의 합이 96 cm예요. 이 정육면체의 겨냥도에서 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["한 모서리는 96 ÷ 12 = 8(cm)예요.","보이지 않는 모서리는 3개예요.","8 × 3 = 24(cm)예요."]},{"stem":"정육면체의 모든 모서리의 길이의 합이 144 cm예요. 이 정육면체의 겨냥도에서 보이지 않는 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["한 모서리는 144 ÷ 12 = 12(cm)예요.","보이지 않는 모서리는 3개예요.","12 × 3 = 36(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_challenge#7','math',5,2,'u5','L04','g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',3,'sa','auto','직육면체의 겨냥도를 그리고 있어요. 지금까지 실선을 3개 그렸어요. 겨냥도를 완성하려면 선(실선과 점선)을 몇 개 더 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"직육면체의 겨냥도를 그리고 있어요. 지금까지 실선을 3개 그렸어요. 겨냥도를 완성하려면 선(실선과 점선)을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["겨냥도에는 실선 9개, 점선 3개가 있어요.","모두 그려야 할 선은 12개예요.","12 − 3 = 9(개)예요."],"mis":"M5-2-u5-X10","variant_rule":{"alt":[{"stem":"직육면체의 겨냥도를 그리고 있어요. 지금까지 실선을 6개 그렸어요. 겨냥도를 완성하려면 선(실선과 점선)을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["겨냥도에는 실선 9개, 점선 3개가 있어요.","모두 그려야 할 선은 12개예요.","12 − 6 = 6(개)예요."]},{"stem":"직육면체의 겨냥도를 그리고 있어요. 지금까지 실선을 8개 그렸어요. 겨냥도를 완성하려면 선(실선과 점선)을 몇 개 더 그려야 하나요? 숫자로 쓰세요.","answer":["4"],"explanation":["겨냥도에는 실선 9개, 점선 3개가 있어요.","모두 그려야 할 선은 12개예요.","12 − 8 = 4(개)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_challenge#8','math',5,2,'u5','L04','g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',4,'sa','auto','가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C4","difficulty":4,"kind":"sa","stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["모든 모서리의 합은 5 × 4 + 3 × 4 + 4 × 4 = 48이에요.","점선 3개는 5 + 3 + 4 = 12예요.","실선은 48 − 12 = 36(cm)예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["모든 모서리의 합은 6 × 4 + 2 × 4 + 3 × 4 = 44예요.","점선 3개는 6 + 2 + 3 = 11이에요.","실선은 44 − 11 = 33(cm)예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[132,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[132,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[66.0,96.0],"6 cm"],[[159.0,81.0],"2 cm"],[[114,55.0],"3 cm"]]}],"tag":false}},{"stem":"가로 4 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["모든 모서리의 합은 4 × 4 + 4 × 4 + 5 × 4 = 52예요.","점선 3개는 4 + 4 + 5 = 13이에요.","실선은 52 − 13 = 39(cm)예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[88,44.0,"sw"],"ㅁ":[44.0,110,"ne"],"ㅇ":[132.0,110,"e"],"ㅂ":[0,154.0,"sw"],"ㅅ":[88,154.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,162.0],"4 cm"],[[126.0,136.0],"4 cm"],[[70,99.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_challenge#9','math',5,2,'u5','L04','g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',4,'sa','auto','정육면체의 겨냥도에서 실선으로 그린 모서리의 길이의 합이 54 cm예요. 이 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C4","difficulty":4,"kind":"sa","stem":"정육면체의 겨냥도에서 실선으로 그린 모서리의 길이의 합이 54 cm예요. 이 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["실선은 보이는 모서리 9개예요.","한 모서리는 54 ÷ 9 = 6(cm)예요.","모든 모서리는 6 × 12 = 72(cm)예요."],"mis":"M5-2-u5-X10","variant_rule":{"alt":[{"stem":"정육면체의 겨냥도에서 실선으로 그린 모서리의 길이의 합이 72 cm예요. 이 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["96"],"explanation":["실선은 보이는 모서리 9개예요.","한 모서리는 72 ÷ 9 = 8(cm)예요.","모든 모서리는 8 × 12 = 96(cm)예요."]},{"stem":"정육면체의 겨냥도에서 실선으로 그린 모서리의 길이의 합이 45 cm예요. 이 정육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["실선은 보이는 모서리 9개예요.","한 모서리는 45 ÷ 9 = 5(cm)예요.","모든 모서리는 5 × 12 = 60(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L04_challenge#10','math',5,2,'u5','L04','g5_2_math_u5_L04_challenge','lesson_challenge','M5-2-u5-C4',4,'essay','teacher','친구가 그린 그림이에요. 이 그림이 직육면체의 겨냥도로 알맞은지 판단하고, 알맞지 않다면 어떻게 고쳐야 하는지와 겨냥도를 그렇게 그리는 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C4","difficulty":4,"kind":"essay","stem":"친구가 그린 그림이에요. 이 그림이 직육면체의 겨냥도로 알맞은지 판단하고, 알맞지 않다면 어떻게 고쳐야 하는지와 겨냥도를 그렇게 그리는 까닭을 쓰세요.","answer_guide":{"answer":"예: 알맞지 않다. 보이지 않는 모서리 3개를 실선으로 그려서 어느 쪽이 앞인지 알 수 없다. 보이지 않는 모서리 3개는 점선으로 고쳐 그려야 한다. 겨냥도는 그림만 보고도 다른 사람이 입체의 모양을 알아맞힐 수 있게 그리는 그림이기 때문이다.","scoring_points":["알맞지 않다고 판단했는가","보이지 않는 모서리 3개를 점선으로 고친다고 썼는가","다른 사람이 입체를 알아볼 수 있게 하려는 까닭을 썼는가"]},"explanation":["보이는 모서리 9개는 실선이에요.","보이지 않는 모서리 3개는 점선이어야 해요.","그래야 그림만 보고도 앞뒤를 알 수 있어요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L05_basic#1','math',5,2,'u5','L05','g5_2_math_u5_L05_basic','lesson_basic','M5-2-u5-C5',1,'sa','auto','직육면체에서 서로 평행한 면은 모두 몇 쌍인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C5","difficulty":1,"kind":"sa","stem":"직육면체에서 서로 평행한 면은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","앞·뒤, 위·아래, 왼쪽·오른쪽 — 평행한 면이 3쌍이에요.","그래서 3이에요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 한 밑면과 수직인 면은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","밑면과 평행한 다른 밑면을 뺀 나머지 6 − 2 = 4(개)가 수직이에요.","그래서 4예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에서 한 면과 평행한 면은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","마주 보는 면 하나만 평행해요.","그래서 1이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
