INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L05_basic#8','math',5,2,'u5','L05','g5_2_math_u5_L05_basic','lesson_basic','M5-2-u5-C5',2,'ox','auto','직육면체에서 옆면끼리는 모두 평행해요.',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":8,"concept":"M5-2-u5-C5","difficulty":2,"kind":"ox","stem":"직육면체에서 옆면끼리는 모두 평행해요.","answer":"X","reason_options":[{"t":"이웃한 옆면끼리는 수직으로 만나므로","correct":true},{"t":"옆면은 모두 같은 쪽에 있으므로","mis":"M5-2-u5-X12"}],"mis":"M5-2-u5-X12","explanation":["만나는 두 면은 수직, 만나지 않는 두 면은 평행해요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「이웃한 옆면끼리는 수직으로 만나므로」를 골라요."],"variant_rule":{"alt":[{"stem":"직육면체에서 평행한 면은 3쌍이에요.","answer":"O","reason_options":[{"t":"마주 보는 면이 앞·뒤, 위·아래, 왼쪽·오른쪽 3쌍이므로","correct":true},{"t":"평행한 면은 6쌍이므로","mis":"M5-2-u5-X13"}],"explanation":["만나는 두 면은 수직, 만나지 않는 두 면은 평행해요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「마주 보는 면이 앞·뒤, 위·아래, 왼쪽·오른쪽 3쌍이므로」를 골라요."]},{"stem":"바닥에 닿은 면만 밑면이 될 수 있어요.","answer":"X","reason_options":[{"t":"밑면은 위치가 아니라 평행한 관계로 정하므로","correct":true},{"t":"밑면은 밑에 있어야 하므로","mis":"M5-2-u5-X11"}],"explanation":["만나는 두 면은 수직, 만나지 않는 두 면은 평행해요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「밑면은 위치가 아니라 평행한 관계로 정하므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L05_basic#9','math',5,2,'u5','L05','g5_2_math_u5_L05_basic','lesson_basic','M5-2-u5-C5',2,'sa','auto','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체예요. 면 ㅁㅂㅅㅇ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C5","difficulty":2,"kind":"sa","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체예요. 면 ㅁㅂㅅㅇ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["다른 밑면은 면 ㄱㄴㄷㄹ이에요.","이 면은 4 cm, 2 cm인 직사각형이에요.","4 + 2 + 4 + 2 = 12예요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,96.0],"4 cm"],[[115.0,81.0],"2 cm"],[[70,55.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체예요. 면 ㄱㄴㄷㄹ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["다른 밑면은 면 ㅁㅂㅅㅇ이에요.","이 면은 5 cm, 3 cm인 직사각형이에요.","5 + 3 + 5 + 3 = 16이에요."],"asset":{"type":"geo","items":[{"w":143.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[143.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[110,77.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,85.0],"5 cm"],[[142.5,64.5],"3 cm"],[[92,55.0],"2 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 4 cm인 직육면체예요. 면 ㅁㅂㅅㅇ이 밑면일 때 다른 밑면의 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["다른 밑면은 면 ㄱㄴㄷㄹ