INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L05_challenge#6','math',5,2,'u5','L05','g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',3,'mc','auto','직육면체에서 옆면끼리의 관계를 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":6,"concept":"M5-2-u5-C5","difficulty":3,"kind":"mc","stem":"직육면체에서 옆면끼리의 관계를 바르게 말한 것은 어느 것인가요?","options":[{"t":"이웃한 옆면끼리는 수직이고 마주 보는 옆면끼리는 평행하다","correct":true},{"t":"옆면끼리는 모두 평행하다","mis":"M5-2-u5-X12"},{"t":"옆면끼리는 모두 수직이다","mis":"M5-2-u5-X12"},{"t":"옆면끼리는 만나지 않는다","mis":"M5-2-u5-X12"}],"explanation":["직육면체에서 만나는 두 면은 직각으로 만나요 — 수직.","마주 보아 만나지 않는 두 면은 평행해요.","정답은 「이웃한 옆면끼리는 수직이고 마주 보는 옆면끼리는 평행하다」예요."],"variant_rule":{"alt":[{"stem":"직육면체에서 만나는 두 면은 어떻게 만나나요?","options":[{"t":"수직으로 만난다","correct":true},{"t":"평행하게 만난다","mis":"M5-2-u5-X12"},{"t":"만나지 않는다","mis":"M5-2-u5-X12"},{"t":"비스듬히 만난다","mis":"M5-2-u5-X12"}],"explanation":["직육면체에서 만나는 두 면은 직각으로 만나요 — 수직.","마주 보아 만나지 않는 두 면은 평행해요.","정답은 「수직으로 만난다」예요."]},{"stem":"직육면체의 한 면에 삼각자의 직각을 대었더니 이웃한 면과 딱 맞았어요. 두 면의 관계는 무엇인가요?","options":[{"t":"수직이다","correct":true},{"t":"평행하다","mis":"M5-2-u5-X12"},{"t":"합동이다","mis":"M5-2-u5-X03"},{"t":"같은 면이다","mis":"M5-2-u5-X03"}],"explanation":["직육면체에서 만나는 두 면은 직각으로 만나요 — 수직.","마주 보아 만나지 않는 두 면은 평행해요.","정답은 「수직이다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L05_challenge#7','math',5,2,'u5','L05','g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',3,'mc','auto','직육면체에서 밑면이 될 수 있는 면의 짝은 어느 것인가요?',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":7,"concept":"M5-2-u5-C5","difficulty":3,"kind":"mc","stem":"직육면체에서 밑면이 될 수 있는 면의 짝은 어느 것인가요?","options":[{"t":"면 ㄴㅂㅅㄷ과 면 ㄱㅁㅇㄹ","correct":true},{"t":"면 ㄱㄴㄷㄹ과 면 ㄴㅂㅅㄷ","mis":"M5-2-u5-X12"},{"t":"면 ㄱㅁㅂㄴ과 면 ㄱㄴㄷㄹ","mis":"M5-2-u5-X12"},{"t":"면 ㄷㅅㅇㄹ과 면 ㅁㅂㅅㅇ","mis":"M5-2-u5-X12"}],"explanation":["밑면은 놓인 자리가 아니라 평행한 관계로 정해요.","평행한 두 면은 어느 쌍이든 밑면이 될 수 있어요.","정답은 「면 ㄴㅂㅅㄷ과 면 ㄱㅁㅇㄹ」예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"과일 가게에서 상자를 눕혀 놓았어요. 옆에 서 있는 두 면은 서로 평행해요. 이 두 면은 밑면이 될 수 있나요?","options":[{"t":"될 수 있다 — 서로 평행하다","correct":true},{"t":"될 수 없다 — 밑에 있지 않다","mis":"M5-2-u5-X11"},{"t":"될 수 없다 — 크기가 작다","mis":"M5-2-u5-X11"},{"t":"될 수 있다 — 서로 수직이다","mis":"M5-2-u5-X12"}],"explanation":["밑면은 놓인 자리가 아니라 평행한 관계로 정해요.","평행한 두 면은 어느 쌍이든 밑면이 될 수 있어요.","정답은 「될 수 있다 — 서로 평행하다」예요."],"asset":null},{"stem":"직육면체에서 밑면을 정하는 기준으로 알맞은 것은 어느 것인가요?","options":[{"t":"서로 평행한 두 면이면 밑면이 될 수 있다","correct":true},{"t":"바닥에 닿아 있는 면만 밑면이다","mis":"M5-2-u5-X11"},{"t":"가장 넓은 두 면만 밑면이다","mis":"M5-2-u5-X11"},{"t":"서로 만나는 두 면이 밑면이다","mis":"M5-2-u5-X12"}],"explanation":["밑면은 놓인 자리가 아니라 평행한 관계로 정해요.","평행한 두 면은 어느 쌍이든 밑면이 될 수 있어요.","정답은 「서로 평행한 두 면이면 밑면이 될 수 있다」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=