INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L05_challenge#8','math',5,2,'u5','L05','g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',4,'sa','auto','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체예요. 면 ㄱㄴㄷㄹ이 밑면일 때 옆면 4개의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C5","difficulty":4,"kind":"sa","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체예요. 면 ㄱㄴㄷㄹ이 밑면일 때 옆면 4개의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["옆면은 가로 × 높이인 면 2개와 세로 × 높이인 면 2개예요.","4 × 3 × 2 + 2 × 3 × 2 = 36이에요.","그래서 36 cm²예요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,96.0],"4 cm"],[[115.0,81.0],"2 cm"],[[70,55.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체예요. 면 ㄱㄴㄷㄹ이 밑면일 때 옆면 4개의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["옆면은 가로 × 높이인 면 2개와 세로 × 높이인 면 2개예요.","5 × 2 × 2 + 3 × 2 × 2 = 32예요.","그래서 32 cm²예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[143.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[110,77.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,85.0],"5 cm"],[[142.5,64.5],"3 cm"],[[92,55.0],"2 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 4 cm인 직육면체예요. 면 ㄱㄴㄷㄹ이 밑면일 때 옆면 4개의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["옆면은 가로 × 높이인 면 2개와 세로 × 높이인 면 2개예요.","6 × 4 × 2 + 2 × 4 × 2 = 64예요.","그래서 64 cm²예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[132,22.0,"sw"],"ㅁ":[22.0,88,"ne"],"ㅇ":[154.0,88,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[132,110.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[66.0,118.0],"6 cm"],[[159.0,103.0],"2 cm"],[[114,66.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L05_challenge#9','math',5,2,'u5','L05','g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',4,'sa','auto','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체예요. 면 ㄴㅂㅅㄷ이 밑면일 때 두 밑면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C5","difficulty":4,"kind":"sa","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체예요. 면 ㄴㅂㅅㄷ이 밑면일 때 두 밑면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["두 밑면은 면 ㄴㅂㅅㄷ과 그와 평행한 면 ㄱㅁㅇㄹ이에요.","두 면은 모양과 크기가 같은 4 cm, 3 cm인 직사각형이에요.","4 × 3 × 2 = 24예요."],"mis":"M5-2-u5-X11","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,96.0],"4 cm"],[[115.0,81.0],"2 cm"],[[70,55.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체예요. 면 ㄷㅅㅇㄹ이 밑면일 때 두 밑면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["두 밑면은 면 ㄷㅅㅇㄹ과 그와 평행한 면 ㄱㅁㅂㄴ이에요.","두 면은 모양과 크기가 같은 3 cm, 2 cm인 직사각형이에요.","3 × 2 × 2 = 12예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[143.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[110,77.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,85.0],"5 cm"],[[142.5,64.5],"3 cm"],[[92,55.0],"2 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 4 cm인 직육면체예요. 면 ㄱㄴㄷㄹ이 밑면일 때 두 밑면의 넓이의 합은 몇 cm²인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["두 밑면은 면 ㄱㄴㄷㄹ과 그와 평행한 면 ㅁㅂㅅㅇ이에요.","두 면은 모양과 크기가 같은 6 cm, 2 cm인 직사각형이에요.","6 × 2 × 2 = 24예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":110.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[132,22.0,"sw"],"ㅁ":[22.0,88,"ne"],"ㅇ":[154.0,88,"e"],"ㅂ":[0,110.0,"sw"],"ㅅ":[132,110.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[66.0,118.0],"6 cm"],[[159.0,103.0],"2 cm"],[[114,66.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L05_challenge#10','math',5,2,'u5','L05','g5_2_math_u5_L05_challenge','lesson_challenge','M5-2-u5-C5',4,'essay','teacher','과일 가게 삼촌이 상자를 눕혀 놓고 「바닥에 닿은 면이 아니니까 옆에 선 두 면은 밑면이 될 수 없어.」라고 했어요. 이 말이 맞는지 판단하고, 밑면과 옆면의 뜻을 넣어 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C5","difficulty":4,"kind":"essay","stem":"과일 가게 삼촌이 상자를 눕혀 놓고 「바닥에 닿은 면이 아니니까 옆에 선 두 면은 밑면이 될 수 없어.」라고 했어요. 이 말이 맞는지 판단하고, 밑면과 옆면의 뜻을 넣어 까닭을 쓰세요.","answer_guide":{"answer":"예: 이 말은 틀렸다. 밑면은 놓인 위치가 아니라 서로 평행한 두 면을 말한다. 옆에 선 두 면도 서로 평행하므로 밑면이 될 수 있다. 그때 이 두 면과 수직으로 만나는 나머지 4개의 면이 옆면이 된다.","scoring_points":["틀렸다고 판단했는가","밑면은 서로 평행한 두 면이라고 썼는가","옆면은 밑면과 수직인 면 4개라고 썼는가"]},"explanation":["밑면은 위치가 아니라 평행한 관계로 정해요.","옆에 선 두 면도 평행하면 밑면이에요.","밑면과 수직인 4개의 면이 옆면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_basic#1','math',5,2,'u5','L06','g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',1,'mc','auto','직육면체의 모든 면이 이어지도록 모서리를 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?',ARRAY['M5-2-u5-X16','M5-2-u5-X02','M5-2-u5-X01']::text[],true,'{"seq":1,"concept":"M5-2-u5-C6","difficulty":1,"kind":"mc","stem":"직육면체의 모든 면이 이어지도록 모서리를 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 전개도","correct":true},{"t":"직육면체의 겨냥도","mis":"M5-2-u5-X16"},{"t":"직사각형","mis":"M5-2-u5-X02"},{"t":"평면도형","mis":"M5-2-u5-X01"}],"explanation":["전개도는 모든 면이 이어지게 모서리를 잘라 펼친 그림이에요.","잘린 모서리는 실선, 잘리지 않은(접는) 모서리는 점선이에요.","정답은 「직육면체의 전개도」예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체의 전개도에서 잘린 모서리는 어떻게 나타내나요?","options":[{"t":"실선으로 나타낸다","correct":true},{"t":"점선으로 나타낸다","mis":"M5-2-u5-X16"},{"t":"나타내지 않는다","mis":"M5-2-u5-X16"},{"t":"색칠해 나타낸다","mis":"M5-2-u5-X03"}],"explanation":["전개도는 모든 면이 이어지게 모서리를 잘라 펼친 그림이에요.","잘린 모서리는 실선, 잘리지 않은(접는) 모서리는 점선이에요.","정답은 「실선으로 나타낸다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false}},{"stem":"직육면체의 전개도에서 잘리지 않은 모서리는 어떻게 나타내나요?","options":[{"t":"점선으로 나타낸다","correct":true},{"t":"실선으로 나타낸다","mis":"M5-2-u5-X16"},{"t":"나타내지 않는다","mis":"M5-2-u5-X16"},{"t":"굵은 선으로 나타낸다","mis":"M5-2-u5-X16"}],"explanation":["전개도는 모든 면이 이어지게 모서리를 잘라 펼친 그림이에요.","잘린 모서리는 실선, 잘리지 않은(접는) 모서리는 점선이에요.","정답은 「점선으로 나타낸다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
