INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_basic#7','math',5,2,'u5','L06','g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',2,'mc','auto','전개도를 접었을 때 면 나와 수직인 면을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":7,"concept":"M5-2-u5-C6","difficulty":2,"kind":"mc","stem":"전개도를 접었을 때 면 나와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 가, 면 다, 면 마, 면 바","correct":true},{"t":"면 가, 면 다, 면 라, 면 마","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 가, 면 다, 면 라","mis":"M5-2-u5-X13"}],"explanation":["면 나와 평행한 면은 면 라 하나뿐이에요.","나머지 4개의 면은 모두 면 나와 수직이에요.","정답은 면 가, 면 다, 면 마, 면 바예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[15.0,70.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"전개도를 접었을 때 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 마","correct":true},{"t":"면 나, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 바","mis":"M5-2-u5-X13"}],"explanation":["면 가와 평행한 면은 면 바 하나뿐이에요.","나머지 4개의 면은 모두 면 가와 수직이에요.","정답은 면 나, 면 다, 면 라, 면 마예요."],"asset":{"type":"geo","items":[{"w":200,"h":140,"seg":[[[0,60],[0,80]],[[0,60],[60,60]],[[0,80],[160,80]],[[60,0],[60,60]],[[60,0],[100,0]],[[100,0],[100,60]],[[100,60],[200,60]],[[160,80],[160,140]],[[160,140],[200,140]],[[200,60],[200,140]]],"dash":[[[60,60],[60,80]],[[60,60],[100,60]],[[100,60],[100,80]],[[160,60],[160,80]],[[160,80],[200,80]]],"lab":[[[80.0,25.0],"가"],[[30.0,65.0],"나"],[[80.0,65.0],"다"],[[130