INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_basic#8','math',5,2,'u5','L06','g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',2,'mc','auto','이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X02']::text[],true,'{"seq":8,"concept":"M5-2-u5-C6","difficulty":2,"kind":"mc","stem":"이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,30],[90,30]],[[90,30],[90,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 만나는 선분의 길이가 다르다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 만나는 선분의 길이가 다르다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":120,"seg":[[[0,0],[0,80]],[[0,0],[60,0]],[[0,80],[100,80]],[[60,0],[60,60]],[[60,60],[200,60]],[[100,80],[100,120]],[[100,120],[160,120]],[[160,80],[160,120]],[[160,80],[200,80]],[[200,60],[200,80]]],"dash":[[[0,60],[60,60]],[[60,60],[60,80]],[[100,60],[100,80]],[[100,80],[160,80]],[[160,60],[160,80]]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"면이 5개뿐이다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「면이 5개뿐이다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":60,"seg":[[[0,0],[0,20]],[[0,0],[200,0]],[[0,20],[100,20]],[[100,20],[100,60]],[[100,60],[160,60]],[[160,20],[160,60]],[[160,20],[200,20]],[[200,0],[200,20]]],"dash":[[[60,0],[60,20]],[[100,0],[100,20]],[[100,20],[160,20]],[[160,0],[160,20]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_basic#9','math',5,2,'u5','L06','g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',2,'ox','auto','면이 6개인 그림은 모두 직육면체의 전개도예요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":9,"concept":"M5-2-u5-C6","difficulty":2,"kind":"ox","stem":"면이 6개인 그림은 모두 직육면체의 전개도예요.","answer":"X","reason_options":[{"t":"면이 6개여도 접었을 때 겹치는 면이 있거나 맞붙는 선분의 길이가 다르면 전개도가 아니므로","correct":true},{"t":"면의 수만 맞으면 되므로","mis":"M5-2-u5-X14"}],"mis":"M5-2-u5-X14","explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「면이 6개여도 접었을 때 겹치는 면이 있거나 맞붙는 선분의 길이가 다르면 전개도가 아니므로」를 골라요."],"variant_rule":{"alt":[{"stem":"전개도를 접었을 때 만나는 두 선분은 길이가 같아요.","answer":"O","reason_options":[{"t":"두 선분이 한 모서리가 되므로","correct":true},{"t":"접으면 길이가 늘어나므로","mis":"M5-2-u5-X14"}],"explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「두 선분이 한 모서리가 되므로」를 골라요."]},{"stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 잘리지 않은 모서리가 점선이므로","correct":true},{"t":"잘린 곳은 끊어졌으니 점선이므로","mis":"M5-2-u5-X16"}],"explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「잘린 모서리는 실선, 잘리지 않은 모서리가 점선이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_basic#10','math',5,2,'u5','L06','g5_2_math_u5_L06_basic','lesson_basic','M5-2-u5-C6',3,'mc','auto','직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":10,"concept":"M5-2-u5-C6","difficulty":3,"kind":"mc","stem":"직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 다","correct":true},{"t":"나","mis":"M5-2-u5-X14"},{"t":"나, 다","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 맞붙는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","전개도가 되는 것은 가, 다예요."],"asset":{"type":"geo","items":[{"w":72,"h":54,"seg":[[[0,0],[0,54]],[[0,0],[18,0]],[[0,54],[18,54]],[[18,0],[18,18]],[[18,18],[72,18]],[[18,36],[18,54]],[[18,36],[72,36]],[[72,18],[72,36]]],"dash":[[[0,18],[18,18]],[[0,36],[18,36]],[[18,18],[18,36]],[[36,18],[36,36]],[[54,18],[54,36]]]},{"w":72,"h":36,"seg":[[[0,0],[0,36]],[[0,0],[18,0]],[[0,36],[72,36]],[[18,0],[18,18]],[[18,18],[36,18]],[[36,0],[36,18]],[[36,0],[54,0]],[[54,0],[54,18]],[[54,18],[72,18]],[[72,18],[72,36]]],"dash":[[[0,18],[18,18]],[[18,18],[18,36]],[[36,18],[36,36]],[[36,18],[54,18]],[[54,18],[54,36]]]},{"w":120,"h":84,"seg":[[[0,36],[0,48]],[[0,36],[36,36]],[[0,48],[96,48]],[[36,0],[36,36]],[[36,0],[60,0]],[[60,0],[60,36]],[[60,36],[120,36]],[[96,48],[96,84]],[[96,84],[120,84]],[[120,36],[120,84]]],"dash":[[[36,36],[36,48]],[[36,36],[60,36]],[[60,36],[60,48]],[[96,36],[96,48]],[[96,48],[120,48]]]},{"w":120,"h":72,"seg":[[[0,0],[0,48]],[[0,0],[36,0]],[[0,48],[60,48]],[[36,0],[36,36]],[[36,36],[120,36]],[[60,48],[60,72]],[[60,72],[96,72]],[[96,48],[96,72]],[[96,48],[120,48]],[[120,36],[120,48]]],"dash":[[[0,36],[36,36]],[[36,36],[36,48]],[[60,36],[60,48]],[[60,48],[96,48]],[[96,36],[96,48]]]}],"tag":true},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"라","mis":"M5-2-u5-X14"},{"t":"나, 다, 라","mis":"M5-2-u5-X14"},{"t":"가, 나, 다","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 맞붙는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","전개도가 되는 것은 나, 라예요."],"asset":{"type":"geo","items":[{"w":108,"h":90,"seg":[[[0,0],[0,54]],[[0,0],[108,0]],[[0,54],[36,54]],[[36,54],[36,90]],[[36,90],[54,90]],[[54,54],[54,90]],[[54,54],[90,54]],[[90,54],[90,90]],[[90,90],[108,90]],[[108,0],[108,90]]],"dash":[[[36,0],[36,54]],[[36,54],[54,54]],[[54,0],[54,54]],[[90,0],[90,54]],[[90,54],[108,54]]]},{"w":72,"h":54,"seg":[[[0,0],[0,36]],[[0,0],[18,0]],[[0,36],[36,36]],[[18,0],[18,18]],[[18,18],[54,18]],[[36,36],[36,54]],[[36,54],[72,54]],[[54,18],[54,36]],[[54,36],[72,36]],[[72,36],[72,54]]],"dash":[[[0,18],[18,18]],[[18,18],[18,36]],[[36,18],[36,36]],[[36,36],[54,36]],[[54,36],[54,54]]]},{"w":72,"h":36,"seg":[[[0,0],[0,18]],[[0,0],[72,0]],[[0,18],[36,18]],[[36,18],[36,36]],[[36,36],[54,36]],[[54,18],[54,36]],[[54,18],[72,18]],[[72,0],[72,18]]],"dash":[[[18,0],[18,18]],[[36,0],[36,18]],[[36,18],[54,18]],[[54,0],[54,18]]]},{"w":72,"h":54,"seg":[[[0,0],[0,18]],[[0,0],[36,0]],[[0,18],[18,18]],[[18,18],[18,36]],[[18,36],[36,36]],[[36,0],[36,18]],[[36,18],[54,18]],[[36,36],[36,54]],[[36,54],[72,54]],[[54,18],[54,36]],[[54,36],[72,36]],[[72,36],[72,54]]],"dash":[[[18,0],[18,18]],[[18,18],[36,18]],[[36,18],[36,36]],[[36,36],[54,36]],[[54,36],[54,54]]]}],"tag":true}},{"stem":"이번에는 다른 보기예요. 직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"다, 라","correct":true},{"t":"가, 나, 다","mis":"M5-2-u5-X14"},{"t":"나","mis":"M5-2-u5-X14"},{"t":"가","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 맞붙는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","전개도가 되는 것은 다, 라예요."],"asset":{"type":"geo","items":[{"w":108,"h":126,"seg":[[[0,0],[0,72]],[[0,0],[36,0]],[[0,72],[54,72]],[[36,0],[36,18]],[[36,18],[108,18]],[[54,72],[54,126]],[[54,126],[90,126]],[[90,72],[90,126]],[[90,72],[108,72]],[[108,18],[108,72