INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_challenge#2','math',5,2,'u5','L06','g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',2,'ox','auto','전개도를 접었을 때 만나는 두 선분은 길이가 같아요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":2,"concept":"M5-2-u5-C6","difficulty":2,"kind":"ox","stem":"전개도를 접었을 때 만나는 두 선분은 길이가 같아요.","answer":"O","reason_options":[{"t":"두 선분이 한 모서리가 되므로","correct":true},{"t":"접으면 길이가 늘어나므로","mis":"M5-2-u5-X14"}],"mis":"M5-2-u5-X14","explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「두 선분이 한 모서리가 되므로」를 골라요."],"variant_rule":{"alt":[{"stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 잘리지 않은 모서리가 점선이므로","correct":true},{"t":"잘린 곳은 끊어졌으니 점선이므로","mis":"M5-2-u5-X16"}],"explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「잘린 모서리는 실선, 잘리지 않은 모서리가 점선이므로」를 골라요."]},{"stem":"직육면체의 전개도에서 한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","answer":"O","reason_options":[{"t":"접으면 하나 건너 있는 면끼리 마주 보므로","correct":true},{"t":"바로 옆에 있는 면끼리 마주 보므로","mis":"M5-2-u5-X12"}],"explanation":["전개도를 접은 모양을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「접으면 하나 건너 있는 면끼리 마주 보므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
