INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_challenge#5','math',5,2,'u5','L06','g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',3,'mc','auto','이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X02']::text[],true,'{"seq":5,"concept":"M5-2-u5-C6","difficulty":3,"kind":"mc","stem":"이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":168,"h":140,"seg":[[[0,0],[0,84]],[[0,0],[168,0]],[[0,84],[56,84]],[[56,84],[56,140]],[[56,140],[84,140]],[[84,84],[84,140]],[[84,84],[140,84]],[[140,84],[140,140]],[[140,140],[168,140]],[[168,0],[168,140]]],"dash":[[[56,0],[56,84]],[[56,84],[84,84]],[[84,0],[84,84]],[[140,0],[140,84]],[[140,84],[168,84]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 만나는 선분의 길이가 다르다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 만나는 선분의 길이가 다르다」예요."],"asset":{"type":"geo","items":[{"w":120,"h":140,"seg":[[[0,0],[0,80]],[[0,0],[40,0]],[[0,80],[60,80]],[[40,0],[40,20]],[[40,20],[120,20]],[[60,80],[60,140]],[[60,140],[100,140]],[[100,80],[100,140]],[[100,80],[120,80]],[[120,20],[120,80]]],"dash":[[[0,20],[40,20]],[[40,20],[40,80]],[[60,20],[60,80]],[[60,80],[100,80]],[[100,20],[100,80]]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","option