INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_challenge#6','math',5,2,'u5','L06','g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',3,'mc','auto','전개도를 접었을 때 면 바와 수직인 면을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":6,"concept":"M5-2-u5-C6","difficulty":3,"kind":"mc","stem":"전개도를 접었을 때 면 바와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 가, 면 나, 면 다, 면 마","correct":true},{"t":"면 가, 면 나, 면 다, 면 라","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 라, 면 마","mis":"M5-2-u5-X12"},{"t":"면 가, 면 나, 면 라","mis":"M5-2-u5-X13"}],"explanation":["면 바와 평행한 면은 면 라 하나뿐이에요.","나머지 4개의 면은 모두 면 바와 수직이에요.","정답은 면 가, 면 나, 면 다, 면 마예요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[90,0]],[[0,30],[60,30]],[[60,30],[60,60]],[[60,60],[150,60]],[[90,0],[90,30]],[[90,30],[150,30]],[[150,30],[150,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[60,30],[90,30]],[[90,30],[90,60]],[[120,30],[120,60]]],"lab":[[[15.0,10.0],"가"],[[45.0,10.0],"나"],[[75.0,10.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[135.0,40.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"전개도를 접었을 때 면 가와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 마, 면 바","correct":true},{"t":"면 나, 면 다, 면 라, 면 마","mis":"M5-2-u5-X12"},{"t":"면 다, 면 라, 면 마, 면 바","mis":"M5-2-u5-X12"},{"t":"면 나, 면 다, 면 라","mis":"M5-2-u5-X13"}],"explanation":["면 가와 평행한 면은 면 라 하나뿐이에요.","나머지 4개의 면은 모두 면 가와 수직이에요.","정답은 면 나, 면 다, 면 마, 면 바예요."],"asset":{"type":"geo","items":[{"w":136,"h":136,"seg":[[[0,51],[0,68]],[[0,51],[51,51]],[[0,68],[51,68]],[[51,0],[51,51]],[[51,0],[85,0]],[[51,68],[51,136]],[[51,136],[136,136]],[[85,0],[85,119]],[[85,119],[136,119]],[[136,119],[136,136]]],"dash":[[[51,51],[51,68]],[[51,51],[85,51]],[[51,68],[85,68]],[[51,119],[85,119]],[[85,119],[85,136]]],"lab":[[[68.0,20.5],"가"],[[25.5,54.5],"나"],[[68.0,54.5],"다"],[[68.0,88.5],"라"],[[68.0,122.5],"마"],[[110.5,122.5],"바"]]}],"tag":false}},{"stem":"전개도를 접었을 때 면 마와 수직인 면을 모두 고른 것은 어느 것인가요?","options":[{"t":"면 나, 면 다, 면 라, 면 바","correct":true},{"t":"면 가, 면 나, 면 다, 면 라","mis":"M5-2-u5-X12"},{"t":"면 가, 면 다, 면 라, 면 바","mis":"M5-2-u5-X12"},{"t":"면 가, 면 나, 면 다","mis":"M5-2-u5-X13"}],"explanation":["면 마와 평행한 면은 면 가 하나뿐이에요.","나머지 4개의 면은 모두 면 마와 수직이에요.","정답은 면 나, 면 다, 면 라, 면 바예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[45.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[75.0,70.0],"마"],[[105.0,70.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_challenge#7','math',5,2,'u5','L06','g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',3,'sa','auto','이 전개도를 접은 직육면체에서 잘린 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C6","difficulty":3,"kind":"sa","stem":"이 전개도를 접은 직육면체에서 잘린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["전개도는 면 6개가 모두 이어지게 모서리를 잘라 펼친 그림이에요.","모서리 12개 가운데 점선 5개는 잘리지 않았으니 12 − 5 = 7(개)예요.","그래서 7이에요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":150,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[90,0]],[[0,30],[60,30]],[[60,30],[60,60]],[[60,60],[150,60]],[[90,0],[90,30]],[[90,30],[150,30]],[[150,30],[150,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[60,30],[90,30]],[[90,30],[90,60]],[[120,30],[120,60]]],"lab":[[[15.0,10.0],"가"],[[45.0,10.0],"나"],[[75.0,10.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[135.0,40.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 전개도를 접은 직육면체에서 잘린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["전개도는 면 6개가 모두 이어지게 모서리를 잘라 펼친 그림이에요.","모서리 12개 가운데 점선 5개는 잘리지 않았으니 12 − 5 = 7(개)예요.","그래서 7이에요."],"asset":{"type":"geo","items":[{"w":192,"h":112,"seg":[[[0,0],[0,80]],[[0,0],[64,0]],[[0,80],[96,80]],[[64,0],[64,32]],[[64,32],[192,32]],[[96,80],[96,112]],[[96,112],[160,112]],[[160,80],[160,112]],[[160,80],[192,80]],[[192,32],[192,80]]],"dash":[[[0,32],[64,32]],[[64,32],[64,80]],[[96,32],[96,80]],[[96,80],[160,80]],[[160,32],[160,80]]],"lab":[[[32.0,11.0],"가"],[[32.0,51.0],"나"],[[80.0,51.0],"다"],[[128.0,51.0],"라"],[[176.0,51.0],"마"],[[128.0,91.0],"바"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 이 전개도를 접은 직육면체에서 잘린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["전개도는 면 6개가 모두 이어지게 모서리를 잘라 펼친 그림이에요.","모서리 12개 가운데 점선 5개는 잘리지 않았으니 12 − 5 = 7(개)예요.","그래서 7이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[45.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[75.0,70.0],"마"],[[105.0,70.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_challenge#8','math',5,2,'u5','L06','g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',4,'mc','auto','직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":8,"concept":"M5-2-u5-C6","difficulty":4,"kind":"mc","stem":"직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"라","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"가, 라","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 맞붙는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","전개도가 되는 것은 나, 라예요."],"asset":{"type":"geo","items":[{"w":54,"h":54,"seg":[[[0,0],[0,36]],[[0,0],[36,0]],[[0,36],[36,36]],[[36,0],[36,18]],[[36,18],[54,18]],[[36,36],[36,54]],[[36,54],[54,54]],[[54,18],[54,54]]],"dash":[[[0,18],[36,18]],[[18,0],[18,36]],[[36,18],[36,36]],[[36,36],[54,36]]]},{"w":72,"h":54,"seg":[[[0,18],[0,36]],[[0,18],[18,18]],[[0,36],[36,36]],[[18,0],[18,18]],[[18,0],[36,0]],[[36,0],[36,18]],[[36,18],[54,18]],[[36,36],[36,54]],[[36,54],[72,54]],[[54,18],[54,36]],[[54,36],[72,36]],[[72,36],[72,54]]],"dash":[[[18,18],[18,36]],[[18,18],[36,18]],[[36,18],[36,36]],[[36,36],[54,36]],[[54,36],[54,54]]]},{"w":120,"h":105,"seg":[[[0,30],[0,60]],[[0,30],[45,30]],[[0,60],[105,60]],[[45,0],[45,30]],[[45,0],[60,0]],[[60,0],[60,30]],[[60,30],[120,30]],[[105,60],[105,105]],[[105,105],[120,105]],[[120,30],[120,105]]],"dash":[[[45,30],[45,60]],[[45,30],[60,30]],[[60,30],[60,60]],[[105,30],[105,60]],[[105,60],[120,60]]]},{"w":120,"h":80,"seg":[[[0,0],[0,50]],[[0,0],[30,0]],[[0,50],[60,50]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,50],[60,80]],[[60,80],[90,80]],[[90,50],[90,80]],[[90,50],[120,50]],[[120,30],[120,50]]],"dash":[[[0,30],[30,30]],[[30,30],[30,50]],[[60,30],[60,50]],[[60,50],[90,50]],[[90,30],[90,50]]]}],"tag":true},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"나, 라","correct":true},{"t":"나, 다, 라","mis":"M5-2-u5-X14"},{"t":"가","mis":"M5-2-u5-X14"},{"t":"가, 나, 다","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 맞붙는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","전개도가 되는 것은 나, 라예요."],"asset":{"type":"geo","items":[{"w":108,"h":18,"seg":[[[0,0],[0,18]],[[0,0],[108,0]],[[0,18],[108,18]],[[108,0],[108,18]]],"dash":[[[18,0],[18,18]],[[36,0],[36,18]],[[54,0],[54,18]],[[72,0],[72,18]],[[90,0],[90,18]]]},{"w":120,"h":70,"seg":[[[0,0],[0,50]],[[0,0],[40,0]],[[0,50],[60,50]],[[40,0],[40,20]],[[40,20],[120,20]],[[60,50],[60,70]],[[60,70],[100,70]],[[100,50],[100,70]],[[100,50],[120,50]],[[120,20],[120,50]]],"dash":[[[0,20],[40,20]],[[40,20],[40,50]],[[60,20],[60,50]],[[60,50],[100,50]],[[100,20],[100,50]]]},{"w":108,"h":90,"seg":[[[0,36],[0,90]],[[0,36],[36,36]],[[0,90],[108,90]],[[36,0],[36,36]],[[36,0],[54,0]],[[54,0],[54,36]],[[54,36],[108,36]],[[108,36],[108,90]]],"dash":[[[36,36],[36,90]],[[36,36],[54,36]],[[54,36],[54,90]],[[90,36],[90,90]]]},{"w":54,"h":72,"seg":[[[0,18],[0,36]],[[0,18],[18,18]],[[0,36],[18,36]],[[18,0],[18,18]],[[18,0],[36,0]],[[18,36],[18,72]],[[18,72],[36,72]],[[36,0],[36,36]],[[36,36],[54,36]],[[36,54],[36,72]],[[36,54],[54,54]],[[54,36],[54,54]]],"dash":[[[18,18],[18,36]],[[18,18],[36,18]],[[18,36],[36,36]],[[18,54],[36,54]],[[36,36],[36,54]]]}],"tag":true}},{"stem":"이번에는 다른 보기예요. 직육면체의 전개도가 될 수 있는 것을 모두 고른 것은 어느 것인가요?","options":[{"t":"가, 라","correct":true},{"t":"다","mis":"M5-2-u5-X14"},{"t":"가","mis":"M5-2-u5-X14"},{"t":"나, 라","mis":"M5-2-u5-X14"}],"explanation":["그림마다 접은 모양을 떠올려요.","겹치는 면이 있거나 맞붙는 선분의 길이가 다르거나 면이 모자라면 전개도가 아니에요.","전개도가 되는 것은 가, 라예요."],"asset":{"type":"geo","items":[{"w":90,"h":108,"seg":[[[0,0],[0,36]],[[0,0],[72,0]],[[0,36],[18,36]],[[18,36],[18,108]],[[18,108],[72,108]],[[72,0],[72,54]],[[72,54],[90,54]],[[72,90],[72,108]],[[72,90],[90,90]],[[90,54],[90,90]]],"dash":[[[18,0],[18,36]],[[18,36],[72,36]],[[18,5