INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_challenge#9','math',5,2,'u5','L06','g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',4,'mc','auto','전개도를 접어서 직육면체를 만들었어요. 점 ㄱ과 만나는 점을 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X15']::text[],true,'{"seq":9,"concept":"M5-2-u5-C6","difficulty":4,"kind":"mc","stem":"전개도를 접어서 직육면체를 만들었어요. 점 ㄱ과 만나는 점을 모두 고른 것은 어느 것인가요?","options":[{"t":"점 ㅈ, 점 ㅍ","correct":true},{"t":"점 ㅈ, 점 ㅎ","mis":"M5-2-u5-X15"},{"t":"점 ㄴ, 점 ㅈ","mis":"M5-2-u5-X15"},{"t":"점 ㅇ, 점 ㅈ","mis":"M5-2-u5-X15"}],"explanation":["접으면 한 꼭짓점에 세 면이 모여요.","점 ㄱ이 있는 면들을 접어 올려 같은 꼭짓점에 오는 점을 찾아요.","점 ㄱ과 만나는 점은 점 ㅈ, 점 ㅍ이에요."],"asset":{"type":"geo","items":[{"w":90,"h":120,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[30,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[30,60],[30,120]],[[30,120],[60,120]],[[60,0],[60,60]],[[60,60],[90,60]],[[60,90],[60,120]],[[60,90],[90,90]],[[90,60],[90,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[30,60],[60,60]],[[30,90],[60,90]],[[60,60],[60,90]]],"lab":[[[45.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[45.0,70.0],"라"],[[75.0,70.0],"마"],[[45.0,100.0],"바"]],"pts":{"ㄱ":[30,0,"nw"],"ㄴ":[60,0,"ne"],"ㄷ":[60,30,"e"],"ㄹ":[60,60,"ne"],"ㅁ":[90,60,"ne"],"ㅂ":[90,90,"se"],"ㅅ":[60,90,"se"],"ㅇ":[60,120,"se"],"ㅈ":[30,120,"sw"],"ㅊ":[30,90,"w"],"ㅋ":[30,60,"sw"],"ㅌ":[0,60,"sw"],"ㅍ":[0,30,"nw"],"ㅎ":[30,30,"nw"]}}],"tag":false},"variant_rule":{"alt":[{"stem":"전개도를 접어서 직육면체를 만들었어요. 점 ㄷ과 만나는 점을 모두 고른 것은 어느 것인가요?","options":[{"t":"점 ㅁ, 점 ㅅ","correct":true},{"t":"점 ㄴ, 점 ㅁ","mis":"M5-2-u5-X15"},{"t":"점 ㄹ, 점 ㅁ","mis":"M5-2-u5-X15"},{"t":"점 ㅁ, 점 ㅂ","mis":"M5-2-u5-X15"}],"explanation":["접으면 한 꼭짓점에 세 면이 모여요.","점 ㄷ이 있는 면들을 접어 올려 같은 꼭짓점에 오는 점을 찾아요.","점 ㄷ과 만나는 점은 점 ㅁ, 점 ㅅ이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,6