INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L06_challenge#10','math',5,2,'u5','L06','g5_2_math_u5_L06_challenge','lesson_challenge','M5-2-u5-C6',4,'essay','teacher','면이 6개인 그림이에요. 친구가 「면이 6개니까 직육면체의 전개도야.」라고 했어요. 친구의 말이 맞는지 판단하고, 전개도가 되려면 무엇을 따져 보아야 하는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C6","difficulty":4,"kind":"essay","stem":"면이 6개인 그림이에요. 친구가 「면이 6개니까 직육면체의 전개도야.」라고 했어요. 친구의 말이 맞는지 판단하고, 전개도가 되려면 무엇을 따져 보아야 하는지 쓰세요.","answer_guide":{"answer":"예: 친구의 말은 틀렸다. 이 그림은 접었을 때 두 면이 같은 자리에서 겹쳐 한쪽이 비므로 전개도가 아니다. 전개도가 되려면 면의 수뿐 아니라 접었을 때 겹치는 면이 없는지, 맞붙는 두 선분의 길이가 같은지를 따져 보아야 한다.","scoring_points":["틀렸다고 판단했는가","접었을 때 겹치는 면이 있다고 썼는가","겹치는 면·맞붙는 선분의 길이를 따져야 한다고 썼는가"]},"explanation":["접은 모양을 떠올려요.","위쪽에 붙은 두 면이 같은 자리에서 겹쳐요.","면의 수뿐 아니라 겹침과 맞붙는 길이를 따져요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,30],[90,30]],[[90,30],[90,60]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#1','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',1,'mc','auto','직육면체의 전개도를 그리려면 면을 몇 개 그려야 하나요?',ARRAY['M5-2-u5-X04','M5-2-u5-X14','M5-2-u5-X05']::text[],true,'{"seq":1,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"직육면체의 전개도를 그리려면 면을 몇 개 그려야 하나요?","options":[{"t":"6개","correct":true},{"t":"4개","mis":"M5-2-u5-X04"},{"t":"5개","mis":"M5-2-u5-X14"},{"t":"12개","mis":"M5-2-u5-X05"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「6개」예요."],"variant_rule":{"alt":[{"stem":"직육면체의 전개도를 그릴 때 접었을 때 맞붙는 두 모서리는 어떻게 그리나요?","options":[{"t":"길이가 같게 그린다","correct":true},{"t":"한쪽을 더 길게 그린다","mis":"M5-2-u5-X14"},{"t":"둘 다 점선으로 그린다","mis":"M5-2-u5-X16"},{"t":"하나만 그린다","mis":"M5-2-u5-X14"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「길이가 같게 그린다」예요."]},{"stem":"직육면체의 전개도를 그릴 때 접었을 때 마주 보는 두 면은 어떻게 그리나요?","options":[{"t":"모양과 크기가 같게 그린다","correct":true},{"t":"크기를 다르게 그린다","mis":"M5-2-u5-X14"},{"t":"하나는 정사각형으로 그린다","mis":"M5-2-u5-X02"},{"t":"바로 붙여서 그린다","mis":"M5-2-u5-X12"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「모양과 크기가 같게 그린다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#2','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',1,'mc','auto','한 모서리가 3 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?',ARRAY['M5-2-u5-X07','M5-2-u5-X04']::text[],true,'{"seq":2,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"한 모서리가 3 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 3 cm인 정사각형 6개","correct":true},{"t":"가로 3 cm, 세로 6 cm인 직사각형 6개","mis":"M5-2-u5-X07"},{"t":"한 변이 3 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 6 cm인 정사각형 6개","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 3 cm이니 한 변이 3 cm인 정사각형이에요.","면이 6개니 6개를 그려요."],"variant_rule":{"alt":[{"stem":"한 모서리가 2 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 2 cm인 정사각형 6개","correct":true},{"t":"가로 2 cm, 세로 4 cm인 직사각형 6개","mis":"M5-2-u5-X07"},{"t":"한 변이 2 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 4 cm인 정사각형 6개","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 2 cm이니 한 변이 2 cm인 정사각형이에요.","면이 6개니 6개를 그려요."]},{"stem":"한 모서리가 4 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 4 cm인 정사각형 6개","correct":true},{"t":"가로 4 cm, 세로 8 cm인 직사각형 6개","mis":"M5-2-u5-X07"},{"t":"한 변이 4 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 8 cm인 정사각형 6개","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 4 cm이니 한 변이 4 cm인 정사각형이에요.","면이 6개니 6개를 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#3','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',1,'mc','auto','한 직육면체의 전개도에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":3,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"한 직육면체의 전개도에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"자르는 모서리에 따라 여러 가지로 그릴 수 있다","correct":true},{"t":"전개도는 한 가지뿐이다","mis":"M5-2-u5-X14"},{"t":"전개도마다 접은 직육면체의 크기가 다르다","mis":"M5-2-u5-X14"},{"t":"면을 7개 그려도 된다","mis":"M5-2-u5-X14"}],"explanation":["어느 모서리를 자르는지에 따라 펼친 모양이 달라져요.","모양은 달라도 접으면 같은 직육면체가 돼요.","정답은 「자르는 모서리에 따라 여러 가지로 그릴 수 있다」예요."],"variant_rule":{"alt":[{"stem":"같은 상자를 두 친구가 다르게 펼쳤어요. 바르게 말한 것은 어느 것인가요?","options":[{"t":"모양은 달라도 접으면 모두 같은 직육면체가 된다","correct":true},{"t":"한 친구는 틀리게 펼쳤다","mis":"M5-2-u5-X14"},{"t":"접으면 서로 다른 직육면체가 된다","mis":"M5-2-u5-X14"},{"t":"면의 수가 서로 다르다","mis":"M5-2-u5-X04"}],"explanation":["어느 모서리를 자르는지에 따라 펼친 모양이 달라져요.","모양은 달라도 접으면 같은 직육면체가 돼요.","정답은 「모양은 달라도 접으면 모두 같은 직육면체가 된다」예요."]},{"stem":"전개도가 여러 가지인 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"어느 모서리를 자르는지에 따라 펼친 모양이 달라지기 때문이다","correct":true},{"t":"면의 크기가 바뀌기 때문이다","mis":"M5-2-u5-X14"},{"t":"모서리의 수가 바뀌기 때문이다","mis":"M5-2-u5-X05"},{"t":"잘못 그린 것이 많기 때문이다","mis":"M5-2-u5-X14"}],"explanation":["어느 모서리를 자르는지에 따라 펼친 모양이 달라져요.","모양은 달라도 접으면 같은 직육면체가 돼요.","정답은 「어느 모서리를 자르는지에 따라 펼친 모양이 달라지기 때문이다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#4','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',1,'ox','auto','직육면체의 전개도에는 면을 6개 그려요.',ARRAY['M5-2-u5-X04']::text[],true,'{"seq":4,"concept":"M5-2-u5-C7","difficulty":1,"kind":"ox","stem":"직육면체의 전개도에는 면을 6개 그려요.","answer":"O","reason_options":[{"t":"직육면체의 면이 6개이므로","correct":true},{"t":"보이는 면 3개만 그리면 되므로","mis":"M5-2-u5-X04"}],"mis":"M5-2-u5-X04","explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「직육면체의 면이 6개이므로」를 골라요."],"variant_rule":{"alt":[{"stem":"정육면체의 전개도는 크기가 같은 정사각형 6개로 이루어져요.","answer":"O","reason_options":[{"t":"정육면체의 면은 모두 크기가 같은 정사각형이므로","correct":true},{"t":"정육면체는 면이 4개이므로","mis":"M5-2-u5-X07"}],"explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「정육면체의 면은 모두 크기가 같은 정사각형이므로」를 골라요."]},{"stem":"전개도에서 접었을 때 맞붙는 두 모서리는 길이가 달라도 돼요.","answer":"X","reason_options":[{"t":"맞붙는 두 모서리는 한 모서리가 되므로 길이가 같아야 하므로","correct":true},{"t":"접으면 길이가 맞춰지므로","mis":"M5-2-u5-X14"}],"explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「맞붙는 두 모서리는 한 모서리가 되므로 길이가 같아야 하므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#5','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'mc','auto','우리 마을 모형을 만들려고 가로 5 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리다 멈췄어요. 모눈 한 칸은 1 cm예요. 빠진 면 하나는 어떤 직사각형인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":5,"concept":"M5-2-u5-C7","difficulty":2,"kind":"mc","stem":"우리 마을 모형을 만들려고 가로 5 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리다 멈췄어요. 모눈 한 칸은 1 cm예요. 빠진 면 하나는 어떤 직사각형인가요?","options":[{"t":"가로 5 cm, 세로 2 cm인 직사각형","correct":true},{"t":"가로 5 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 2 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 3 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 면은 6개인데 그림에는 5개뿐이에요.","빠진 면은 이미 있는 아랫면과 마주 보는 면이라 모양과 크기가 같아요.","그래서 가로 5 cm, 세로 2 cm인 직사각형이에요."],"asset":{"type":"geo","items":[{"w":196,"h":70,"seg":[[[0,0],[0,42]],[[0,0],[196,0]],[[0,42],[98,42]],[[98,42],[98,70]],[[98,70],[168,70]],[[168,42],[168,70]],[[168,42],[196,42]],[[196,0],[196,42]]],"dash":[[[70,0],[70,42]],[[98,0],[98,42]],[[98,42],[168,42]],[[168,0],[168,42]]],"grid":14}],"tag":false},"variant_rule":{"alt":[{"stem":"우리 마을 모형을 만들려고 가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체의 전개도를 그리다 멈췄어요. 모눈 한 칸은 1 cm예요. 빠진 면 하나는 어떤 직사각형인가요?","options":[{"t":"가로 4 cm, 세로 3 cm인 직사각형","correct":true},{"t":"가로 4 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 3 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 2 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 면은 6개인데 그림에는 5개뿐이에요.","빠진 면은 이미 있는 윗면과 마주 보는 면이라 모양과 크기가 같아요.","그래서 가로 4 cm, 세로 3 cm인 직사각형이에요."],"asset":{"type":"geo","items":[{"w":196,"h":70,"seg":[[[0,0],[0,70]],[[0,0],[56,0]],[[0,70],[196,70]],[[56,0],[56,42]],[[56,42],[196,42]],[[196,42],[196,70]]],"dash":[[[0,42],[56,42]],[[56,42],[56,70]],[[98,42],[98,70]],[[154,42],[154,70]]],"grid":14}],"tag":false}},{"stem":"우리 마을 모형을 만들려고 가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리다 멈췄어요. 모눈 한 칸은 1 cm예요. 빠진 면 하나는 어떤 직사각형인가요?","options":[{"t":"가로 6 cm, 세로 2 cm인 직사각형","correct":true},{"t":"가로 6 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 2 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 3 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 면은 6개인데 그림에는 5개뿐이에요.","빠진 면은 이미 있는 아랫면과 마주 보는 면이라 모양과 크기가 같아요.","그래서 가로 6 cm, 세로 2 cm인 직사각형이에요."],"asset":{"type":"geo","items":[{"w":224,"h":70,"seg":[[[0,0],[0,42]],[[0,0],[224,0]],[[0,42],[112,42]],[[112,42],[112,70]],[[112,70],[196,70]],[[196,42],[196,70]],[[196,42],[224,42]],[[224,0],[224,42]]],"dash":[[[84,0],[84,42]],[[112,0],[112,42]],[[112,42],[196,42]],[[196,0],[196,42]]],"grid":14}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#6','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'sa','auto','한 모서리가 2 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M5-2-u5-C7","difficulty":2,"kind":"sa","stem":"한 모서리가 2 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["전개도의 둘레(실선)에는 한 변이 2 cm인 선분이 14개 있어요.","2 × 14 = 28이에요.","그래서 28 cm예요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["전개도의 둘레(실선)에는 한 변이 3 cm인 선분이 14개 있어요.","3 × 14 = 42예요.","그래서 42 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}},{"stem":"한 모서리가 4 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["전개도의 둘레(실선)에는 한 변이 4 cm인 선분이 14개 있어요.","4 × 14 = 56이에요.","그래서 56 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#7','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'mc','auto','잘못 그린 전개도예요. 어떻게 고치면 직육면체의 전개도가 되나요?',ARRAY['M5-2-u5-X14','M5-2-u5-X16']::text[],true,'{"seq":7,"concept":"M5-2-u5-C7","difficulty":2,"kind":"mc","stem":"잘못 그린 전개도예요. 어떻게 고치면 직육면체의 전개도가 되나요?","options":[{"t":"겹치는 두 면 가운데 한 면을 반대쪽으로 옮긴다","correct":true},{"t":"면을 하나 더 그린다","mis":"M5-2-u5-X14"},{"t":"모든 점선을 실선으로 바꾼다","mis":"M5-2-u5-X16"},{"t":"한 줄의 면을 모두 지운다","mis":"M5-2-u5-X14"}],"explanation":["같은 쪽에 붙은 두 면은 접으면 같은 자리에서 겹쳐요.","한 면을 반대쪽으로 옮기면 비어 있던 자리를 채워요.","그러면 면 6개가 직육면체를 둘러싸요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,30],[90,30]],[[90,30],[90,60]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 잘못 그린 전개도예요. 어떻게 고치면 직육면체의 전개도가 되나요?","options":[{"t":"겹치는 두 면 가운데 한 면을 반대쪽으로 옮긴다","correct":true},{"t":"면을 하나 더 그린다","mis":"M5-2-u5-X14"},{"t":"모든 점선을 실선으로 바꾼다","mis":"M5-2-u5-X16"},{"t":"한 줄의 면을 모두 지운다","mis":"M5-2-u5-X14"}],"explanation":["같은 쪽에 붙은 두 면은 접으면 같은 자리에서 겹쳐요.","한 면을 반대쪽으로 옮기면 비어 있던 자리를 채워요.","그러면 면 6개가 직육면체를 둘러싸요."],"asset":{"type":"geo","items":[{"w":168,"h":140,"seg":[[[0,0],[0,84]],[[0,0],[168,0]],[[0,84],[56,84]],[[56,84],[56,140]],[[56,140],[84,140]],[[84,84],[84,140]],[[84,84],[140,84]],[[140,84],[140,140]],[[140,140],[168,140]],[[168,0],[168,140]]],"dash":[[[56,0],[56,84]],[[56,84],[84,84]],[[84,0],[84,84]],[[140,0],[140,84]],[[140,84],[168,84]]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 잘못 그린 전개도예요. 어떻게 고치면 직육면체의 전개도가 되나요?","options":[{"t":"겹치는 두 면 가운데 한 면을 반대쪽으로 옮긴다","correct":true},{"t":"면을 하나 더 그린다","mis":"M5-2-u5-X14"},{"t":"모든 점선을 실선으로 바꾼다","mis":"M5-2-u5-X16"},{"t":"한 줄의 면을 모두 지운다","mis":"M5-2-u5-X14"}],"explanation":["같은 쪽에 붙은 두 면은 접으면 같은 자리에서 겹쳐요.","한 면을 반대쪽으로 옮기면 비어 있던 자리를 채워요.","그러면 면 6개가 직육면체를 둘러싸요."],"asset":{"type":"geo","items":[{"w":180,"h":30,"seg":[[[0,0],[0,30]],[[0,0],[180,0]],[[0,30],[180,30]],[[180,0],[180,30]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[90,0],[90,30]],[[120,0],[120,30]],[[150,0],[150,30]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#8','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'error','auto','친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X16']::text[],true,'{"seq":8,"concept":"M5-2-u5-C7","difficulty":2,"kind":"error","stem":"친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「전개도에서 마주 보는 두 면은 크기가 달라도 돼.」","correct":true,"mis_target":"M5-2-u5-X14"},{"t":"도윤 — 「접었을 때 맞붙는 모서리는 길이가 같게 그려.」","mis":"M5-2-u5-X14"},{"t":"하린 — 「잘리지 않은 모서리는 점선으로 그려.」","mis":"M5-2-u5-X16"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","수아의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「잘린 모서리는 점선으로 그려.」","correct":true,"mis_target":"M5-2-u5-X16"},{"t":"서연 — 「면 6개를 겹치지 않게 이어 그려.」","mis":"M5-2-u5-X14"},{"t":"지호 — 「자르는 모서리에 따라 전개도는 여러 가지야.」","mis":"M5-2-u5-X14"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","민준의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「한 직육면체의 전개도는 한 가지뿐이야.」","correct":true,"mis_target":"M5-2-u5-X14"},{"t":"나린 — 「정육면체의 전개도는 크기가 같은 정사각형 6개야.」","mis":"M5-2-u5-X07"},{"t":"유진 — 「마주 보는 면은 모양과 크기가 같게 그려.」","mis":"M5-2-u5-X14"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","가온의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#9','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',2,'sa','auto','한 모서리가 2 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C7","difficulty":2,"kind":"sa","stem":"한 모서리가 2 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["면 6개를 잇는 점선은 5개예요.","2 × 5 = 10이에요.","그래서 10 cm예요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["면 6개를 잇는 점선은 5개예요.","3 × 5 = 15예요.","그래서 15 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}},{"stem":"한 모서리가 5 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["면 6개를 잇는 점선은 5개예요.","5 × 5 = 25예요.","그래서 25 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_basic#10','math',5,2,'u5','L07','g5_2_math_u5_L07_basic','lesson_basic','M5-2-u5-C7',3,'mc','auto','밑면이 한 변 3 cm인 정사각형이고 높이가 2 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":10,"concept":"M5-2-u5-C7","difficulty":3,"kind":"mc","stem":"밑면이 한 변 3 cm인 정사각형이고 높이가 2 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"나","correct":true},{"t":"가","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"라","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 3 cm, 세로 2 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 나예요."],"asset":{"type":"geo","items":[{"w":120,"h":50,"seg":[[[0,0],[0,50]],[[0,0],[30,0]],[[0,50],[120,50]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,50]]],"dash":[[[0,30],[30,30]],[[30,30],[30,50]],[[60,30],[60,50]],[[60,30],[90,30]],[[90,30],[90,50]]],"grid":10},{"w":120,"h":80,"seg":[[[0,0],[0,50]],[[0,0],[30,0]],[[0,50],[60,50]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,50],[60,80]],[[60,80],[90,80]],[[90,50],[90,80]],[[90,50],[120,50]],[[120,30],[120,50]]],"dash":[[[0,30],[30,30]],[[30,30],[30,50]],[[60,30],[60,50]],[[60,50],[90,50]],[[90,30],[90,50]]],"grid":10},{"w":120,"h":70,"seg":[[[0,0],[0,40]],[[0,0],[30,0]],[[0,40],[60,40]],[[30,0],[30,20]],[[30,20],[120,20]],[[60,40],[60,70]],[[60,70],[90,70]],[[90,40],[90,70]],[[90,40],[120,40]],[[120,20],[120,40]]],"dash":[[[0,20],[30,20]],[[30,20],[30,40]],[[60,20],[60,40]],[[60,40],[90,40]],[[90,20],[90,40]]],"grid":10},{"w":120,"h":50,"seg":[[[0,0],[0,20]],[[0,0],[120,0]],[[0,20],[90,20]],[[90,20],[90,50]],[[90,50],[120,50]],[[120,0],[120,50]]],"dash":[[[30,0],[30,20]],[[60,0],[60,20]],[[90,0],[90,20]],[[90,20],[120,20]]],"grid":10}],"tag":true},"variant_rule":{"alt":[{"stem":"밑면이 한 변 2 cm인 정사각형이고 높이가 4 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"라","correct":true},{"t":"가","mis":"M5-2-u5-X14"},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 2 cm, 세로 4 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 라예요."],"asset":{"type":"geo","items":[{"w":80,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[20,0]],[[0,60],[80,60]],[[20,0],[20,20]],[[20,20],[40,20]],[[40,0],[40,20]],[[40,0],[60,0]],[[60,0],[60,20]],[[60,20],[80,20]],[[80,20],[80,60]]],"dash":[[[0,20],[20,20]],[[20,20],[20,60]],[[40,20],[40,60]],[[40,20],[60,20]],[[60,20],[60,60]]],"grid":10},{"w":80,"h":100,"seg":[[[0,0],[0,80]],[[0,0],[20,0]],[[0,80],[40,80]],[[20,0],[20,40]],[[20,40],[80,40]],[[40,80],[40,100]],[[40,100],[60,100]],[[60,80],[60,100]],[[60,80],[80,80]],[[80,40],[80,80]]],"dash":[[[0,40],[20,40]],[[20,40],[20,80]],[[40,40],[40,80]],[[40,80],[60,80]],[[60,40],[60,80]]],"grid":10},{"w":80,"h":60,"seg":[[[0,0],[0,40]],[[0,0],[80,0]],[[0,40],[60,40]],[[60,40],[60,60]],[[60,60],[80,60]],[[80,0],[80,60]]],"dash":[[[20,0],[20,40]],[[40,0],[40,40]],[[60,0],[60,40]],[[60,40],[80,40]]],"grid":10},{"w":80,"h":80,"seg":[[[0,0],[0,60]],[[0,0],[20,0]],[[0,60],[20,60]],[[20,0],[20,20]],[[20,20],[80,20]],[[20,60],[20,80]],[[20,80],[40,80]],[[40,60],[40,80]],[[40,60],[80,60]],[[80,20],[80,60]]],"dash":[[[0,20],[20,20]],[[20,20],[20,60]],[[20,60],[40,60]],[[40,20],[40,60]],[[60,20],[60,60]]],"grid":10}],"tag":true}},{"stem":"밑면이 한 변 4 cm인 정사각형이고 높이가 1 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가","correct":true},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"라","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 4 cm, 세로 1 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 가예요."],"asset":{"type":"geo","items":[{"w":160,"h":90,"seg":[[[0,0],[0,50]],[[0,0],[40,0]],[[0,50],[120,50]],[[40,0],[40,40]],[[40,40],[160,40]],[[120,50],[120,90]],[[120,90],[160,90]],[[160,40],[160,90]]],"dash":[[[0,40],[40,40]],[[40,40],[40,50]],[[80,40],[80,50]],[[120,40],[120,50]],[[120,50],[160,50]]],"grid":10},{"w":160,"h":50,"seg":[[[0,0],[0,50]],[[0,0],[40,0]],[[0,50],[160,50]],[[40,0],[40,40]],[[40,40],[80,40]],[[80,0],[80,40]],[[80,0],[120,0]],[[120,0],[120,40]],[[120,40],[160,40]],[[160,40],[160,50]]],"dash":[[[0,40],[40,40]],[[40,40],[40,50]],[[80,40],[80,50]],[[80,40],[120,40]],[[120,40],[120,50]]],"grid":10},{"w":160,"h":60,"seg":[[[0,0],[0,20]],[[0,0],[40,0]],[[0,20],[80,20]],[[40,0],[40,10]],[[40,10],[160,10]],[[80,20],[80,60]],[[80,60],[120,60]],[[120,20],[120,60]],[[120,20],[160,20]],[[160,10],[160,20]]],"dash":[[[0,10],[40,10]],[[40,10],[40,20]],[[80,10],[80,20]],[[80,20],[120,20]],[[120,10],[120,20]]],"grid":10},{"w":160,"h":50,"seg":[[[0,0],[0,10]],[[0,0],[160,0]],[[0,10],[120,10]],[[120,10],[120,50]],[[120,50],[160,50]],[[160,0],[160,50]]],"dash":[[[40,0],[40,10]],[[80,0],[80,10]],[[120,0],[120,10]],[[120,10],[160,10]]],"grid":10}],"tag":true}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#1','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',2,'ox','auto','한 직육면체의 전개도는 한 가지로만 그릴 수 있어요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":1,"concept":"M5-2-u5-C7","difficulty":2,"kind":"ox","stem":"한 직육면체의 전개도는 한 가지로만 그릴 수 있어요.","answer":"X","reason_options":[{"t":"자르는 모서리에 따라 여러 가지로 그릴 수 있으므로","correct":true},{"t":"직육면체 모양이 하나이므로","mis":"M5-2-u5-X14"}],"mis":"M5-2-u5-X14","explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「자르는 모서리에 따라 여러 가지로 그릴 수 있으므로」를 골라요."],"variant_rule":{"alt":[{"stem":"전개도에서 접었을 때 맞붙는 두 모서리는 길이가 달라도 돼요.","answer":"X","reason_options":[{"t":"맞붙는 두 모서리는 한 모서리가 되므로 길이가 같아야 하므로","correct":true},{"t":"접으면 길이가 맞춰지므로","mis":"M5-2-u5-X14"}],"explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 X예요.","까닭으로 「맞붙는 두 모서리는 한 모서리가 되므로 길이가 같아야 하므로」를 골라요."]},{"stem":"직육면체의 전개도에는 면을 6개 그려요.","answer":"O","reason_options":[{"t":"직육면체의 면이 6개이므로","correct":true},{"t":"보이는 면 3개만 그리면 되므로","mis":"M5-2-u5-X04"}],"explanation":["전개도를 그리는 약속을 떠올려요.","맞는 말이면 O, 틀린 말이면 X — 정답은 O예요.","까닭으로 「직육면체의 면이 6개이므로」를 골라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#2','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',2,'mc','auto','한 모서리가 5 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?',ARRAY['M5-2-u5-X07','M5-2-u5-X04']::text[],true,'{"seq":2,"concept":"M5-2-u5-C7","difficulty":2,"kind":"mc","stem":"한 모서리가 5 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 5 cm인 정사각형 6개","correct":true},{"t":"가로 5 cm, 세로 10 cm인 직사각형 6개","mis":"M5-2-u5-X07"},{"t":"한 변이 5 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 10 cm인 정사각형 6개","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 5 cm이니 한 변이 5 cm인 정사각형이에요.","면이 6개니 6개를 그려요."],"variant_rule":{"alt":[{"stem":"한 모서리가 6 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 6 cm인 정사각형 6개","correct":true},{"t":"가로 6 cm, 세로 12 cm인 직사각형 6개","mis":"M5-2-u5-X07"},{"t":"한 변이 6 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 12 cm인 정사각형 6개","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 6 cm이니 한 변이 6 cm인 정사각형이에요.","면이 6개니 6개를 그려요."]},{"stem":"한 모서리가 7 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 7 cm인 정사각형 6개","correct":true},{"t":"가로 7 cm, 세로 14 cm인 직사각형 6개","mis":"M5-2-u5-X07"},{"t":"한 변이 7 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 14 cm인 정사각형 6개","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 7 cm이니 한 변이 7 cm인 정사각형이에요.","면이 6개니 6개를 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#3','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'sa','auto','모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M5-2-u5-C7","difficulty":3,"kind":"sa","stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["모눈을 세면 가로 3 cm, 세로 2 cm, 높이 1 cm인 직육면체예요.","3 × 4 + 2 × 4 + 1 × 4 = 24예요.","그래서 24 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":140,"h":70,"seg":[[[0,0],[0,42]],[[0,0],[42,0]],[[0,42],[70,42]],[[42,0],[42,28]],[[42,28],[140,28]],[[70,42],[70,70]],[[70,70],[112,70]],[[112,42],[112,70]],[[112,42],[140,42]],[[140,28],[140,42]]],"dash":[[[0,28],[42,28]],[[42,28],[42,42]],[[70,28],[70,42]],[[70,42],[112,42]],[[112,28],[112,42]]],"grid":14}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["모눈을 세면 가로 2 cm, 세로 1 cm, 높이 4 cm인 직육면체예요.","2 × 4 + 1 × 4 + 4 × 4 = 28이에요.","그래서 28 cm예요."],"asset":{"type":"geo","items":[{"w":84,"h":84,"seg":[[[0,0],[0,70]],[[0,0],[28,0]],[[0,70],[42,70]],[[28,0],[28,14]],[[28,14],[84,14]],[[42,70],[42,84]],[[42,84],[70,84]],[[70,70],[70,84]],[[70,70],[84,70]],[[84,14],[84,70]]],"dash":[[[0,14],[28,14]],[[28,14],[28,70]],[[42,14],[42,70]],[[42,70],[70,70]],[[70,14],[70,70]]],"grid":14}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["모눈을 세면 가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체예요.","4 × 4 + 2 × 4 + 3 × 4 = 36이에요.","그래서 36 cm예요."],"asset":{"type":"geo","items":[{"w":168,"h":98,"seg":[[[0,0],[0,70]],[[0,0],[56,0]],[[0,70],[84,70]],[[56,0],[56,28]],[[56,28],[168,28]],[[84,70],[84,98]],[[84,98],[140,98]],[[140,70],[140,98]],[[140,70],[168,70]],[[168,28],[168,70]]],"dash":[[[0,28],[56,28]],[[56,28],[56,70]],[[84,28],[84,70]],[[84,70],[140,70]],[[140,28],[140,70]]],"grid":14}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#4','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'mc','auto','밑면이 한 변 2 cm인 정사각형이고 높이가 3 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":4,"concept":"M5-2-u5-C7","difficulty":3,"kind":"mc","stem":"밑면이 한 변 2 cm인 정사각형이고 높이가 3 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"다","correct":true},{"t":"가","mis":"M5-2-u5-X14"},{"t":"나","mis":"M5-2-u5-X14"},{"t":"라","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 2 cm, 세로 3 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 다예요."],"asset":{"type":"geo","items":[{"w":80,"h":50,"seg":[[[0,0],[0,50]],[[0,0],[20,0]],[[0,50],[80,50]],[[20,0],[20,20]],[[20,20],[40,20]],[[40,0],[40,20]],[[40,0],[60,0]],[[60,0],[60,20]],[[60,20],[80,20]],[[80,20],[80,50]]],"dash":[[[0,20],[20,20]],[[20,20],[20,50]],[[40,20],[40,50]],[[40,20],[60,20]],[[60,20],[60,50]]],"grid":10},{"w":80,"h":80,"seg":[[[0,0],[0,60]],[[0,0],[20,0]],[[0,60],[40,60]],[[20,0],[20,30]],[[20,30],[80,30]],[[40,60],[40,80]],[[40,80],[60,80]],[[60,60],[60,80]],[[60,60],[80,60]],[[80,30],[80,60]]],"dash":[[[0,30],[20,30]],[[20,30],[20,60]],[[40,30],[40,60]],[[40,60],[60,60]],[[60,30],[60,60]]],"grid":10},{"w":80,"h":70,"seg":[[[0,0],[0,50]],[[0,0],[20,0]],[[0,50],[20,50]],[[20,0],[20,20]],[[20,20],[80,20]],[[20,50],[20,70]],[[20,70],[40,70]],[[40,50],[40,70]],[[40,50],[80,50]],[[80,20],[80,50]]],"dash":[[[0,20],[20,20]],[[20,20],[20,50]],[[20,50],[40,50]],[[40,20],[40,50]],[[60,20],[60,50]]],"grid":10},{"w":80,"h":50,"seg":[[[0,0],[0,30]],[[0,0],[80,0]],[[0,30],[60,30]],[[60,30],[60,50]],[[60,50],[80,50]],[[80,0],[80,50]]],"dash":[[[20,0],[20,30]],[[40,0],[40,30]],[[60,0],[60,30]],[[60,30],[80,30]]],"grid":10}],"tag":true},"variant_rule":{"alt":[{"stem":"밑면이 한 변 3 cm인 정사각형이고 높이가 1 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"가","correct":true},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"},{"t":"라","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 3 cm, 세로 1 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 가예요."],"asset":{"type":"geo","items":[{"w":120,"h":70,"seg":[[[0,0],[0,40]],[[0,0],[30,0]],[[0,40],[90,40]],[[30,0],[30,30]],[[30,30],[120,30]],[[90,40],[90,70]],[[90,70],[120,70]],[[120,30],[120,70]]],"dash":[[[0,30],[30,30]],[[30,30],[30,40]],[[60,30],[60,40]],[[90,30],[90,40]],[[90,40],[120,40]]],"grid":10},{"w":120,"h":40,"seg":[[[0,0],[0,40]],[[0,0],[30,0]],[[0,40],[120,40]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,40]]],"dash":[[[0,30],[30,30]],[[30,30],[30,40]],[[60,30],[60,40]],[[60,30],[90,30]],[[90,30],[90,40]]],"grid":10},{"w":120,"h":50,"seg":[[[0,0],[0,20]],[[0,0],[30,0]],[[0,20],[60,20]],[[30,0],[30,10]],[[30,10],[120,10]],[[60,20],[60,50]],[[60,50],[90,50]],[[90,20],[90,50]],[[90,20],[120,20]],[[120,10],[120,20]]],"dash":[[[0,10],[30,10]],[[30,10],[30,20]],[[60,10],[60,20]],[[60,20],[90,20]],[[90,10],[90,20]]],"grid":10},{"w":120,"h":40,"seg":[[[0,0],[0,10]],[[0,0],[120,0]],[[0,10],[90,10]],[[90,10],[90,40]],[[90,40],[120,40]],[[120,0],[120,40]]],"dash":[[[30,0],[30,10]],[[60,0],[60,10]],[[90,0],[90,10]],[[90,10],[120,10]]],"grid":10}],"tag":true}},{"stem":"밑면이 한 변 1 cm인 정사각형이고 높이가 3 cm인 직육면체의 전개도를 바르게 그린 것은 어느 것인가요? 모눈 한 칸은 1 cm예요.","options":[{"t":"라","correct":true},{"t":"가","mis":"M5-2-u5-X14"},{"t":"나","mis":"M5-2-u5-X14"},{"t":"다","mis":"M5-2-u5-X14"}],"explanation":["정사각형 밑면 2개와 가로 1 cm, 세로 3 cm인 옆면 4개가 있어야 해요.","겹치는 면이 없고 맞붙는 선분의 길이가 같아야 해요.","그래서 라예요."],"asset":{"type":"geo","items":[{"w":40,"h":40,"seg":[[[0,0],[0,40]],[[0,0],[10,0]],[[0,40],[40,40]],[[10,0],[10,10]],[[10,10],[20,10]],[[20,0],[20,10]],[[20,0],[30,0]],[[30,0],[30,10]],[[30,10],[40,10]],[[40,1