INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#5','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'mc','auto','우리 마을 모형을 만들려고 가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리다 멈췄어요. 모눈 한 칸은 1 cm예요. 빠진 면 하나는 어떤 직사각형인가요?',ARRAY['M5-2-u5-X14']::text[],true,'{"seq":5,"concept":"M5-2-u5-C7","difficulty":3,"kind":"mc","stem":"우리 마을 모형을 만들려고 가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리다 멈췄어요. 모눈 한 칸은 1 cm예요. 빠진 면 하나는 어떤 직사각형인가요?","options":[{"t":"가로 4 cm, 세로 2 cm인 직사각형","correct":true},{"t":"가로 4 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 2 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 3 cm, 세로 3 cm인 직사각형","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 면은 6개인데 그림에는 5개뿐이에요.","빠진 면은 이미 있는 윗면과 마주 보는 면이라 모양과 크기가 같아요.","그래서 가로 4 cm, 세로 2 cm인 직사각형이에요."],"asset":{"type":"geo","items":[{"w":168,"h":70,"seg":[[[0,0],[0,70]],[[0,0],[56,0]],[[0,70],[168,70]],[[56,0],[56,28]],[[56,28],[168,28]],[[168,28],[168,70]]],"dash":[[[0,28],[56,28]],[[56,28],[56,70]],[[84,28],[84,70]],[[140,28],[140,70]]],"grid":14}],"tag":false},"variant_rule":{"alt":[{"stem":"우리 마을 모형을 만들려고 가로 5 cm, 세로 3 cm, 높이 1 cm인 직육면체의 전개도를 그리다 멈췄어요. 모눈 한 칸은 1 cm예요. 빠진 면 하나는 어떤 직사각형인가요?","options":[{"t":"가로 5 cm, 세로 3 cm인 직사각형","correct":true},{"t":"가로 5 cm, 세로 1 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 3 cm, 세로 1 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 1 cm, 세로 1 cm인 직사각형","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 면은 6개인데 그림에는 5개뿐이에요.","빠진 면은 이미 있는 아랫면과 마주 보는 면이라 모양과 크기가 같아요.","그래서 가로 5 cm, 세로 3 cm인 직사각형이에요."],"asset":{"type":"geo","items":[{"w":224,"h":56,"seg":[[[0,0],[0,14]],[[0,0],[224,0]],[[0,14],[112,14]],[[112,14],[112,56]],[[112,56],[182,56]],[[182,14],[182,56]],[[182,14],[224,14]],[[224,0],[224,14]]],"dash":[[[70,0],[70,14]],[[112,0],[112,14]],[[112,14],[182,14]],[[182,0],[182,14]]],"grid":14}],"tag":false}},{"stem":"우리 마을 모형을 만들려고 가로 3 cm, 세로 1 cm, 높이 2 cm인 직육면체의 전개도를 그리다 멈췄어요. 모눈 한 칸은 1 cm예요. 빠진 면 하나는 어떤 직사각형인가요?","options":[{"t":"가로 3 cm, 세로 1 cm인 직사각형","correct":true},{"t":"가로 3 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 1 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X14"},{"t":"가로 2 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X14"}],"explanation":["직육면체의 면은 6개인데 그림에는 5개뿐이에요.","빠진 면은 이미 있는 윗면과 마주 보는 면이라 모양과 크기가 같아요.","그래서 가로 3 cm, 세로 1 cm인 직사각형이에요."],"asset":{"type":"geo","items":[{"w":112,"h":42,"seg":[[[0,0],[0,42]],[[0,0],[42,0]],[[0,42],[112,42]],[[42,0],[42,14]],[[42,14],[112,14]],[[112,14],[112,42]]],"dash":[[[0,14],[42,14]],[[42,14],[42,42]],[[56,14],[56,42]],[[98,14],[98,42]]],"grid":14}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#6','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'error','auto','친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X16','M5-2-u5-X14']::text[],true,'{"seq":6,"concept":"M5-2-u5-C7","difficulty":3,"kind":"error","stem":"친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「잘린 모서리는 점선으로 그려.」","correct":true,"mis_target":"M5-2-u5-X16"},{"t":"라온 — 「면 6개를 겹치지 않게 이어 그려.」","mis":"M5-2-u5-X14"},{"t":"예준 — 「자르는 모서리에 따라 전개도는 여러 가지야.」","mis":"M5-2-u5-X14"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","여울의 말이 틀렸어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「한 직육면체의 전개도는 한 가지뿐이야.」","correct":true,"mis_target":"M5-2-u5-X14"},{"t":"도윤 — 「정육면체의 전개도는 크기가 같은 정사각형 6개야.」","mis":"M5-2-u5-X07"},{"t":"하린 — 「마주 보는 면은 모양과 크기가 같게 그려.」","mis":"M5-2-u5-X14"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","수아의 말이 틀렸어요."]},{"stem":"이번에는 다른 보기예요. 친구들이 직육면체의 전개도를 그리며 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"민준 — 「전개도에서 마주 보는 두 면은 크기가 달라도 돼.」","correct":true,"mis_target":"M5-2-u5-X14"},{"t":"서연 — 「접었을 때 맞붙는 모서리는 길이가 같게 그려.」","mis":"M5-2-u5-X14"},{"t":"지호 — 「잘리지 않은 모서리는 점선으로 그려.」","mis":"M5-2-u5-X16"}],"explanation":["면 6개를 겹치지 않게, 맞붙는 모서리는 같은 길이로, 마주 보는 면은 같은 모양과 크기로 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요.","민준의 말이 틀렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#7','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',3,'sa','auto','한 모서리가 6 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M5-2-u5-C7","difficulty":3,"kind":"sa","stem":"한 모서리가 6 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["전개도의 둘레(실선)에는 한 변이 6 cm인 선분이 14개 있어요.","6 × 14 = 84예요.","그래서 84 cm예요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 7 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["면 6개를 잇는 점선은 5개예요.","7 × 5 = 35예요.","그래서 35 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}},{"stem":"한 모서리가 5 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["전개도의 둘레(실선)에는 한 변이 5 cm인 선분이 14개 있어요.","5 × 14 = 70이에요.","그래서 70 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#8','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',4,'sa','auto','모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C7","difficulty":4,"kind":"sa","stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["모눈을 세면 가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체예요.","5 × 4 + 3 × 4 + 2 × 4 = 40이에요.","그래서 40 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":224,"h":112,"seg":[[[0,0],[0,70]],[[0,0],[70,0]],[[0,70],[112,70]],[[70,0],[70,42]],[[70,42],[224,42]],[[112,70],[112,112]],[[112,112],[182,112]],[[182,70],[182,112]],[[182,70],[224,70]],[[224,42],[224,70]]],"dash":[[[0,42],[70,42]],[[70,42],[70,70]],[[112,42],[112,70]],[[112,70],[182,70]],[[182,42],[182,70]]],"grid":14}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["모눈을 세면 가로 3 cm, 세로 2 cm, 높이 4 cm인 직육면체예요.","3 × 4 + 2 × 4 + 4 × 4 = 36이에요.","그래서 36 cm예요."],"asset":{"type":"geo","items":[{"w":140,"h":112,"seg":[[[0,0],[0,84]],[[0,0],[42,0]],[[0,84],[70,84]],[[42,0],[42,28]],[[42,28],[140,28]],[[70,84],[70,112]],[[70,112],[112,112]],[[112,84],[112,112]],[[112,84],[140,84]],[[140,28],[140,84]]],"dash":[[[0,28],[42,28]],[[42,28],[42,84]],[[70,28],[70,84]],[[70,84],[112,84]],[[112,28],[112,84]]],"grid":14}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 이 전개도를 접어 만든 직육면체의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["모눈을 세면 가로 4 cm, 세로 3 cm, 높이 1 cm인 직육면체예요.","4 × 4 + 3 × 4 + 1 × 4 = 32예요.","그래서 32 cm예요."],"asset":{"type":"geo","items":[{"w":196,"h":98,"seg":[[[0,0],[0,56]],[[0,0],[56,0]],[[0,56],[98,56]],[[56,0],[56,42]],[[56,42],[196,42]],[[98,56],[98,98]],[[98,98],[154,98]],[[154,56],[154,98]],[[154,56],[196,56]],[[196,42],[196,56]]],"dash":[[[0,42],[56,42]],[[56,42],[56,56]],[[98,42],[98,56]],[[98,56],[154,56]],[[154,42],[154,56]]],"grid":14}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#9','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',4,'sa','auto','모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C7","difficulty":4,"kind":"sa","stem":"모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["둘레를 따라 실선의 길이를 차례로 세어요.","3 + 2 + 2 + 3 + 2 + 1 + 2 + 3 + 2 + 2 + 3 + 2 + 1 + 2 = 30이에요.","그래서 30 cm예요 — 잘린 모서리 하나가 둘레에 두 번씩 나와요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":140,"h":70,"seg":[[[0,0],[0,70]],[[0,0],[42,0]],[[0,70],[42,70]],[[42,0],[42,28]],[[42,28],[140,28]],[[42,42],[42,70]],[[42,42],[140,42]],[[140,28],[140,42]]],"dash":[[[0,28],[42,28]],[[0,42],[42,42]],[[42,28],[42,42]],[[70,28],[70,42]],[[112,28],[112,42]]],"grid":14}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["38"],"explanation":["둘레를 따라 실선의 길이를 차례로 세어요.","4 + 2 + 2 + 4 + 2 + 3 + 2 + 2 + 4 + 2 + 2 + 4 + 3 + 2 = 38이에요.","그래서 38 cm예요 — 잘린 모서리 하나가 둘레에 두 번씩 나와요."],"asset":{"type":"geo","items":[{"w":168,"h":98,"seg":[[[0,0],[0,70]],[[0,0],[56,0]],[[0,70],[84,70]],[[56,0],[56,28]],[[56,28],[168,28]],[[84,70],[84,98]],[[84,98],[140,98]],[[140,70],[140,98]],[[140,70],[168,70]],[[168,28],[168,70]]],"dash":[[[0,28],[56,28]],[[56,28],[56,70]],[[84,28],[84,70]],[[84,70],[140,70]],[[140,28],[140,70]]],"grid":14}],"tag":false}},{"stem":"이번에는 다른 보기예요. 모눈 한 칸이 1 cm인 모눈종이에 그린 직육면체의 전개도예요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["둘레를 따라 실선의 길이를 차례로 세어요.","3 + 3 + 3 + 3 + 3 + 2 + 3 + 3 + 3 + 3 + 3 + 3 + 2 + 3 = 40이에요.","그래서 40 cm예요 — 잘린 모서리 하나가 둘레에 두 번씩 나와요."],"asset":{"type":"geo","items":[{"w":168,"h":112,"seg":[[[0,0],[0,70]],[[0,0],[42,0]],[[0,70],[84,70]],[[42,0],[42,42]],[[42,42],[168,42]],[[84,70],[84,112]],[[84,112],[126,112]],[[126,70],[126,112]],[[126,70],[168,70]],[[168,42],[168,70]]],"dash":[[[0,42],[42,42]],[[42,42],[42,70]],[[84,42],[84,70]],[[84,70],[126,70]],[[126,42],[126,70]]],"grid":14}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L07_challenge#10','math',5,2,'u5','L07','g5_2_math_u5_L07_challenge','lesson_challenge','M5-2-u5-C7',4,'essay','teacher','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리려고 해요. 어떤 직사각형을 몇 개씩 그려야 하는지 쓰고, 전개도를 그릴 때 지켜야 할 약속 두 가지를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C7","difficulty":4,"kind":"essay","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체의 전개도를 그리려고 해요. 어떤 직사각형을 몇 개씩 그려야 하는지 쓰고, 전개도를 그릴 때 지켜야 할 약속 두 가지를 쓰세요.","answer_guide":{"answer":"예: 가로 4 cm, 세로 2 cm인 직사각형 2개, 가로 4 cm, 세로 3 cm인 직사각형 2개, 가로 2 cm, 세로 3 cm인 직사각형 2개를 그린다. 면 6개를 겹치지 않게 이어 그리고, 접었을 때 맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그린다. 잘린 모서리는 실선, 잘리지 않은 모서리는 점선으로 그린다.","scoring_points":["세 가지 직사각형을 2개씩 썼는가","맞붙는 모서리 길이를 같게 그린다고 썼는가","실선·점선 또는 마주 보는 면 약속을 썼는가"]},"explanation":["마주 보는 면은 모양과 크기가 같아 세 가지 직사각형이 2개씩이에요.","맞붙는 모서리는 길이가 같게 그려요.","잘린 모서리는 실선, 잘리지 않은 모서리는 점선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L08_basic#1','math',5,2,'u5','L08','g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',1,'match','auto','주사위의 전개도를 접었을 때 평행한 면끼리 알맞게 이어 보세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C8","difficulty":1,"kind":"match","stem":"주사위의 전개도를 접었을 때 평행한 면끼리 알맞게 이어 보세요.","pairs":[{"l":"1과 평행한 면","r":"6"},{"l":"2와 평행한 면","r":"5"},{"l":"3과 평행한 면","r":"4"}],"mis":"M5-2-u5-X12","explanation":["전개도를 접으면 하나 건너 있는 면끼리 마주 봐요.","주사위는 1과 6, 2와 5, 3과 4가 평행해요.","평행한 두 면의 눈의 수를 더하면 7이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주사위의 전개도를 접었을 때 평행한 면끼리 알맞게 이어 보세요.","pairs":[{"l":"4와 평행한 면","r":"3"},{"l":"5와 평행한 면","r":"2"},{"l":"6과 평행한 면","r":"1"}],"explanation":["전개도를 접으면 하나 건너 있는 면끼리 마주 봐요.","주사위는 1과 6, 2와 5, 3과 4가 평행해요.","평행한 두 면의 눈의 수를 더하면 7이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 주사위의 전개도를 접었을 때 평행한 면끼리 알맞게 이어 보세요.","pairs":[{"l":"1과 평행한 면","r":"6"},{"l":"3과 평행한 면","r":"4"},{"l":"5와 평행한 면","r":"2"}],"explanation":["전개도를 접으면 하나 건너 있는 면끼리 마주 봐요.","주사위는 1과 6, 2와 5, 3과 4가 평행해요.","평행한 두 면의 눈의 수를 더하면 7이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
