INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L08_basic#4','math',5,2,'u5','L08','g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',1,'mc','auto','주사위의 전개도예요. 눈의 수 1과 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":4,"concept":"M5-2-u5-C8","difficulty":1,"kind":"mc","stem":"주사위의 전개도예요. 눈의 수 1과 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"2, 3, 4, 5","correct":true},{"t":"2, 3, 4, 6","mis":"M5-2-u5-X12"},{"t":"3, 4, 5, 6","mis":"M5-2-u5-X12"},{"t":"2, 3, 4, 5, 6","mis":"M5-2-u5-X13"}],"explanation":["1과 평행한 면은 6 하나예요.","나머지 네 면이 1과 수직이에요.","정답은 2, 3, 4, 5예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"주사위의 전개도예요. 눈의 수 2와 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 3, 4, 6","correct":true},{"t":"1, 3, 4, 5","mis":"M5-2-u5-X12"},{"t":"3, 4, 5, 6","mis":"M5-2-u5-X12"},{"t":"1, 3, 4, 5, 6","mis":"M5-2-u5-X13"}],"explanation":["2와 평행한 면은 5 하나예요.","나머지 네 면이 2와 수직이에요.","정답은 1, 3, 4, 6이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0]