INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L08_basic#7','math',5,2,'u5','L08','g5_2_math_u5_L08_basic','lesson_basic','M5-2-u5-C8',2,'mc','auto','명령을 반복하는 횟수가 아주 많을 때 알맞은 해결 방법은 어느 것인가요?',ARRAY['M5-2-u5-X17']::text[],true,'{"seq":7,"concept":"M5-2-u5-C8","difficulty":2,"kind":"mc","stem":"명령을 반복하는 횟수가 아주 많을 때 알맞은 해결 방법은 어느 것인가요?","options":[{"t":"몇 번 굴려 보고 되풀이되는 규칙을 찾는다","correct":true},{"t":"반복 횟수만큼 모두 굴려 본다","mis":"M5-2-u5-X17"},{"t":"눈의 수를 모두 더한다","mis":"M5-2-u5-X17"},{"t":"시작하는 수를 바꾼다","mis":"M5-2-u5-X17"}],"explanation":["평행한 면과 수직인 면을 먼저 찾아요.","몇 번 실행해 되풀이되는 규칙을 찾으면 끝까지 굴리지 않아도 돼요.","정답은 「몇 번 굴려 보고 되풀이되는 규칙을 찾는다」예요."],"variant_rule":{"alt":[{"stem":"주사위 굴리기 결과가 2번마다 처음 수로 되풀이돼요. 10번 실행한 결과는 어떻게 알 수 있나요?","options":[{"t":"10은 2로 나누어떨어지므로 처음 수와 같다","correct":true},{"t":"10번 모두 굴려야만 알 수 있다","mis":"M5-2-u5-X17"},{"t":"1번 실행한 결과와 같다","mis":"M5-2-u5-X17"},{"t":"알 수 없다","mis":"M5-2-u5-X17"}],"explanation":["평행한 면과 수직인 면을 먼저 찾아요.","몇 번 실행해 되풀이되는 규칙을 찾으면 끝까지 굴리지 않아도 돼요.","정답은 「10은 2로 나누어떨어지므로 처음 수와 같다」예요."]},{"stem":"주사위 전개도에서 평행한 두 면의 눈의 수를 바르게 말한 것은 어느 것인가요?","options":[{"t":"평행한 두 면의 눈의 수를 더하면 7이다","correct":true},{"t":"이웃한 두 면의 눈의 수를 더하면 7이다","mis":"M5-2-u5-X12"},{"t":"평행한 두 면의 눈의 수는 같다","mis":"M5-2-u5-X12"},{"t":"평행한 두 면의 눈의 수를 더하면 6이다","mis":"M5-2-u5-X12"}],"explanation":["평행한 면과 수직인 면을 먼저 찾아요.","몇 번 실행해 되풀이되는 규칙을 찾으면 끝까지 굴리지 않아도 돼요.","정답은 「평행한 두 면의 눈의 수를 더하면 7이다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
