INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L08_challenge#2','math',5,2,'u5','L08','g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',2,'sa','auto','눈의 수를 특별하게 적은 주사위의 전개도예요. 전개도를 접었을 때 눈의 수 1과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 전개도를 접었을 때 눈의 수 1과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 1과 마주 보는 면은 4예요.","그래서 4예요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[90,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[120,30]],[[90,60],[90,90]],[[90,90],[120,90]],[[120,30],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,60],[120,60]]],"lab":[[[45.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[105.0,40.0],"5"],[[105.0,70.0],"4"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 전개도를 접었을 때 눈의 수 2와 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 2와 마주 보는 면은 3이에요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[90,0]],[[0,30],[60,30]],[[60,30],[60,60]],[[60,60],[150,60]],[[90,0],[90,30]],[[90,30],[150,30]],[[150,30],[150,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[60,30],[90,30]],[[90,30],[90,60]],[[120,30],[120,60]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"2"],[[75.0,10.0],"5"],[[75.0,40.0],"4"],[[105.0,40.0],"3"],[[135.0,40.0],"6"]]}],"tag":false}},{"stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 전개도를 접었을 때 눈의 수 3과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 3과 마주 보는 면은 6이에요.","그래서 6이에요."],"asset":{"type":"geo","items"