INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L08_challenge#5','math',5,2,'u5','L08','g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',3,'mc','auto','눈의 수를 특별하게 적은 주사위의 전개도예요. 눈의 수 1과 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?',ARRAY['M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":5,"concept":"M5-2-u5-C8","difficulty":3,"kind":"mc","stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 눈의 수 1과 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"2, 3, 5, 6","correct":true},{"t":"2, 3, 4, 5","mis":"M5-2-u5-X12"},{"t":"3, 4, 5, 6","mis":"M5-2-u5-X12"},{"t":"2, 3, 4, 5, 6","mis":"M5-2-u5-X13"}],"explanation":["1과 평행한 면은 4 하나예요.","나머지 네 면이 1과 수직이에요.","정답은 2, 3, 5, 6이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[90,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[120,30]],[[90,60],[90,90]],[[90,90],[120,90]],[[120,30],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,60],[120,60]]],"lab":[[[45.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[105.0,40.0],"5"],[[105.0,70.0],"4"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 눈의 수 3과 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 4, 5, 6","correct":true},{"t":"1, 2, 4, 5","mis":"M5-2-u5-X12"},{"t":"2, 4, 5, 6","mis":"M5-2-u5-X12"},{"t":"1, 2, 4, 5, 6","mis":"M5-2-u5-X13"}],"explanation":["3과 평행한 면은 2 하나예요.","나머지 네 면이 3과 수직이에요.","정답은 1, 4, 5, 6이에요."],"asset":{"type":"geo","items":[{"w":150,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[90,0]],[[0,30],[60,30]],[[60,30],[60,60]],[[60,60],[150,60]],[[90,0],[90,30]],[[90,30],[150,30]],[[150,30],[150,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[60,30],[90,30]],[[90,30],[90,60]],[[120,30],[120,60]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"2"],[[75.0,10.0],"5"],[[75.0,40.0],"4"],[[105.0,40.0],"3"],[[135.0,40.0],"6"]]}],"tag":false}},{"stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 눈의 수 6과 수직인 면의 눈의 수를 모두 고른 것은 어느 것인가요?","options":[{"t":"1, 2, 4, 5","correct":true},{"t":"1, 2, 3, 4","mis":"M5-2-u5-X12"},{"t":"2, 3, 4, 5","mis":"M5-2-u5-X12"},{"t":"1, 2, 3, 4, 5","mis":"M5-2-u5-X13"}],"explanation":["6과 평행한 면은 3 하나예요.","나머지 네 면이 6과 수직이에요.","정답은 1, 2, 4, 5예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[45.0,10.0],"1"],[[15.0,40.0],"3"],[[45.0,40.0],"4"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"5"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L08_challenge#6','math',5,2,'u5','L08','g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',3,'error','auto','주사위를 굴리는 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M5-2-u5-X17','M5-2-u5-X12','M5-2-u5-X13']::text[],true,'{"seq":6,"concept":"M5-2-u5-C8","difficulty":3,"kind":"error","stem":"주사위를 굴리는 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「4에서 시작해 가장 큰 수를 고르는 명령으로 1번 하면 5가 보여.」","correct":true,"mis_target":"M5-2-u5-X17"},{"t":"나린 — 「4와 평행한 면은 3이야.」","mis":"M5-2-u5-X12"},{"t":"유진 — 「3과 수직인 면 가운데 가장 큰 수는 6이야.」","mis":"M5-2-u5-X13"}],"explanation":["주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","가온의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 주사위를 굴리는 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「반복 횟수가 많으면 끝까지 다 굴려야만 알 수 있어.」","correct":true,"mis_target":"M5-2-u5-X17"},{"t":"라온 — 「몇 번 굴려 보고 규칙을 찾으면 돼.」","mis":"M5-2-u5-X17"},{"t":"예준 — 「평행한 두 면의 수를 더하면 7이야.」","mis":"M5-2-u5-X12"}],"explanation":["주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","여울의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 주사위를 굴리는 프로그램을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"수아 — 「1과 평행한 면은 바로 옆에 붙은 2야.」","correct":true,"mis_target":"M5-2-u5-X12"},{"t":"도윤 — 「1과 평행한 면은 6이야.」","mis":"M5-2-u5-X12"},{"t":"하린 — 「1과 수직인 면은 2, 3, 4, 5야.」","mis":"M5-2-u5-X13"}],"explanation":["주사위는 1과 6, 2와 5, 3과 4가 평행해요.","명령은 평행한 면으로 굴린 뒤 그 면과 수직인 면 가운데에서 골라요.","수아의 말이 틀렸어요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
