INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L08_challenge#9','math',5,2,'u5','L08','g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',4,'sa','auto','눈의 수를 특별하게 적은 주사위의 전개도예요. 1이 보일 때, 1과 수직인 면 가운데 눈의 수가 가장 큰 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C8","difficulty":4,"kind":"sa","stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 1이 보일 때, 1과 수직인 면 가운데 눈의 수가 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["1과 평행한 면은 5예요.","1과 수직인 면은 나머지 2, 3, 4, 6이에요.","가장 큰 수는 6이에요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":150,"h":60,"seg":[[[0,0],[0,30]],[[0,0],[90,0]],[[0,30],[60,30]],[[60,30],[60,60]],[[60,60],[150,60]],[[90,0],[90,30]],[[90,30],[150,30]],[[150,30],[150,60]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[60,30],[90,30]],[[90,30],[90,60]],[[120,30],[120,60]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"2"],[[75.0,10.0],"5"],[[75.0,40.0],"4"],[[105.0,40.0],"3"],[[135.0,40.0],"6"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 2가 보일 때, 2와 수직인 면 가운데 눈의 수가 가장 작은 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["2와 평행한 면은 1이에요.","2와 수직인 면은 나머지 3, 4, 5, 6이에요.","가장 작은 수는 3이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[45.0,10.0],"1"],[[15.0,40.0],"3"],[[45.0,40.0],"4"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"5"]]}],"tag":false}},{"stem":"눈의 수를 특별하게 적은 주사위의 전개도예요. 4가 보일 때, 4와 수직인 면 가운데 눈의 수가 가장 큰 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["4와 평행한 면은 1이에요.","4와 수직인 면은 나머지 2, 3, 5, 6이에요.","가장 큰 수는 6이에요."],