INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_L08_challenge#10','math',5,2,'u5','L08','g5_2_math_u5_L08_challenge','lesson_challenge','M5-2-u5-C8',4,'essay','teacher','주사위 전개도를 보고 눈의 수 1에서 시작해 「① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기」를 99번 반복하려고 해요. 끝까지 굴리지 않고 결과를 구하는 방법과 결과를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"M5-2-u5-C8","difficulty":4,"kind":"essay","stem":"주사위 전개도를 보고 눈의 수 1에서 시작해 「① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기」를 99번 반복하려고 해요. 끝까지 굴리지 않고 결과를 구하는 방법과 결과를 쓰세요.","answer_guide":{"answer":"예: 1에서 시작하면 평행한 6으로 굴린 뒤 6과 수직인 2, 3, 4, 5 가운데 가장 작은 2가 보인다. 2에서는 평행한 5로 굴린 뒤 1, 3, 4, 6 가운데 가장 작은 1이 보인다. 그래서 1 → 2 → 1 → 2로 2번마다 되풀이된다. 99번은 홀수 번이므로 2가 보인다.","scoring_points":["1번·2번 실행 결과(2, 1)을 구했는가","2번마다 되풀이되는 규칙을 찾았는가","홀수 번이라 2라고 결론지었는가"]},"explanation":["1 → 2, 2 → 1로 바뀌어요.","2번마다 처음 수로 되풀이돼요.","99번은 홀수 번이라 2가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#1','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C2',1,'sa','auto','직육면체 모양 캠핑 상자의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C2","difficulty":1,"kind":"sa","stem":"직육면체 모양 캠핑 상자의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["12"],"explanation":["보이는 모서리 9개와 보이지 않는 모서리 3개가 있어요.","9 + 3 = 12예요.","그래서 모서리는 12개예요."],"mis":"M5-2-u5-X04","asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 서랍의 꼭짓점은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["8"],"explanation":["윗면에 4개, 아랫면에 4개가 있어요.","4 + 4 = 8이에요.","그래서 꼭짓점은 8개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 선물 상자의 면은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["6"],"explanation":["앞·뒤, 위·아래, 왼쪽·오른쪽에 면이 둘씩 있어요.","2 × 3 = 6이에요.","그래서 면은 6개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#2','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C3',1,'mc','auto','정사각형 6개로 둘러싸인 입체도형을 무엇이라고 하나요?',ARRAY['M5-2-u5-X02','M5-2-u5-X01']::text[],true,'{"seq":2,"concept":"M5-2-u5-C3","difficulty":1,"kind":"mc","stem":"정사각형 6개로 둘러싸인 입체도형을 무엇이라고 하나요?","options":[{"t":"정육면체","correct":true},{"t":"삼각뿔","mis":"M5-2-u5-X02"},{"t":"정사각형","mis":"M5-2-u5-X01"},{"t":"평면도형","mis":"M5-2-u5-X01"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「정육면체」예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"정육면체는 어떤 도형으로 둘러싸인 입체도형인가요?","options":[{"t":"크기가 같은 정사각형 6개","correct":true},{"t":"직사각형 4개와 정사각형 2개","mis":"M5-2-u5-X02"},{"t":"크기가 같은 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"크기가 다른 직사각형 6개","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「크기가 같은 정사각형 6개」예요."],"asset":null},{"stem":"동생과 방을 정리하며 모은 쌓기나무, 루빅큐브, 주사위의 같은 점을 수학적으로 말한 것은 어느 것인가요?","options":[{"t":"모두 정사각형 6개로 둘러싸여 있다","correct":true},{"t":"모두 장난감이다","mis":"M5-2-u5-X02"},{"t":"모두 색이 같다","mis":"M5-2-u5-X02"},{"t":"모두 크기가 같다","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「모두 정사각형 6개로 둘러싸여 있다」예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_co