-2-u5-X12"},{"t":"면 라","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 다와 평행한 면은 면 마예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[90,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[120,30]],[[90,60],[90,90]],[[90,90],[120,90]],[[120,30],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,60],[120,60]]],"lab":[[[45.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[105.0,70.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#7','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C7',1,'mc','auto','직육면체의 전개도를 그릴 때 접었을 때 맞붙는 두 모서리는 어떻게 그리나요?',ARRAY['M5-2-u5-X14','M5-2-u5-X16']::text[],true,'{"seq":7,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"직육면체의 전개도를 그릴 때 접었을 때 맞붙는 두 모서리는 어떻게 그리나요?","options":[{"t":"길이가 같게 그린다","correct":true},{"t":"한쪽을 더 길게 그린다","mis":"M5-2-u5-X14"},{"t":"둘 다 점선으로 그린다","mis":"M5-2-u5-X16"},{"t":"하나만 그린다","mis":"M5-2-u5-X14"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「길이가 같게 그린다」예요."],"variant_rule":{"alt":[{"stem":"직육면체의 전개도를 그릴 때 접었을 때 마주 보는 두 면은 어떻게 그리나요?","options":[{"t":"모양과 크기가 같게 그린다","correct":true},{"t":"크기를 다르게 그린다","mis":"M5-2-u5-X14"},{"t":"하나는 정사각형으로 그린다","mis":"M5-2-u5-X02"},{"t":"바로 붙여서 그린다","mis":"M5-2-u5-X12"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「모양과 크기가 같게 그린다」예요."]},{"stem":"직육면체의 전개도를 그리려면 면을 몇 개 그려야 하나요?","options":[{"t":"6개","correct":true},{"t":"4개","mis":"M5-2-u5-X04"},{"t":"5개","mis":"M5-2-u5-X14"},{"t":"12개","mis":"M5-2-u5-X05"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「6개」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#8','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C8',1,'sa','auto','주사위의 전개도예요. 전개도를 접었을 때 눈의 수 1과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C8","difficulty":1,"kind":"sa","stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 1과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 1과 마주 보는 면은 6이에요.","그래서 6이에요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 2와 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 2와 마주 보는 면은 5예요.","그래서 5예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"2"],[[45.0,40.0],"4"],[[75.0,40.0],"5"],[[75.0,70.0],"1"],[[105.0,70.0],"3"]]}],"tag":false}},{"stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 3과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 3과 마주 보는 면은 4예요.","그래서 4예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"4"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#9','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C2',2,'sa','auto','직육면체 모양 선물 상자 2개의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C2","difficulty":2,"kind":"sa","stem":"직육면체 모양 선물 상자 2개의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체 하나의 모서리는 12개예요.","2개니 12 × 2 = 24예요.","그래서 모두 24개예요."],"mis":"M5-2-u5-X05","variant_rule":{"alt":[{"stem":"직육면체 모양 서랍 3개의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체 하나의 꼭짓점은 8개예요.","3개니 8 × 3 = 24예요.","그래서 모두 24개예요."]},{"stem":"직육면체 모양 도시락통 4개의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체 하나의 면은 6개예요.","4개니 6 × 4 = 24예요.","그래서 모두 24개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
