INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#16','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C7',2,'sa','auto','한 모서리가 2 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M5-2-u5-C7","difficulty":2,"kind":"sa","stem":"한 모서리가 2 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["전개도의 둘레(실선)에는 한 변이 2 cm인 선분이 14개 있어요.","2 × 14 = 28이에요.","그래서 28 cm예요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["면 6개를 잇는 점선은 5개예요.","3 × 5 = 15예요.","그래서 15 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}},{"stem":"한 모서리가 4 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["전개도의 둘레(실선)에는 한 변이 4 cm인 선분이 14개 있어요.","4 × 14 = 56이에요.","그래서 56 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]]