INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#18','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C3',3,'sa','auto','모서리의 길이가 15 cm, 7 cm, 7 cm인 직육면체 모양 빵을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"모서리의 길이가 15 cm, 7 cm, 7 cm인 직육면체 모양 빵을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 7 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 7 cm예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"모서리의 길이가 12 cm, 9 cm, 10 cm인 직육면체 모양 두부를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 9 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 9 cm예요."]},{"stem":"모서리의 길이가 8 cm, 11 cm, 6 cm인 직육면체 모양 나무 토막을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 6 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 6 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
