INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#21','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C8',3,'sa','auto','명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["몇 번만 실행해 보면 1 → 2 → 1 → 2 → 1이에요.","2번마다 처음 수로 되풀이돼요.","그래서 6번 실행하면 1이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 6 → 5 → 6 → 5 → 6이에요.","2번마다 처음 수로 되풀이돼요.","그래서 9번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"2"],[[45.0,40.0],"4"],[[75.0,40.0],"5"],[[75.0,70.0],"1"],[[105.0,70.0],"3"]]}],"tag":false}},{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 7번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["몇 번만 실행해 보면 4 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 7번 실행하면 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"4"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#22','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C4',3,'sa','auto','가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겨냥도예요. 점선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겨냥도예요. 점선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["점선 3개는 보이지 않는 꼭짓점에서 만나는 가로, 세로, 높이 하나씩이에요.","5 + 3 + 4 = 12예요.","그래서 12 cm예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["모든 모서리의 합은 6 × 4 + 2 × 4 + 3 × 4 = 44예요.","점선 3개는 6 + 2 + 3 = 11이에요.","실선은 44 − 11 = 33(cm)예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[132,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[132,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[66.0,96.0],"6 cm"],[[159.0,81.0],"2 cm"],[[114,55.0],"3 cm"]]}],"tag":false}},{"stem":"가로 4 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겨냥도예요. 점선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["점선 3개는 보이지 않는 꼭짓점에서 만나는 가로, 세로, 높이 하나씩이에요.","4 + 4 + 5 = 13이에요.","그래서 13 cm예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[88,44.0,"sw"],"ㅁ":[44.0,110,"ne"],"ㅇ":[132.0,110,"e"],"ㅂ":[0,154.0,"sw"],"ㅅ":[88,154.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,162.0],"4 cm"],[[126.0,136.0],"4 cm"],[[70,99.0],"5 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#23','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C2',4,'essay','teacher','가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 상자의 모서리를 따라 리본을 한 번씩 붙이려고 해요. 리본은 모두 몇 cm 필요한지 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u5-C2","difficulty":4,"kind":"essay","stem":"가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 상자의 모서리를 따라 리본을 한 번씩 붙이려고 해요. 리본은 모두 몇 cm 필요한지 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 직육면체에는 길이가 같은 모서리가 4개씩 있다. 5 cm인 모서리 4개, 3 cm인 모서리 4개, 2 cm인 모서리 4개이므로 5 × 4 + 3 × 4 + 2 × 4 = 40(cm)이다. 리본은 40 cm 필요하다.","scoring_points":["같은 길이 모서리가 4개씩이라고 썼는가","5 × 4 + 3 × 4 + 2 × 4를 세웠는가","40 cm라고 답했는가"]},"explanation":["길이가 같은 모서리가 4개씩이에요.","5 × 4 + 3 × 4 + 2 × 4 = 40이에요.","리본은 40 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[143.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[110,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,85.0],"5 cm"],[[142.5,64.5],"3 cm"],[[92,55.0],"2 cm"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#24','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C6',4,'essay','teacher','전개도를 접어서 직육면체를 만들 때 면 가와 평행한 면과 수직인 면을 모두 찾고, 어떻게 찾았는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u5-C6","difficulty":4,"kind":"essay","stem":"전개도를 접어서 직육면체를 만들 때 면 가와 평행한 면과 수직인 면을 모두 찾고, 어떻게 찾았는지 쓰세요.","answer_guide":{"answer":"예: 면 가와 평행한 면은 면 바이고, 수직인 면은 면 나, 면 다, 면 라, 면 마이다. 접어 보면 면 가는 맨 위에, 면 바는 맨 아래에 와서 서로 마주 보므로 평행하다. 나머지 네 면은 면 가와 만나므로 수직이다.","scoring_points":["평행한 면 바를 찾았는가","수직인 면 나·다·라·마를 찾았는가","마주 보면 평행, 만나면 수직이라고 설명했는가"]},"explanation":["접으면 면 가와 면 바가 마주 봐요.","나머지 네 면은 면 가와 만나요.","마주 보면 평행, 만나면 수직이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[15.0,70.0],"바"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_a#25','math',5,2,'u5','','g5_2_math_u5_review_a','unit_review','M5-2-u5-C2',4,'sa','auto','길이가 50 cm인 철사를 겹치지 않게 모두 써서 가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u5-C2","difficulty":4,"kind":"sa","stem":"길이가 50 cm인 철사를 겹치지 않게 모두 써서 가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","5 × 4 + 3 × 4 + 2 × 4 = 40이에요.","남는 철사는 50 − 40 = 10(cm)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"길이가 40 cm인 철사를 겹치지 않게 모두 써서 가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","4 × 4 + 3 × 4 + 2 × 4 = 36이에요.","남는 철사는 40 − 36 = 4(cm)예요."]},{"stem":"길이가 50 cm인 철사를 겹치지 않게 모두 써서 가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","6 × 4 + 2 × 4 + 3 × 4 = 44예요.","남는 철사는 50 − 44 = 6(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#1','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C2',1,'sa','auto','직육면체 모양 서랍의 꼭짓점은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C2","difficulty":1,"kind":"sa","stem":"직육면체 모양 서랍의 꼭짓점은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["8"],"explanation":["윗면에 4개, 아랫면에 4개가 있어요.","4 + 4 = 8이에요.","그래서 꼭짓점은 8개예요."],"mis":"M5-2-u5-X04","asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 선물 상자의 면은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["6"],"explanation":["앞·뒤, 위·아래, 왼쪽·오른쪽에 면이 둘씩 있어요.","2 × 3 = 6이에요.","그래서 면은 6개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 과일 상자의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["12"],"explanation":["보이는 모서리 9개와 보이지 않는 모서리 3개가 있어요.","9 + 3 = 12예요.","그래서 모서리는 12개예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[132.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[110,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#2','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C3',1,'mc','auto','정육면체는 어떤 도형으로 둘러싸인 입체도형인가요?',ARRAY['M5-2-u5-X02','M5-2-u5-X04']::text[],true,'{"seq":2,"concept":"M5-2-u5-C3","difficulty":1,"kind":"mc","stem":"정육면체는 어떤 도형으로 둘러싸인 입체도형인가요?","options":[{"t":"크기가 같은 정사각형 6개","correct":true},{"t":"직사각형 4개와 정사각형 2개","mis":"M5-2-u5-X02"},{"t":"크기가 같은 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"크기가 다른 직사각형 6개","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「크기가 같은 정사각형 6개」예요."],"variant_rule":{"alt":[{"stem":"동생과 방을 정리하며 모은 쌓기나무, 루빅큐브, 주사위의 같은 점을 수학적으로 말한 것은 어느 것인가요?","options":[{"t":"모두 정사각형 6개로 둘러싸여 있다","correct":true},{"t":"모두 장난감이다","mis":"M5-2-u5-X02"},{"t":"모두 색이 같다","mis":"M5-2-u5-X02"},{"t":"모두 크기가 같다","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「모두 정사각형 6개로 둘러싸여 있다」예요."]},{"stem":"정육면체의 면이 될 수 있는 사각형은 어느 것인가요?","options":[{"t":"네 변이 모두 3 cm이고 네 각이 모두 직각인 사각형","correct":true},{"t":"가로 3 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X02"},{"t":"네 변이 모두 3 cm이지만 직각이 없는 사각형","mis":"M5-2-u5-X02"},{"t":"윗변 2 cm, 아랫변 3 cm인 사다리꼴","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","그래서 면 6개가 모두 크기가 같은 정사각형이에요.","정답은 「네 변이 모두 3 cm이고 네 각이 모두 직각인 사각형」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#3','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C4',1,'mc','auto','직육면체의 겨냥도에서 보이는 모서리는 어떻게 그리나요?',ARRAY['M5-2-u5-X09','M5-2-u5-X03']::text[],true,'{"seq":3,"concept":"M5-2-u5-C4","difficulty":1,"kind":"mc","stem":"직육면체의 겨냥도에서 보이는 모서리는 어떻게 그리나요?","options":[{"t":"실선으로 그린다","correct":true},{"t":"점선으로 그린다","mis":"M5-2-u5-X09"},{"t":"그리지 않는다","mis":"M5-2-u5-X09"},{"t":"색칠한다","mis":"M5-2-u5-X03"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「실선으로 그린다」예요."],"variant_rule":{"alt":[{"stem":"보이는 모서리는 실선, 보이지 않는 모서리는 점선으로 나타낸 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 겨냥도","correct":true},{"t":"직육면체의 전개도","mis":"M5-2-u5-X16"},{"t":"평면도형","mis":"M5-2-u5-X01"},{"t":"직사각형","mis":"M5-2-u5-X02"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「직육면체의 겨냥도」예요."]},{"stem":"직육면체의 모든 면이 이어지도록 모서리를 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 전개도","correct":true},{"t":"직육면체의 겨냥도","mis":"M5-2-u5-X16"},{"t":"직사각형","mis":"M5-2-u5-X02"},{"t":"평면도형","mis":"M5-2-u5-X01"}],"explanation":["전개도는 모든 면이 이어지게 모서리를 잘라 펼친 그림이에요.","잘린 모서리는 실선, 잘리지 않은(접는) 모서리는 점선이에요.","정답은 「직육면체의 전개도」예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#4','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C4',1,'sa','auto','직육면체 모양 서랍의 겨냥도예요. 점선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u5-C4","difficulty":1,"kind":"sa","stem":"직육면체 모양 서랍의 겨냥도예요. 점선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","보이지 않는 모서리 3개를 점선으로 그려요.","그래서 3개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 선물 상자의 겨냥도예요. 보이지 않는 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","뒤쪽 아래 꼭짓점 1개만 보이지 않아요.","그래서 1개예요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 도시락통의 겨냥도예요. 보이는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","앞, 위, 옆의 면 3개가 보여요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#5','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C5',1,'sa','auto','직육면체에서 한 밑면과 수직인 면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u5-C5","difficulty":1,"kind":"sa","stem":"직육면체에서 한 밑면과 수직인 면은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","밑면과 평행한 다른 밑면을 뺀 나머지 6 − 2 = 4(개)가 수직이에요.","그래서 4예요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 한 면과 평행한 면은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","마주 보는 면 하나만 평행해요.","그래서 1이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에서 한 꼭짓점에서 만나는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","한 꼭짓점에는 서로 수직인 면 3개가 모여요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#6','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C6',1,'mc','auto','전개도를 접었을 때 면 나와 평행한 면은 어느 것인가요?',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":6,"concept":"M5-2-u5-C6","difficulty":1,"kind":"mc","stem":"전개도를 접었을 때 면 나와 평행한 면은 어느 것인가요?","options":[{"t":"면 라","correct":true},{"t":"면 가","mis":"M5-2-u5-X12"},{"t":"면 다","mis":"M5-2-u5-X12"},{"t":"면 마","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 나와 평행한 면은 면 라예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"전개도를 접었을 때 면 다와 평행한 면은 어느 것인가요?","options":[{"t":"면 마","correct":true},{"t":"면 가","mis":"M5-2-u5-X12"},{"t":"면 나","mis":"M5-2-u5-X12"},{"t":"면 라","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 다와 평행한 면은 면 마예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[90,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[120,30]],[[90,60],[90,90]],[[90,90],[120,90]],[[120,30],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,60],[120,60]]],"lab":[[[45.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[105.0,70.0],"바"]]}],"tag":false}},{"stem":"전개도를 접었을 때 면 라와 평행한 면은 어느 것인가요?","options":[{"t":"면 나","correct":true},{"t":"면 가","mis":"M5-2-u5-X12"},{"t":"면 다","mis":"M5-2-u5-X12"},{"t":"면 마","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 라와 평행한 면은 면 나예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[75.0,70.0],"마"],[[105.0,70.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#7','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C7',1,'mc','auto','직육면체의 전개도를 그릴 때 접었을 때 마주 보는 두 면은 어떻게 그리나요?',ARRAY['M5-2-u5-X14','M5-2-u5-X02','M5-2-u5-X12']::text[],true,'{"seq":7,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"직육면체의 전개도를 그릴 때 접었을 때 마주 보는 두 면은 어떻게 그리나요?","options":[{"t":"모양과 크기가 같게 그린다","correct":true},{"t":"크기를 다르게 그린다","mis":"M5-2-u5-X14"},{"t":"하나는 정사각형으로 그린다","mis":"M5-2-u5-X02"},{"t":"바로 붙여서 그린다","mis":"M5-2-u5-X12"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「모양과 크기가 같게 그린다」예요."],"variant_rule":{"alt":[{"stem":"직육면체의 전개도를 그리려면 면을 몇 개 그려야 하나요?","options":[{"t":"6개","correct":true},{"t":"4개","mis":"M5-2-u5-X04"},{"t":"5개","mis":"M5-2-u5-X14"},{"t":"12개","mis":"M5-2-u5-X05"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「6개」예요."]},{"stem":"한 모서리가 3 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 3 cm인 정사각형 6개","correct":true},{"t":"가로 3 cm, 세로 6 cm인 직사각형 6개","mis":"M5-2-u5-X07"},{"t":"한 변이 3 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 6 cm인 정사각형 6개","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 3 cm이니 한 변이 3 cm인 정사각형이에요.","면이 6개니 6개를 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#8','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C8',1,'sa','auto','주사위의 전개도예요. 전개도를 접었을 때 눈의 수 2와 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C8","difficulty":1,"kind":"sa","stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 2와 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 2와 마주 보는 면은 5예요.","그래서 5예요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"2"],[[45.0,40.0],"4"],[[75.0,40.0],"5"],[[75.0,70.0],"1"],[[105.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 3과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 3과 마주 보는 면은 4예요.","그래서 4예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"4"]]}],"tag":false}},{"stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 4와 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 4와 마주 보는 면은 3이에요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,60],[60,90]],[[60,90],[90,90]],[[90,60],[90,90]],[[90,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"2"],[[105.0,40.0],"4"],[[75.0,70.0],"1"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#9','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C2',2,'sa','auto','직육면체 모양 서랍 3개의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C2","difficulty":2,"kind":"sa","stem":"직육면체 모양 서랍 3개의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체 하나의 꼭짓점은 8개예요.","3개니 8 × 3 = 24예요.","그래서 모두 24개예요."],"mis":"M5-2-u5-X05","variant_rule":{"alt":[{"stem":"직육면체 모양 도시락통 4개의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체 하나의 면은 6개예요.","4개니 6 × 4 = 24예요.","그래서 모두 24개예요."]},{"stem":"직육면체 모양 벽돌 5개의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["직육면체 하나의 모서리는 12개예요.","5개니 12 × 5 = 60이에요.","그래서 모두 60개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
