INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#14','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C6',2,'mc','auto','이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X02']::text[],true,'{"seq":14,"concept":"M5-2-u5-C6","difficulty":2,"kind":"mc","stem":"이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 만나는 선분의 길이가 다르다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 만나는 선분의 길이가 다르다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":120,"seg":[[[0,0],[0,80]],[[0,0],[60,0]],[[0,80],[100,80]],[[60,0],[60,60]],[[60,60],[200,60]],[[100,80],[100,120]],[[100,120],[160,120]],[[160,80],[160,120]],[[160,80],[200,80]],[[200,60],[200,80]]],"dash":[[[0,60],[60,60]],[[60,60],[60,80]],[[100,60],[100,80]],[[100,80],[160,80]],[[160,60],[160,80]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"면이 5개뿐이다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「면이 5개뿐이다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":60,"seg":[[[0,0],[0,20]],[[0,0],[200,0]],[[0,20],[100,20]],[[100,20],[100,60]],[[100,60],[160,60]],[[160,20],[160,60]],[[160,20],[200,20]],[[200,0],[200,20]]],"dash":[[[60,0],[60,20]],[[100,0],[100,20]],[[100,20],[160,20]],[[160,0],[160,20]]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":180,"h":30,"seg":[[[0,0],[0,30]],[[0,0],[180,0]],[[0,30],[180,30]],[[180,0],[180,30]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[90,0],[90,30]],[[120,0],[120,30]],[[150,0],[150,30]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#15','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C8',2,'sa','auto','명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["① 1과 평행한 면 6이 보이게 굴려요.","② 6과 수직인 면 2, 3, 4, 5 가운데 가장 작은 수는 2예요.","그래서 2가 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"2"],[[45.0,40.0],"4"],[[75.0,40.0],"5"],[[75.0,70.0],"1"],[[105.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 2와 평행한 면 5가 보이게 굴려요.","② 5와 수직인 면 1, 3, 4, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"4"]]}],"tag":false}},{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["① 6과 평행한 면 1이 보이게 굴려요.","② 1과 수직인 면 2, 3, 4, 5 가운데 가장 작은 수는 2예요.","그래서 2가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,60],[60,90]],[[60,90],[90,90]],[[90,60],[90,90]],[[90,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"2"],[[105.0,40.0],"4"],[[75.0,70.0],"1"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#16','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C7',2,'sa','auto','한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M5-2-u5-C7","difficulty":2,"kind":"sa","stem":"한 모서리가 3 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["면 6개를 잇는 점선은 5개예요.","3 × 5 = 15예요.","그래서 15 cm예요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 4 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["전개도의 둘레(실선)에는 한 변이 4 cm인 선분이 14개 있어요.","4 × 14 = 56이에요.","그래서 56 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}},{"stem":"한 모서리가 5 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["면 6개를 잇는 점선은 5개예요.","5 × 5 = 25예요.","그래서 25 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64