INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#17','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C2',3,'sa','auto','가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체 모양 선물 상자의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M5-2-u5-C2","difficulty":3,"kind":"sa","stem":"가로 4 cm, 세로 2 cm, 높이 3 cm인 직육면체 모양 선물 상자의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","4 × 4 + 2 × 4 + 3 × 4 = 36이에요.","그래서 36 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,96.0],"4 cm"],[[115.0,81.0],"2 cm"],[[70,55.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 3 cm, 세로 2 cm, 높이 2 cm인 직육면체 모양 도시락통의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","3 × 4 + 2 × 4 + 2 × 4 = 28이에요.","그래서 28 cm예요."],"asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,74.0],"3 cm"],[[93.0,59.0],"2 cm"],[[48,44.0],"2 cm"]]}],"tag":false}},{"stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 서랍의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","4 × 4 + 3 × 4 + 2 × 4 = 36이에요.","그래서 36 cm예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,85.0],"4 cm"],[[120.5,64.5],"3 cm"],[[70,55.0],"2 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#18','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C3',3,'sa','auto','모서리의 길이가 12 cm, 9 cm, 10 cm인 직육면체 모양 두부를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"모서리의 길이가 12 cm, 9 cm, 10 cm인 직육면체 모양 두부를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 9 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 9 cm예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"모서리의 길이가 8 cm, 11 cm, 6 cm인 직육면체 모양 나무 토막을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 6 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 6 cm예요."]},{"stem":"모서리의 길이가 20 cm, 14 cm, 16 cm인 직육면체 모양 케이크를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 14 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
