INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#21','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C8',3,'sa','auto','명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 6 → 5 → 6 → 5 → 6이에요.","2번마다 처음 수로 되풀이돼요.","그래서 9번 실행하면 5가 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"2"],[[45.0,40.0],"4"],[[75.0,40.0],"5"],[[75.0,70.0],"1"],[[105.0,70.0],"3"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 7번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["몇 번만 실행해 보면 4 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 7번 실행하면 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"4"]]}],"tag":false}},{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 3이 보이게 놓고 시작해 10번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 3 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 10번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,60],[60,90]],[[60,90],[90,90]],[[90,60],[90,90]],[[90,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"2"],[[105.0,40.0],"4"],[[75.0,70.0],"1"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#22','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C4',3,'sa','auto','가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["모든 모서리의 합은 6 × 4 + 2 × 4 + 3 × 4 = 44예요.","점선 3개는 6 + 2 + 3 = 11이에요.","실선은 44 − 11 = 33(cm)예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":154.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[132,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[132,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[66.0,96.0],"6 cm"],[[159.0,81.0],"2 cm"],[[114,55.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겨냥도예요. 점선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["점선 3개는 보이지 않는 꼭짓점에서 만나는 가로, 세로, 높이 하나씩이에요.","4 + 4 + 5 = 13이에요.","그래서 13 cm예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[88,44.0,"sw"],"ㅁ":[44.0,110,"ne"],"ㅇ":[132.0,110,"e"],"ㅂ":[0,154.0,"sw"],"ㅅ":[88,154.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,162.0],"4 cm"],[[126.0,136.0],"4 cm"],[[70,99.0],"5 cm"]]}],"tag":false}},{"stem":"가로 7 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["모든 모서리의 합은 7 × 4 + 2 × 4 + 3 × 4 = 48이에요.","점선 3개는 7 + 2 + 3 = 12예요.","실선은 48 − 12 = 36(cm)예요."],"asset":{"type":"geo","items":[{"w":176.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[176.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[154,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[176.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[154,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[77.0,96.0],"7 cm"],[[181.0,81.0],"2 cm"],[[136,55.0],"3 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#23','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C4',4,'essay','teacher','직육면체의 겨냥도에서 보이지 않는 면, 모서리, 꼭짓점의 수를 각각 쓰고, 왜 그만큼만 보이지 않는지 그림을 보며 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u5-C4","difficulty":4,"kind":"essay","stem":"직육면체의 겨냥도에서 보이지 않는 면, 모서리, 꼭짓점의 수를 각각 쓰고, 왜 그만큼만 보이지 않는지 그림을 보며 설명하세요.","answer_guide":{"answer":"예: 보이지 않는 면은 3개, 모서리는 3개, 꼭짓점은 1개이다. 앞·위·오른쪽 면이 보이고 뒤·아래·왼쪽 면 3개가 가려진다. 가려진 세 면이 함께 만나는 꼭짓점 하나와 그 꼭짓점에서 만나는 모서리 3개만 보이지 않는다.","scoring_points":["면 3·모서리 3·꼭짓점 1을 썼는가","가려진 면 3개를 말했는가","한 꼭짓점과 거기서 만나는 모서리 3개라고 설명했는가"]},"explanation":["보이지 않는 면은 3개예요.","세 면이 함께 만나는 꼭짓점 1개가 가려져요.","그 꼭짓점에서 만나는 모서리 3개가 점선이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#24','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C3',4,'essay','teacher','모서리의 길이가 9 cm, 12 cm, 15 cm인 직육면체 모양 나무 토막을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이와 모든 모서리의 길이의 합을 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u5-C3","difficulty":4,"kind":"essay","stem":"모서리의 길이가 9 cm, 12 cm, 15 cm인 직육면체 모양 나무 토막을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이와 모든 모서리의 길이의 합을 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 정육면체는 모든 모서리의 길이가 같아야 하므로 가장 짧은 9 cm에 맞춰야 한다. 한 모서리는 9 cm이다. 정육면체의 모서리는 12개이므로 모든 모서리의 길이의 합은 9 × 12 = 108(cm)이다.","scoring_points":["가장 짧은 모서리에 맞춘다고 썼는가","한 모서리 9 cm를 구했는가","9 × 12 = 108(cm)을 구했는가"]},"explanation":["가장 짧은 모서리 9 cm에 맞춰요.","정육면체의 모서리는 12개예요.","9 × 12 = 108(cm)이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_b#25','math',5,2,'u5','','g5_2_math_u5_review_b','unit_review','M5-2-u5-C2',4,'sa','auto','길이가 40 cm인 철사를 겹치지 않게 모두 써서 가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u5-C2","difficulty":4,"kind":"sa","stem":"길이가 40 cm인 철사를 겹치지 않게 모두 써서 가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","4 × 4 + 3 × 4 + 2 × 4 = 36이에요.","남는 철사는 40 − 36 = 4(cm)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"길이가 50 cm인 철사를 겹치지 않게 모두 써서 가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","6 × 4 + 2 × 4 + 3 × 4 = 44예요.","남는 철사는 50 − 44 = 6(cm)예요."]},{"stem":"길이가 40 cm인 철사를 겹치지 않게 모두 써서 가로 3 cm, 세로 3 cm, 높이 3 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","3 × 4 + 3 × 4 + 3 × 4 = 36이에요.","남는 철사는 40 − 36 = 4(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#1','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C2',1,'sa','auto','직육면체 모양 선물 상자의 면은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C2","difficulty":1,"kind":"sa","stem":"직육면체 모양 선물 상자의 면은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["6"],"explanation":["앞·뒤, 위·아래, 왼쪽·오른쪽에 면이 둘씩 있어요.","2 × 3 = 6이에요.","그래서 면은 6개예요."],"mis":"M5-2-u5-X04","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 과일 상자의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["12"],"explanation":["보이는 모서리 9개와 보이지 않는 모서리 3개가 있어요.","9 + 3 = 12예요.","그래서 모서리는 12개예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[132.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[110,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 캠핑 상자의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["12"],"explanation":["보이는 모서리 9개와 보이지 않는 모서리 3개가 있어요.","9 + 3 = 12예요.","그래서 모서리는 12개예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#2','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C3',1,'mc','auto','동생과 방을 정리하며 모은 쌓기나무, 루빅큐브, 주사위의 같은 점을 수학적으로 말한 것은 어느 것인가요?',ARRAY['M5-2-u5-X02']::text[],true,'{"seq":2,"concept":"M5-2-u5-C3","difficulty":1,"kind":"mc","stem":"동생과 방을 정리하며 모은 쌓기나무, 루빅큐브, 주사위의 같은 점을 수학적으로 말한 것은 어느 것인가요?","options":[{"t":"모두 정사각형 6개로 둘러싸여 있다","correct":true},{"t":"모두 장난감이다","mis":"M5-2-u5-X02"},{"t":"모두 색이 같다","mis":"M5-2-u5-X02"},{"t":"모두 크기가 같다","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「모두 정사각형 6개로 둘러싸여 있다」예요."],"variant_rule":{"alt":[{"stem":"정육면체의 면이 될 수 있는 사각형은 어느 것인가요?","options":[{"t":"네 변이 모두 3 cm이고 네 각이 모두 직각인 사각형","correct":true},{"t":"가로 3 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X02"},{"t":"네 변이 모두 3 cm이지만 직각이 없는 사각형","mis":"M5-2-u5-X02"},{"t":"윗변 2 cm, 아랫변 3 cm인 사다리꼴","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","그래서 면 6개가 모두 크기가 같은 정사각형이에요.","정답은 「네 변이 모두 3 cm이고 네 각이 모두 직각인 사각형」이에요."]},{"stem":"정사각형 6개로 둘러싸인 입체도형을 무엇이라고 하나요?","options":[{"t":"정육면체","correct":true},{"t":"삼각뿔","mis":"M5-2-u5-X02"},{"t":"정사각형","mis":"M5-2-u5-X01"},{"t":"평면도형","mis":"M5-2-u5-X01"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「정육면체」예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#3','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C4',1,'mc','auto','보이는 모서리는 실선, 보이지 않는 모서리는 점선으로 나타낸 그림을 무엇이라고 하나요?',ARRAY['M5-2-u5-X16','M5-2-u5-X01','M5-2-u5-X02']::text[],true,'{"seq":3,"concept":"M5-2-u5-C4","difficulty":1,"kind":"mc","stem":"보이는 모서리는 실선, 보이지 않는 모서리는 점선으로 나타낸 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 겨냥도","correct":true},{"t":"직육면체의 전개도","mis":"M5-2-u5-X16"},{"t":"평면도형","mis":"M5-2-u5-X01"},{"t":"직사각형","mis":"M5-2-u5-X02"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「직육면체의 겨냥도」예요."],"variant_rule":{"alt":[{"stem":"직육면체의 모든 면이 이어지도록 모서리를 잘라서 평면 위에 펼친 그림을 무엇이라고 하나요?","options":[{"t":"직육면체의 전개도","correct":true},{"t":"직육면체의 겨냥도","mis":"M5-2-u5-X16"},{"t":"직사각형","mis":"M5-2-u5-X02"},{"t":"평면도형","mis":"M5-2-u5-X01"}],"explanation":["전개도는 모든 면이 이어지게 모서리를 잘라 펼친 그림이에요.","잘린 모서리는 실선, 잘리지 않은(접는) 모서리는 점선이에요.","정답은 「직육면체의 전개도」예요."],"asset":{"type":"geo","items":[{"w":200,"h":100,"seg":[[[0,0],[0,100]],[[0,0],[60,0]],[[0,100],[60,100]],[[60,0],[60,40]],[[60,40],[200,40]],[[60,60],[60,100]],[[60,60],[200,60]],[[200,40],[200,60]]],"dash":[[[0,40],[60,40]],[[0,60],[60,60]],[[60,40],[60,60]],[[100,40],[100,60]],[[160,40],[160,60]]],"lab":[[[30.0,15.0],"가"],[[30.0,45.0],"나"],[[80.0,45.0],"다"],[[130.0,45.0],"라"],[[180.0,45.0],"마"],[[30.0,75.0],"바"]]}],"tag":false}},{"stem":"직육면체의 겨냥도에서 보이지 않는 모서리는 어떻게 그리나요?","options":[{"t":"점선으로 그린다","correct":true},{"t":"실선으로 그린다","mis":"M5-2-u5-X09"},{"t":"그리지 않는다","mis":"M5-2-u5-X09"},{"t":"보이는 모서리보다 굵게 그린다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선으로 그려요.","보이지 않는 모서리는 점선으로 그려요.","정답은 「점선으로 그린다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.gradin