INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#4','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C4',1,'sa','auto','직육면체 모양 선물 상자의 겨냥도예요. 보이지 않는 꼭짓점은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M5-2-u5-C4","difficulty":1,"kind":"sa","stem":"직육면체 모양 선물 상자의 겨냥도예요. 보이지 않는 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","뒤쪽 아래 꼭짓점 1개만 보이지 않아요.","그래서 1개예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 도시락통의 겨냥도예요. 보이는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","앞, 위, 옆의 면 3개가 보여요.","그래서 3개예요."],"asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 캠핑 상자의 겨냥도예요. 실선으로 그린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["겨냥도에서 보이는 모서리는 실선, 보이지 않는 모서리는 점선이에요.","보이는 모서리 9개를 실선으로 그려요.","그래서 9개예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#5','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C5',1,'sa','auto','직육면체에서 한 면과 평행한 면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M5-2-u5-C5","difficulty":1,"kind":"sa","stem":"직육면체에서 한 면과 평행한 면은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","마주 보는 면 하나만 평행해요.","그래서 1이에요."],"mis":"M5-2-u5-X13","asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체에서 한 꼭짓점에서 만나는 면은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","한 꼭짓점에는 서로 수직인 면 3개가 모여요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체에서 서로 평행한 면은 모두 몇 쌍인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["계속 늘여도 만나지 않는 두 면은 평행, 만나는 두 면은 수직이에요.","앞·뒤, 위·아래, 왼쪽·오른쪽 — 평행한 면이 3쌍이에요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":["ㄱ","ㄹ","ㄴ","ㄷ","ㅁ","ㅇ","ㅂ","ㅅ"],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#6','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C6',1,'mc','auto','전개도를 접었을 때 면 다와 평행한 면은 어느 것인가요?',ARRAY['M5-2-u5-X12']::text[],true,'{"seq":6,"concept":"M5-2-u5-C6","difficulty":1,"kind":"mc","stem":"전개도를 접었을 때 면 다와 평행한 면은 어느 것인가요?","options":[{"t":"면 마","correct":true},{"t":"면 가","mis":"M5-2-u5-X12"},{"t":"면 나","mis":"M5-2-u5-X12"},{"t":"면 라","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 다와 평행한 면은 면 마예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,30],[0,60]],[[0,30],[30,30]],[[0,60],[90,60]],[[30,0],[30,30]],[[30,0],[60,0]],[[60,0],[60,30]],[[60,30],[120,30]],[[90,60],[90,90]],[[90,90],[120,90]],[[120,30],[120,90]]],"dash":[[[30,30],[30,60]],[[30,30],[60,30]],[[60,30],[60,60]],[[90,30],[90,60]],[[90,60],[120,60]]],"lab":[[[45.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[105.0,70.0],"바"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"전개도를 접었을 때 면 라와 평행한 면은 어느 것인가요?","options":[{"t":"면 나","correct":true},{"t":"면 가","mis":"M5-2-u5-X12"},{"t":"면 다","mis":"M5-2-u5-X12"},{"t":"면 마","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 라와 평행한 면은 면 나예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[75.0,70.0],"마"],[[105.0,70.0],"바"]]}],"tag":false}},{"stem":"전개도를 접었을 때 면 가와 평행한 면은 어느 것인가요?","options":[{"t":"면 바","correct":true},{"t":"면 나","mis":"M5-2-u5-X12"},{"t":"면 다","mis":"M5-2-u5-X12"},{"t":"면 라","mis":"M5-2-u5-X12"}],"explanation":["접었을 때 마주 보는 면이 평행한 면이에요.","한 줄로 이어진 네 면에서는 하나 건너 있는 면끼리 평행해요.","면 가와 평행한 면은 면 바예요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"가"],[[15.0,40.0],"나"],[[45.0,40.0],"다"],[[75.0,40.0],"라"],[[105.0,40.0],"마"],[[15.0,70.0],"바"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#7','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C7',1,'mc','auto','직육면체의 전개도를 그리려면 면을 몇 개 그려야 하나요?',ARRAY['M5-2-u5-X04','M5-2-u5-X14','M5-2-u5-X05']::text[],true,'{"seq":7,"concept":"M5-2-u5-C7","difficulty":1,"kind":"mc","stem":"직육면체의 전개도를 그리려면 면을 몇 개 그려야 하나요?","options":[{"t":"6개","correct":true},{"t":"4개","mis":"M5-2-u5-X04"},{"t":"5개","mis":"M5-2-u5-X14"},{"t":"12개","mis":"M5-2-u5-X05"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「6개」예요."],"variant_rule":{"alt":[{"stem":"한 모서리가 3 cm인 정육면체의 전개도에 그려야 하는 면은 어느 것인가요?","options":[{"t":"한 변이 3 cm인 정사각형 6개","correct":true},{"t":"가로 3 cm, 세로 6 cm인 직사각형 6개","mis":"M5-2-u5-X07"},{"t":"한 변이 3 cm인 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"한 변이 6 cm인 정사각형 6개","mis":"M5-2-u5-X07"}],"explanation":["정육면체의 면은 모두 크기가 같은 정사각형이에요.","한 모서리가 3 cm이니 한 변이 3 cm인 정사각형이에요.","면이 6개니 6개를 그려요."]},{"stem":"직육면체의 전개도를 그릴 때 접었을 때 맞붙는 두 모서리는 어떻게 그리나요?","options":[{"t":"길이가 같게 그린다","correct":true},{"t":"한쪽을 더 길게 그린다","mis":"M5-2-u5-X14"},{"t":"둘 다 점선으로 그린다","mis":"M5-2-u5-X16"},{"t":"하나만 그린다","mis":"M5-2-u5-X14"}],"explanation":["전개도에는 면 6개를 겹치지 않게 이어 그려요.","맞붙는 모서리는 길이가 같게, 마주 보는 면은 모양과 크기가 같게 그려요.","정답은 「길이가 같게 그린다」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#8','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C8',1,'sa','auto','주사위의 전개도예요. 전개도를 접었을 때 눈의 수 3과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M5-2-u5-C8","difficulty":1,"kind":"sa","stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 3과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 3과 마주 보는 면은 4예요.","그래서 4예요."],"mis":"M5-2-u5-X12","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"4"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 4와 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 4와 마주 보는 면은 3이에요.","그래서 3이에요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,60],[60,90]],[[60,90],[90,90]],[[90,60],[90,90]],[[90,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"2"],[[105.0,40.0],"4"],[[75.0,70.0],"1"]]}],"tag":false}},{"stem":"주사위의 전개도예요. 전개도를 접었을 때 눈의 수 1과 평행한 면의 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 줄로 이어진 네 면은 하나 건너 있는 면끼리 평행해요.","접어 보면 1과 마주 보는 면은 6이에요.","그래서 6이에요."],"asset":{"type":"geo","items":[{"w":