INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#9','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C2',2,'sa','auto','직육면체 모양 도시락통 4개의 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M5-2-u5-C2","difficulty":2,"kind":"sa","stem":"직육면체 모양 도시락통 4개의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체 하나의 면은 6개예요.","4개니 6 × 4 = 24예요.","그래서 모두 24개예요."],"mis":"M5-2-u5-X05","variant_rule":{"alt":[{"stem":"직육면체 모양 벽돌 5개의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["직육면체 하나의 모서리는 12개예요.","5개니 12 × 5 = 60이에요.","그래서 모두 60개예요."]},{"stem":"직육면체 모양 선물 상자 2개의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["직육면체 하나의 모서리는 12개예요.","2개니 12 × 2 = 24예요.","그래서 모두 24개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
