INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#11','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C4',2,'mc','auto','서랍 모양을 그린 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X09','M5-2-u5-X10']::text[],true,'{"seq":11,"concept":"M5-2-u5-C4","difficulty":2,"kind":"mc","stem":"서랍 모양을 그린 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?","options":[{"t":"보이는 모서리를 점선으로 그렸다","correct":true},{"t":"보이지 않는 모서리를 실선으로 그렸다","mis":"M5-2-u5-X09"},{"t":"보이지 않는 모서리를 그리지 않았다","mis":"M5-2-u5-X09"},{"t":"면을 7개 그렸다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 어떤 모서리가 어떻게 그려졌는지 살펴봐요.","잘못된 까닭은 「보이는 모서리를 점선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄴ","ㄷ"],["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"과일 상자 모양을 그린 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?","options":[{"t":"보이지 않는 모서리를 실선으로 그렸다","correct":true},{"t":"보이지 않는 모서리를 그리지 않았다","mis":"M5-2-u5-X10"},{"t":"보이는 모서리를 점선으로 그렸다","mis":"M5-2-u5-X10"},{"t":"면을 7개 그렸다","mis":"M5-2-u5-X10"}],"explanation":["겨냥도는 보이는 모서리를 실선, 보이지 않는 모서리를 점선으로 그려요.","그림에서 어떤 모서리가 어떻게 그려졌는지 살펴봐요.","잘못된 까닭은 「보이지 않는 모서리를 실선으로 그렸다」예요."],"asset":{"type":"geo","items":[{"w":132.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[132.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[110,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"캠핑 상자 모양을 그린 겨냥도예요. 이 겨냥도가 잘못된 까닭은 어느 것인가요?","options":