INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#14','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C6',2,'mc','auto','이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?',ARRAY['M5-2-u5-X14','M5-2-u5-X02']::text[],true,'{"seq":14,"concept":"M5-2-u5-C6","difficulty":2,"kind":"mc","stem":"이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"면이 5개뿐이다","correct":true},{"t":"접었을 때 겹치는 면이 있다","mis":"M5-2-u5-X14"},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「면이 5개뿐이다」예요."],"asset":{"type":"geo","items":[{"w":200,"h":60,"seg":[[[0,0],[0,20]],[[0,0],[200,0]],[[0,20],[100,20]],[[100,20],[100,60]],[[100,60],[160,60]],[[160,20],[160,60]],[[160,20],[200,20]],[[200,0],[200,20]]],"dash":[[[60,0],[60,20]],[[100,0],[100,20]],[[100,20],[160,20]],[[160,0],[160,20]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않게 접혀 직육면체를 둘러싸야 해요.","접은 모양을 떠올려 겹치는 면, 맞붙는 선분의 길이, 면의 수를 살펴봐요.","까닭은 「접었을 때 겹치는 면이 있다」예요."],"asset":{"type":"geo","items":[{"w":180,"h":30,"seg":[[[0,0],[0,30]],[[0,0],[180,0]],[[0,30],[180,30]],[[180,0],[180,30]]],"dash":[[[30,0],[30,30]],[[60,0],[60,30]],[[90,0],[90,30]],[[120,0],[120,30]],[[150,0],[150,30]]]}],"tag":false}},{"stem":"이번에는 다른 보기예요. 이 그림이 직육면체의 전개도가 될 수 없는 까닭은 어느 것인가요?","options":[{"t":"접었을 때 겹치는 면이 있다","correct":true},{"t":"접었을 때 만나는 선분의 길이가 다르다","mis":"M5-2-u5-X14"},{"t":"면이 5개뿐이다","mis":"M5-2-u5-X14"},{"t":"직사각형이 아닌 면이 있다","mis":"M5-2-u5-X02"}],"explanation":["전개도는 면 6개가 겹치지 않