INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#15','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C8',2,'sa','auto','명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M5-2-u5-C8","difficulty":2,"kind":"sa","stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 2가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 2와 평행한 면 5가 보이게 굴려요.","② 5와 수직인 면 1, 3, 4, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"4"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["① 6과 평행한 면 1이 보이게 굴려요.","② 1과 수직인 면 2, 3, 4, 5 가운데 가장 작은 수는 2예요.","그래서 2가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,60],[60,90]],[[60,90],[90,90]],[[90,60],[90,90]],[[90,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"2"],[[105.0,40.0],"4"],[[75.0,70.0],"1"]]}],"tag":false}},{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 1번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["① 4와 평행한 면 3이 보이게 굴려요.","② 3과 수직인 면 1, 2, 5, 6 가운데 가장 큰 수는 6이에요.","그래서 6이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#16','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C7',2,'sa','auto','한 모서리가 4 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M5-2-u5-C7","difficulty":2,"kind":"sa","stem":"한 모서리가 4 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["전개도의 둘레(실선)에는 한 변이 4 cm인 선분이 14개 있어요.","4 × 14 = 56이에요.","그래서 56 cm예요."],"mis":"M5-2-u5-X16","asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false},"variant_rule":{"alt":[{"stem":"한 모서리가 5 cm인 정육면체의 전개도를 그렸어요. 잘리지 않은 모서리(점선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["면 6개를 잇는 점선은 5개예요.","5 × 5 = 25예요.","그래서 25 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}},{"stem":"한 모서리가 2 cm인 정육면체의 전개도를 그렸어요. 잘린 모서리(실선)의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["전개도의 둘레(실선)에는 한 변이 2 cm인 선분이 14개 있어요.","2 × 14 = 28이에요.","그래서 28 cm예요."],"asset":{"type":"geo","items":[{"w":64,"h":48,"seg":[[[0,16],[0,32]],[[0,16],[16,16]],[[0,32],[16,32]],[[16,0],[16,16]],[[16,0],[32,0]],[[16,32],[16,48]],[[16,48],[32,48]],[[32,0],[32,16]],[[32,16],[64,16]],[[32,32],[32,48]],[[32,32],[64,32]],[[64,16],[64,32]]],"dash":[[[16,16],[16,32]],[[16,16],[32,16]],[[16,32],[32,32]],[[32,16],[32,32]],[[48,16],[48,32]]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#17','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C2',3,'sa','auto','가로 3 cm, 세로 2 cm, 높이 2 cm인 직육면체 모양 도시락통의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":17,"concept":"M5-2-u5-C2","difficulty":3,"kind":"sa","stem":"가로 3 cm, 세로 2 cm, 높이 2 cm인 직육면체 모양 도시락통의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","3 × 4 + 2 × 4 + 2 × 4 = 28이에요.","그래서 28 cm예요."],"mis":"M5-2-u5-X07","asset":{"type":"geo","items":[{"w":88.0,"h":66.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[88.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[66,22.0,"sw"],"ㅁ":[22.0,44,"ne"],"ㅇ":[88.0,44,"e"],"ㅂ":[0,66.0,"sw"],"ㅅ":[66,66.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[33.0,74.0],"3 cm"],[[93.0,59.0],"2 cm"],[[48,44.0],"2 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 서랍의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","4 × 4 + 3 × 4 + 2 × 4 = 36이에요.","그래서 36 cm예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,85.0],"4 cm"],[[120.5,64.5],"3 cm"],[[70,55.0],"2 cm"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 3 cm, 높이 3 cm인 직육면체 모양 캠핑 상자의 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["직육면체에는 길이가 같은 모서리가 4개씩 3묶음 있어요.","5 × 4 + 3 × 4 + 3 × 4 = 44예요.","그래서 44 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,107.0],"5 cm"],[[142.5,86.5],"3 cm"],[[92,66.0],"3 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#18','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C3',3,'sa','auto','모서리의 길이가 8 cm, 11 cm, 6 cm인 직육면체 모양 나무 토막을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M5-2-u5-C3","difficulty":3,"kind":"sa","stem":"모서리의 길이가 8 cm, 11 cm, 6 cm인 직육면체 모양 나무 토막을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 6 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 6 cm예요."],"mis":"M5-2-u5-X08","variant_rule":{"alt":[{"stem":"모서리의 길이가 20 cm, 14 cm, 16 cm인 직육면체 모양 케이크를 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 14 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 14 cm예요."]},{"stem":"모서리의 길이가 15 cm, 7 cm, 7 cm인 직육면체 모양 빵을 잘라 가장 큰 정육면체를 만들려고 해요. 정육면체의 한 모서리의 길이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["정육면체는 모든 모서리의 길이가 같아야 해요.","가장 짧은 모서리 7 cm보다 길게 자를 수는 없어요.","그래서 한 모서리는 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
