INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#21','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C8',3,'sa','auto','명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 7번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 4가 보이게 놓고 시작해 7번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["몇 번만 실행해 보면 4 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 7번 실행하면 6이 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,30]],[[0,0],[60,0]],[[0,30],[30,30]],[[30,30],[30,60]],[[30,60],[60,60]],[[60,0],[60,30]],[[60,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[30,0],[30,30]],[[30,30],[60,30]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"1"],[[45.0,10.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"6"],[[75.0,70.0],"2"],[[105.0,70.0],"4"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 3이 보이게 놓고 시작해 10번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 3 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 10번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,60],[60,90]],[[60,90],[90,90]],[[90,60],[90,90]],[[90,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"2"],[[105.0,40.0],"4"],[[75.0,70.0],"1"]]}],"tag":false}},{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["몇 번만 실행해 보면 1 → 2 → 1 → 2 → 1이에요.","2번마다 처음 수로 되풀이돼요.","그래서 6번 실행하면 1이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#22','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C4',3,'sa','auto','가로 4 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겨냥도예요. 점선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"가로 4 cm, 세로 4 cm, 높이 5 cm인 직육면체의 겨냥도예요. 점선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["점선 3개는 보이지 않는 꼭짓점에서 만나는 가로, 세로, 높이 하나씩이에요.","4 + 4 + 5 = 13이에요.","그래서 13 cm예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":132.0,"h":154.0,"pts":{"ㄱ":[44.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,44.0,"w"],"ㄷ":[88,44.0,"sw"],"ㅁ":[44.0,110,"ne"],"ㅇ":[132.0,110,"e"],"ㅂ":[0,154.0,"sw"],"ㅅ":[88,154.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[44.0,162.0],"4 cm"],[[126.0,136.0],"4 cm"],[[70,99.0],"5 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 7 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["모든 모서리의 합은 7 × 4 + 2 × 4 + 3 × 4 = 48이에요.","점선 3개는 7 + 2 + 3 = 12예요.","실선은 48 − 12 = 36(cm)예요."],"asset":{"type":"geo","items":[{"w":176.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[176.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[154,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[176.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[154,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[77.0,96.0],"7 cm"],[[181.0,81.0],"2 cm"],[[136,55.0],"3 cm"]]}],"tag":false}},{"stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겨냥도예요. 점선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["점선 3개는 보이지 않는 꼭짓점에서 만나는 가로, 세로, 높이 하나씩이에요.","5 + 3 + 4 = 12예요.","그래서 12 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#23','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C4',4,'essay','teacher','친구가 그린 그림이에요. 이 그림이 직육면체의 겨냥도로 알맞은지 판단하고, 알맞지 않다면 어떻게 고쳐야 하는지와 겨냥도를 그렇게 그리는 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u5-C4","difficulty":4,"kind":"essay","stem":"친구가 그린 그림이에요. 이 그림이 직육면체의 겨냥도로 알맞은지 판단하고, 알맞지 않다면 어떻게 고쳐야 하는지와 겨냥도를 그렇게 그리는 까닭을 쓰세요.","answer_guide":{"answer":"예: 알맞지 않다. 보이지 않는 모서리 3개를 실선으로 그려서 어느 쪽이 앞인지 알 수 없다. 보이지 않는 모서리 3개는 점선으로 고쳐 그려야 한다. 겨냥도는 그림만 보고도 다른 사람이 입체의 모양을 알아맞힐 수 있게 그리는 그림이기 때문이다.","scoring_points":["알맞지 않다고 판단했는가","보이지 않는 모서리 3개를 점선으로 고친다고 썼는가","다른 사람이 입체를 알아볼 수 있게 하려는 까닭을 썼는가"]},"explanation":["보이는 모서리 9개는 실선이에요.","보이지 않는 모서리 3개는 점선이어야 해요.","그래야 그림만 보고도 앞뒤를 알 수 있어요."],"asset":{"type":"geo","items":[{"w":110.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[110.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[88,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[110.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[88,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"],["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#24','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C6',4,'essay','teacher','면이 6개인 그림이에요. 친구가 「면이 6개니까 직육면체의 전개도야.」라고 했어요. 친구의 말이 맞는지 판단하고, 전개도가 되려면 무엇을 따져 보아야 하는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u5-C6","difficulty":4,"kind":"essay","stem":"면이 6개인 그림이에요. 친구가 「면이 6개니까 직육면체의 전개도야.」라고 했어요. 친구의 말이 맞는지 판단하고, 전개도가 되려면 무엇을 따져 보아야 하는지 쓰세요.","answer_guide":{"answer":"예: 친구의 말은 틀렸다. 이 그림은 접었을 때 두 면이 같은 자리에서 겹쳐 한쪽이 비므로 전개도가 아니다. 전개도가 되려면 면의 수뿐 아니라 접었을 때 겹치는 면이 없는지, 맞붙는 두 선분의 길이가 같은지를 따져 보아야 한다.","scoring_points":["틀렸다고 판단했는가","접었을 때 겹치는 면이 있다고 썼는가","겹치는 면·맞붙는 선분의 길이를 따져야 한다고 썼는가"]},"explanation":["접은 모양을 떠올려요.","위쪽에 붙은 두 면이 같은 자리에서 겹쳐요.","면의 수뿐 아니라 겹침과 맞붙는 길이를 따져요."],"asset":{"type":"geo","items":[{"w":120,"h":60,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[120,60]],[[30,0],[30,30]],[[30,30],[60,30]],[[60,0],[60,30]],[[60,0],[90,0]],[[90,0],[90,30]],[[90,30],[120,30]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,30],[90,30]],[[90,30],[90,60]]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_c#25','math',5,2,'u5','','g5_2_math_u5_review_c','unit_review','M5-2-u5-C2',4,'sa','auto','길이가 50 cm인 철사를 겹치지 않게 모두 써서 가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u5-C2","difficulty":4,"kind":"sa","stem":"길이가 50 cm인 철사를 겹치지 않게 모두 써서 가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","6 × 4 + 2 × 4 + 3 × 4 = 44예요.","남는 철사는 50 − 44 = 6(cm)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"길이가 40 cm인 철사를 겹치지 않게 모두 써서 가로 3 cm, 세로 3 cm, 높이 3 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","3 × 4 + 3 × 4 + 3 × 4 = 36이에요.","남는 철사는 40 − 36 = 4(cm)예요."]},{"stem":"길이가 50 cm인 철사를 겹치지 않게 모두 써서 가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","5 × 4 + 3 × 4 + 2 × 4 = 40이에요.","남는 철사는 50 − 40 = 10(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_d#1','math',5,2,'u5','','g5_2_math_u5_review_d','unit_review','M5-2-u5-C2',1,'sa','auto','직육면체 모양 과일 상자의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M5-2-u5-C2","difficulty":1,"kind":"sa","stem":"직육면체 모양 과일 상자의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["12"],"explanation":["보이는 모서리 9개와 보이지 않는 모서리 3개가 있어요.","9 + 3 = 12예요.","그래서 모서리는 12개예요."],"mis":"M5-2-u5-X04","asset":{"type":"geo","items":[{"w":132.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[132.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[110,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[132.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[110,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"직육면체 모양 캠핑 상자의 모서리는 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["12"],"explanation":["보이는 모서리 9개와 보이지 않는 모서리 3개가 있어요.","9 + 3 = 12예요.","그래서 모서리는 12개예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[143.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[110,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"직육면체 모양 서랍의 꼭짓점은 모두 몇 개인가요? 보이지 않는 곳까지 세어 숫자로 쓰세요.","answer":["8"],"explanation":["윗면에 4개, 아랫면에 4개가 있어요.","4 + 4 = 8이에요.","그래서 꼭짓점은 8개예요."],"asset":{"type":"geo","items":[{"w":121.0,"h":77.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[121.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[88,33.0,"sw"],"ㅁ":[33.0,44,"ne"],"ㅇ":[121.0,44,"e"],"ㅂ":[0,77.0,"sw"],"ㅅ":[88,77.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_d#2','math',5,2,'u5','','g5_2_math_u5_review_d','unit_review','M5-2-u5-C3',1,'mc','auto','정육면체의 면이 될 수 있는 사각형은 어느 것인가요?',ARRAY['M5-2-u5-X02']::text[],true,'{"seq":2,"concept":"M5-2-u5-C3","difficulty":1,"kind":"mc","stem":"정육면체의 면이 될 수 있는 사각형은 어느 것인가요?","options":[{"t":"네 변이 모두 3 cm이고 네 각이 모두 직각인 사각형","correct":true},{"t":"가로 3 cm, 세로 2 cm인 직사각형","mis":"M5-2-u5-X02"},{"t":"네 변이 모두 3 cm이지만 직각이 없는 사각형","mis":"M5-2-u5-X02"},{"t":"윗변 2 cm, 아랫변 3 cm인 사다리꼴","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 모든 모서리의 길이가 같아요.","그래서 면 6개가 모두 크기가 같은 정사각형이에요.","정답은 「네 변이 모두 3 cm이고 네 각이 모두 직각인 사각형」이에요."],"variant_rule":{"alt":[{"stem":"정사각형 6개로 둘러싸인 입체도형을 무엇이라고 하나요?","options":[{"t":"정육면체","correct":true},{"t":"삼각뿔","mis":"M5-2-u5-X02"},{"t":"정사각형","mis":"M5-2-u5-X01"},{"t":"평면도형","mis":"M5-2-u5-X01"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「정육면체」예요."],"asset":{"type":"geo","items":[{"w":99.0,"h":99.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[99.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[66,33.0,"sw"],"ㅁ":[33.0,66,"ne"],"ㅇ":[99.0,66,"e"],"ㅂ":[0,99.0,"sw"],"ㅅ":[66,99.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]]}],"tag":false}},{"stem":"정육면체는 어떤 도형으로 둘러싸인 입체도형인가요?","options":[{"t":"크기가 같은 정사각형 6개","correct":true},{"t":"직사각형 4개와 정사각형 2개","mis":"M5-2-u5-X02"},{"t":"크기가 같은 정사각형 4개","mis":"M5-2-u5-X04"},{"t":"크기가 다른 직사각형 6개","mis":"M5-2-u5-X02"}],"explanation":["정육면체는 면이 모두 정사각형이에요.","정사각형 6개로 둘러싸인 입체도형이 정육면체예요.","정답은 「크기가 같은 정사각형 6개」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_