INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_d#21','math',5,2,'u5','','g5_2_math_u5_review_d','unit_review','M5-2-u5-C8',3,'sa','auto','명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 3이 보이게 놓고 시작해 10번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M5-2-u5-C8","difficulty":3,"kind":"sa","stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 3이 보이게 놓고 시작해 10번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 3 → 6 → 5 → 6 → 5예요.","2번째부터 2번마다 되풀이돼요.","그래서 10번 실행하면 5가 보여요."],"mis":"M5-2-u5-X17","asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[120,30]],[[60,60],[60,90]],[[60,90],[90,90]],[[90,60],[90,90]],[[90,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"5"],[[45.0,40.0],"3"],[[75.0,40.0],"2"],[[105.0,40.0],"4"],[[75.0,70.0],"1"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 1이 보이게 놓고 시작해 6번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["몇 번만 실행해 보면 1 → 2 → 1 → 2 → 1이에요.","2번마다 처음 수로 되풀이돼요.","그래서 6번 실행하면 1이 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}},{"stem":"명령 카드 — ① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 큰 면이 보이게 굴리기 — 이 두 명령을 한 번으로 셉니다. 주사위의 전개도를 보고, 눈의 수 6이 보이게 놓고 시작해 9번 실행하면 보이는 눈의 수는 얼마인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["몇 번만 실행해 보면 6 → 5 → 6 → 5 → 6이에요.","2번마다 처음 수로 되풀이돼요.","그래서 9번 실행하면 5가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,60]],[[0,0],[30,0]],[[0,60],[60,60]],[[30,0],[30,30]],[[30,30],[90,30]],[[60,60],[60,90]],[[60,90],[120,90]],[[90,30],[90,60]],[[90,60],[120,60]],[[120,60],[120,90]]],"dash":[[[0,30],[30,30]],[[30,30],[30,60]],[[60,30],[60,60]],[[60,60],[90,60]],[[90,60],[90,90]]],"lab":[[[15.0,10.0],"6"],[[15.0,40.0],"2"],[[45.0,40.0],"4"],[[75.0,40.0],"5"],[[75.0,70.0],"1"],[[105.0,70.0],"3"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_d#22','math',5,2,'u5','','g5_2_math_u5_review_d','unit_review','M5-2-u5-C4',3,'sa','auto','가로 7 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":22,"concept":"M5-2-u5-C4","difficulty":3,"kind":"sa","stem":"가로 7 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["모든 모서리의 합은 7 × 4 + 2 × 4 + 3 × 4 = 48이에요.","점선 3개는 7 + 2 + 3 = 12예요.","실선은 48 − 12 = 36(cm)예요."],"mis":"M5-2-u5-X10","asset":{"type":"geo","items":[{"w":176.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[176.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[154,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[176.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[154,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[77.0,96.0],"7 cm"],[[181.0,81.0],"2 cm"],[[136,55.0],"3 cm"]]}],"tag":false},"variant_rule":{"alt":[{"stem":"가로 5 cm, 세로 3 cm, 높이 4 cm인 직육면체의 겨냥도예요. 점선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["점선 3개는 보이지 않는 꼭짓점에서 만나는 가로, 세로, 높이 하나씩이에요.","5 + 3 + 4 = 12예요.","그래서 12 cm예요."],"asset":{"type":"geo","items":[{"w":143.0,"h":121.0,"pts":{"ㄱ":[33.0,0,"nw"],"ㄹ":[143.0,0,"ne"],"ㄴ":[0,33.0,"w"],"ㄷ":[110,33.0,"sw"],"ㅁ":[33.0,88,"ne"],"ㅇ":[143.0,88,"e"],"ㅂ":[0,121.0,"sw"],"ㅅ":[110,121.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[55.0,129.0],"5 cm"],[[142.5,108.5],"3 cm"],[[92,77.0],"4 cm"]]}],"tag":false}},{"stem":"가로 6 cm, 세로 2 cm, 높이 3 cm인 직육면체의 겨냥도예요. 실선으로 그린 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["33"],"explanation":["모든 모서리의 합은 6 × 4 + 2 × 4 + 3 × 4 = 44예요.","점선 3개는 6 + 2 + 3 = 11이에요.","실선은 44 − 11 = 33(cm)예요."],"asset":{"type":"geo","items":[{"w":154.0,"h":88.0,"pts":{"ㄱ":[22.0,0,"nw"],"ㄹ":[154.0,0,"ne"],"ㄴ":[0,22.0,"w"],"ㄷ":[132,22.0,"sw"],"ㅁ":[22.0,66,"ne"],"ㅇ":[154.0,66,"e"],"ㅂ":[0,88.0,"sw"],"ㅅ":[132,88.0,"s"]},"show":[],"seg":[["ㄱ","ㄴ"],["ㄴ","ㄷ"],["ㄷ","ㄹ"],["ㄹ","ㄱ"],["ㄴ","ㅂ"],["ㄷ","ㅅ"],["ㄹ","ㅇ"],["ㅂ","ㅅ"],["ㅅ","ㅇ"]],"dash":[["ㄱ","ㅁ"],["ㅁ","ㅂ"],["ㅁ","ㅇ"]],"lab":[[[66.0,96.0],"6 cm"],[[159.0,81.0],"2 cm"],[[114,55.0],"3 cm"]]}],"tag":false}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_d#23','math',5,2,'u5','','g5_2_math_u5_review_d','unit_review','M5-2-u5-C5',4,'essay','teacher','과일 가게 삼촌이 상자를 눕혀 놓고 「바닥에 닿은 면이 아니니까 옆에 선 두 면은 밑면이 될 수 없어.」라고 했어요. 이 말이 맞는지 판단하고, 밑면과 옆면의 뜻을 넣어 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"M5-2-u5-C5","difficulty":4,"kind":"essay","stem":"과일 가게 삼촌이 상자를 눕혀 놓고 「바닥에 닿은 면이 아니니까 옆에 선 두 면은 밑면이 될 수 없어.」라고 했어요. 이 말이 맞는지 판단하고, 밑면과 옆면의 뜻을 넣어 까닭을 쓰세요.","answer_guide":{"answer":"예: 이 말은 틀렸다. 밑면은 놓인 위치가 아니라 서로 평행한 두 면을 말한다. 옆에 선 두 면도 서로 평행하므로 밑면이 될 수 있다. 그때 이 두 면과 수직으로 만나는 나머지 4개의 면이 옆면이 된다.","scoring_points":["틀렸다고 판단했는가","밑면은 서로 평행한 두 면이라고 썼는가","옆면은 밑면과 수직인 면 4개라고 썼는가"]},"explanation":["밑면은 위치가 아니라 평행한 관계로 정해요.","옆에 선 두 면도 평행하면 밑면이에요.","밑면과 수직인 4개의 면이 옆면이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_d#24','math',5,2,'u5','','g5_2_math_u5_review_d','unit_review','M5-2-u5-C8',4,'essay','teacher','주사위 전개도를 보고 눈의 수 1에서 시작해 「① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기」를 99번 반복하려고 해요. 끝까지 굴리지 않고 결과를 구하는 방법과 결과를 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M5-2-u5-C8","difficulty":4,"kind":"essay","stem":"주사위 전개도를 보고 눈의 수 1에서 시작해 「① 보이는 면과 평행한 면이 보이게 굴리기 ② 보이는 면과 수직인 면 가운데 눈의 수가 가장 작은 면이 보이게 굴리기」를 99번 반복하려고 해요. 끝까지 굴리지 않고 결과를 구하는 방법과 결과를 쓰세요.","answer_guide":{"answer":"예: 1에서 시작하면 평행한 6으로 굴린 뒤 6과 수직인 2, 3, 4, 5 가운데 가장 작은 2가 보인다. 2에서는 평행한 5로 굴린 뒤 1, 3, 4, 6 가운데 가장 작은 1이 보인다. 그래서 1 → 2 → 1 → 2로 2번마다 되풀이된다. 99번은 홀수 번이므로 2가 보인다.","scoring_points":["1번·2번 실행 결과(2, 1)을 구했는가","2번마다 되풀이되는 규칙을 찾았는가","홀수 번이라 2라고 결론지었는가"]},"explanation":["1 → 2, 2 → 1로 바뀌어요.","2번마다 처음 수로 되풀이돼요.","99번은 홀수 번이라 2가 보여요."],"asset":{"type":"geo","items":[{"w":120,"h":90,"seg":[[[0,0],[0,90]],[[0,0],[30,0]],[[0,90],[30,90]],[[30,0],[30,30]],[[30,30],[120,30]],[[30,60],[30,90]],[[30,60],[120,60]],[[120,30],[120,60]]],"dash":[[[0,30],[30,30]],[[0,60],[30,60]],[[30,30],[30,60]],[[60,30],[60,60]],[[90,30],[90,60]]],"lab":[[[15.0,10.0],"1"],[[15.0,40.0],"2"],[[45.0,40.0],"3"],[[75.0,40.0],"5"],[[105.0,40.0],"4"],[[15.0,70.0],"6"]]}],"tag":false}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g5_2_math_u5_review_d#25','math',5,2,'u5','','g5_2_math_u5_review_d','unit_review','M5-2-u5-C2',4,'sa','auto','길이가 40 cm인 철사를 겹치지 않게 모두 써서 가로 3 cm, 세로 3 cm, 높이 3 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":25,"concept":"M5-2-u5-C2","difficulty":4,"kind":"sa","stem":"길이가 40 cm인 철사를 겹치지 않게 모두 써서 가로 3 cm, 세로 3 cm, 높이 3 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","3 × 4 + 3 × 4 + 3 × 4 = 36이에요.","남는 철사는 40 − 36 = 4(cm)예요."],"mis":"M5-2-u5-X07","variant_rule":{"alt":[{"stem":"길이가 50 cm인 철사를 겹치지 않게 모두 써서 가로 5 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","5 × 4 + 3 × 4 + 2 × 4 = 40이에요.","남는 철사는 50 − 40 = 10(cm)예요."]},{"stem":"길이가 40 cm인 철사를 겹치지 않게 모두 써서 가로 4 cm, 세로 3 cm, 높이 2 cm인 직육면체 모양 틀을 만들려고 해요. 틀을 만들고 남는 철사는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["틀에 드는 철사는 모든 모서리의 길이의 합이에요.","4 × 4 + 3 × 4 + 2 × 4 = 36이에요.","남는 철사는 40 − 36 = 4(cm)예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
